'use client';

import { useState, useEffect } from 'react';
import { TradingChartContainer } from '@/components/charts/TradingChartContainer';

/**
 * 案例數據結構
 */
interface CaseRecord {
  case_id: string;
  symbol: string;
  timeframe: string;
  timestamp: number;
  positive_case: boolean;
  details?: {
    close?: number;
    volume?: number;
    timestamp_str?: string;
  };
}

/**
 * 案例列表API響應
 * 注意：後端直接返回數據，沒有 success/data/error 包裹層
 */
interface CaseListResponse {
  total: number;
  cases: CaseRecord[];
  positive_count: number;
  negative_count: number;
  symbols: string[];
  timeframes: string[];
}

/**
 * 案例類型選項
 */
type CaseTypeFilter = 'all' | 'positive' | 'negative';

/**
 * 生產環境圖表頁面
 *
 * 功能：
 * 1. 從案例列表加載可用數據
 * 2. Symbol選擇器
 * 3. 時間戳選擇器（根據選擇的symbol和案例類型過濾）
 * 4. 案例類型過濾器（全部/正例/反例）
 * 5. 圖表渲染
 */
export default function ChartPage() {
  // 狀態管理
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // 案例數據
  const [caseList, setCaseList] = useState<CaseRecord[]>([]);
  const [availableSymbols, setAvailableSymbols] = useState<string[]>([]);

  // 所有支援的時間框架（固定列表，與案例時間框架獨立）
  const availableTimeframes = ['1m', '5m', '15m', '30m', '1h', '4h', '12h', '1d'];

  // 用戶選擇
  const [selectedSymbol, setSelectedSymbol] = useState<string>('');
  const [selectedTimestamp, setSelectedTimestamp] = useState<number | null>(null);
  const [selectedTimeframe, setSelectedTimeframe] = useState<string>('1h'); // 預設1h
  const [caseTypeFilter, setCaseTypeFilter] = useState<CaseTypeFilter>('all');

  // 當前選擇案例的詳細信息
  const [currentCase, setCurrentCase] = useState<CaseRecord | null>(null);

  // K線數據（用於三個圖表組件）
  const [klineData, setKlineData] = useState<unknown[]>([]);
  const [loadingKlines, setLoadingKlines] = useState(false);
  const [klineError, setKlineError] = useState<string | null>(null);
  const [alignedCaseTimestamp, setAlignedCaseTimestamp] = useState<number | null>(null);
  const [alignedTcTimestamp, setAlignedTcTimestamp] = useState<number | null>(null);

  /**
   * 加載案例列表數據
   */
  useEffect(() => {
    const fetchCaseList = async () => {
      try {
        setLoading(true);
        setError(null);

        const response = await fetch('http://localhost:8000/api/v1/case/list');

        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        const result: CaseListResponse = await response.json();

        // 後端直接返回數據，無需檢查 success 字段
        // 設置案例數據
        setCaseList(result.cases);
        setAvailableSymbols(result.symbols);

        // NOTE: 不再從案例列表獲取timeframes，使用固定的所有支援時間框架
        // availableTimeframes 已在上方定義為常量

        // 自動選擇第一個symbol
        if (result.symbols.length > 0) {
          setSelectedSymbol(result.symbols[0]);
        }

        // selectedTimeframe 已預設為 '1h'，不需要從案例設定

      } catch (err) {
        console.error('Failed to fetch case list:', err);
        setError(err instanceof Error ? err.message : '加載案例列表時發生錯誤');
      } finally {
        setLoading(false);
      }
    };

    fetchCaseList();
  }, []);

  /**
   * 根據當前選擇過濾可用的案例
   */
  const filteredCases = caseList.filter(c => {
    // 過濾symbol
    if (selectedSymbol && c.symbol !== selectedSymbol) {
      return false;
    }

    // 過濾案例類型
    if (caseTypeFilter === 'positive' && !c.positive_case) {
      return false;
    }
    if (caseTypeFilter === 'negative' && c.positive_case) {
      return false;
    }

    return true;
  });

  /**
   * 當symbol或案例類型改變時，重置timestamp選擇
   */
  useEffect(() => {
    if (filteredCases.length > 0) {
      // 自動選擇第一個可用的timestamp
      const firstCase = filteredCases[0];
      setSelectedTimestamp(firstCase.timestamp);
      setCurrentCase(firstCase);
    } else {
      setSelectedTimestamp(null);
      setCurrentCase(null);
    }
  }, [selectedSymbol, caseTypeFilter]);

  /**
   * 當timestamp選擇改變時，更新當前案例
   */
  useEffect(() => {
    if (selectedTimestamp !== null) {
      const foundCase = filteredCases.find(c => c.timestamp === selectedTimestamp);
      setCurrentCase(foundCase || null);
    }
  }, [selectedTimestamp, filteredCases]);

  /**
   * 獲取K線數據（當symbol/timestamp/timeframe改變時）
   */
  useEffect(() => {
    if (!selectedSymbol || selectedTimestamp === null || !selectedTimeframe || !currentCase) {
      return;
    }

    const fetchKlineData = async () => {
      try {
        setLoadingKlines(true);
        setKlineError(null);
        setAlignedCaseTimestamp(null);
        setAlignedTcTimestamp(null);

        // 添加 case_timeframe 參數（從當前案例獲取）
        const caseTimeframe = currentCase.timeframe;

        // 從localStorage讀取lookback/forward參數（批量下載時保存的值）
        const lookbackBars = localStorage.getItem('kline_lookback_bars') || '100';
        const forwardBars = localStorage.getItem('kline_forward_bars') || '48';

        const url = `http://localhost:8000/api/v1/chart/data?symbol=${selectedSymbol}&case_timestamp=${selectedTimestamp}&timeframe=${selectedTimeframe}&case_timeframe=${caseTimeframe}&max_bars=200&lookback_bars=${lookbackBars}&forward_bars=${forwardBars}`;

        console.log(`[ChartPage] Fetching klines: case_tf=${caseTimeframe}, view_tf=${selectedTimeframe}, lookback=${lookbackBars}, forward=${forwardBars}`);

        const response = await fetch(url);

        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        const result = await response.json();

        if (!result.success || !result.data) {
          throw new Error(result.error?.message || '獲取K線數據失敗');
        }

        setKlineData(result.data.klines);

        const resolvedCaseTimestamp = result.data.aligned_case_timestamp ?? selectedTimestamp;
        const resolvedTcTimestamp = result.data.aligned_tc_timestamp ?? null;
        setAlignedCaseTimestamp(resolvedCaseTimestamp ?? null);
        setAlignedTcTimestamp(resolvedTcTimestamp);

        console.log(
          `[ChartPage] Loaded ${result.data.klines.length} klines, ` +
          `TO at ${result.data.to_index}, TC at ${result.data.tc_index}, ` +
          `case_bars=${result.data.case_bars}, ` +
          `aligned_to=${resolvedCaseTimestamp}, ` +
          `aligned_tc=${resolvedTcTimestamp}`
        );

      } catch (err) {
        console.error('Failed to fetch kline data:', err);
        setKlineError(err instanceof Error ? err.message : '獲取K線數據時發生錯誤');
        setKlineData([]);
        setAlignedCaseTimestamp(null);
        setAlignedTcTimestamp(null);
      } finally {
        setLoadingKlines(false);
      }
    };

    fetchKlineData();
  }, [selectedSymbol, selectedTimestamp, selectedTimeframe, currentCase]);

  /**
   * 格式化時間戳為可讀格式（UTC時間）
   * 注意：顯示UTC時間以與API數據保持一致，避免時區轉換混淆
   */
  const formatTimestamp = (timestamp: number): string => {
    const date = new Date(timestamp * 1000);
    // 使用 UTC 時間格式，與後端 API 的 timestamp 保持一致
    const year = date.getUTCFullYear();
    const month = String(date.getUTCMonth() + 1).padStart(2, '0');
    const day = String(date.getUTCDate()).padStart(2, '0');
    const hours = String(date.getUTCHours()).padStart(2, '0');
    const minutes = String(date.getUTCMinutes()).padStart(2, '0');
    const seconds = String(date.getUTCSeconds()).padStart(2, '0');
    return `${year}-${month}-${day} ${hours}:${minutes}:${seconds} UTC`;
  };

  /**
   * 渲染加載狀態
   */
  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-slate-950/40">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-emerald-400 mx-auto mb-4"></div>
          <p className="text-slate-300">加載案例數據中...</p>
        </div>
      </div>
    );
  }

  /**
   * 渲染錯誤狀態
   */
  if (error) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-slate-950/40">
        <div className="glass-panel border border-rose-500/40 rounded-lg p-6 max-w-md">
          <h2 className="text-rose-200 text-lg font-semibold mb-2">加載失敗</h2>
          <p className="text-rose-200/80">{error}</p>
          <button
            onClick={() => window.location.reload()}
            className="mt-4 px-4 py-2 bg-rose-500/20 text-rose-100 rounded border border-rose-400/40 hover:bg-rose-500/30 transition-colors"
          >
            重新加載
          </button>
        </div>
      </div>
    );
  }

  /**
   * 渲染無數據狀態
   */
  if (caseList.length === 0) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-slate-950/40">
        <div className="glass-panel border border-amber-400/40 rounded-lg p-6 max-w-md">
          <h2 className="text-amber-200 text-lg font-semibold mb-2">暫無數據</h2>
          <p className="text-amber-200/80">
            尚未導入任何案例數據。請先使用 Phase 1 功能導入案例CSV並下載K線數據。
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="container mx-auto px-4 py-6">
      {/* 頁面標題 */}
      <div className="mb-6">
        <h1 className="text-3xl font-semibold text-slate-100 mb-2">圖表查看</h1>
        <p className="text-slate-400">選擇案例查看K線圖表</p>
      </div>

      {/* 控制面板 */}
      <div className="glass-panel rounded-xl p-6 mb-6">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">

          {/* Symbol選擇器 */}
          <div>
            <label className="block text-sm font-medium text-slate-300 mb-2">
              交易對
            </label>
            <select
              value={selectedSymbol}
              onChange={(e) => setSelectedSymbol(e.target.value)}
              className="w-full px-3 py-2 border border-slate-700 rounded-md text-slate-100 bg-slate-900/60 focus:outline-none focus:ring-2 focus:ring-emerald-400/40"
            >
              {availableSymbols.map(symbol => (
                <option key={symbol} value={symbol}>{symbol}</option>
              ))}
            </select>
          </div>

          {/* 案例類型過濾器 */}
          <div>
            <label className="block text-sm font-medium text-slate-300 mb-2">
              案例類型
            </label>
            <select
              value={caseTypeFilter}
              onChange={(e) => setCaseTypeFilter(e.target.value as CaseTypeFilter)}
              className="w-full px-3 py-2 border border-slate-700 rounded-md text-slate-100 bg-slate-900/60 focus:outline-none focus:ring-2 focus:ring-emerald-400/40"
            >
              <option value="all">全部</option>
              <option value="positive">正例</option>
              <option value="negative">反例</option>
            </select>
          </div>

          {/* 時間框架選擇器 */}
          <div>
            <label className="block text-sm font-medium text-slate-300 mb-2">
              時間框架（查看用）
            </label>
            <select
              value={selectedTimeframe}
              onChange={(e) => setSelectedTimeframe(e.target.value)}
              className="w-full px-3 py-2 border border-slate-700 rounded-md text-slate-100 bg-slate-900/60 focus:outline-none focus:ring-2 focus:ring-emerald-400/40"
            >
              {availableTimeframes.map(tf => (
                <option key={tf} value={tf}>{tf}</option>
              ))}
            </select>
            <p className="text-xs text-slate-500 mt-1">與案例搜尋時間框架獨立</p>
          </div>

          {/* 時間戳選擇器 */}
          <div>
            <label className="block text-sm font-medium text-slate-300 mb-2">
              案例時間點 ({filteredCases.length} 個可用)
            </label>
            <select
              value={selectedTimestamp || ''}
              onChange={(e) => setSelectedTimestamp(Number(e.target.value))}
              className="w-full px-3 py-2 border border-slate-700 rounded-md text-slate-100 bg-slate-900/60 focus:outline-none focus:ring-2 focus:ring-emerald-400/40"
              disabled={filteredCases.length === 0}
            >
              {filteredCases.map(c => (
                <option key={c.case_id} value={c.timestamp}>
                  {formatTimestamp(c.timestamp)} {c.positive_case ? '✓' : '✗'}
                </option>
              ))}
            </select>
            <p className="text-xs text-slate-500 mt-1">💡 顯示UTC時間（與API數據一致），非本地時區</p>
          </div>
        </div>

        {/* 當前案例信息 */}
        {currentCase && (
          <div className="mt-4 pt-4 border-t border-slate-800/80">
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
              <div>
                <span className="text-slate-400">案例ID：</span>
                <span className="font-mono text-slate-100">{currentCase.case_id}</span>
              </div>
              <div>
                <span className="text-slate-400">類型：</span>
                <span className={`font-semibold ${currentCase.positive_case ? 'text-emerald-400' : 'text-rose-400'}`}>
                  {currentCase.positive_case ? '正例 ✓' : '反例 ✗'}
                </span>
              </div>
              {currentCase.details?.close && (
                <div>
                  <span className="text-slate-400">收盤價：</span>
                  <span className="font-mono text-slate-100">{currentCase.details.close}</span>
                </div>
              )}
              {currentCase.details?.volume && (
                <div>
                  <span className="text-slate-400">成交量：</span>
                  <span className="font-mono text-slate-100">{currentCase.details.volume.toLocaleString()}</span>
                </div>
              )}
            </div>
          </div>
        )}
      </div>

      {/* 圖表區域 - 使用 TradingChartContainer（自帶同步功能） */}
      {selectedTimestamp !== null ? (
        loadingKlines ? (
          <div className="flex items-center justify-center glass-panel rounded-xl" style={{ height: '640px' }}>
            <div className="text-center">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-emerald-400 mx-auto mb-2"></div>
              <p className="text-slate-300 text-sm">載入K線數據中...</p>
            </div>
          </div>
        ) : klineError ? (
          <div className="flex items-center justify-center glass-panel rounded-xl" style={{ height: '640px' }}>
            <div className="text-center">
              <div className="text-rose-300 text-2xl mb-2">⚠️</div>
              <p className="text-rose-200 text-sm">{klineError}</p>
            </div>
          </div>
        ) : klineData.length > 0 ? (
          <TradingChartContainer
            symbol={selectedSymbol}
            timeframe={selectedTimeframe}
            klines={klineData}
            toTimestamp={alignedCaseTimestamp ?? selectedTimestamp ?? 0}
            tcTimestamp={alignedTcTimestamp ?? undefined}
            totalHeight={640}
            showToMarker={true}
          />
        ) : (
          <div className="glass-panel border border-slate-800/80 rounded-lg p-12 text-center">
            <p className="text-slate-300 text-lg">無K線數據</p>
          </div>
        )
      ) : (
        <div className="glass-panel border border-slate-800/80 rounded-lg p-12 text-center">
          <p className="text-slate-300 text-lg">請選擇案例以查看圖表</p>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import {
  AlertCircle,
  ArrowLeft,
  LineChart,
  Loader2,
  RefreshCcw,
} from "lucide-react";
import {
  useStrategyConfig,
  type HydrationSource,
} from "@/hooks/useStrategyConfig";
import {
  TradingChartWithSignals,
  type IndicatorLineSeries,
  type WindowOverlayRange,
} from "@/components/charts/TradingChartWithSignals";
import type { SignalPoint } from "@/components/charts/StrategySignalChart";

const API_BASE_URL =
  process.env.NEXT_PUBLIC_API_URL || "http://localhost:8000";

// ============ 接口定義 ============

interface CaseRecord {
  case_id: string;
  symbol: string;
  timeframe: string;
  timestamp: number;
  positive_case: boolean;
}

interface CaseListResponse {
  total: number;
  cases: CaseRecord[];
  positive_count: number;
  negative_count: number;
  symbols: string[];
  timeframes: string[];
}

interface ChartKline {
  timestamp: number;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
  taker_buy_volume?: number;
  taker_ratio?: number;
}

interface ChartDataPayload {
  case_timestamp: number;
  klines: ChartKline[];
  to_index?: number;
  tc_index?: number;
  case_bars?: number;
  aligned_case_timestamp?: number;
  aligned_tc_timestamp?: number;
  // 新增：後端計算的指標數據
  indicators?: {
    ema_short?: Array<{ time: number; value: number | null }>;
    ema_mid?: Array<{ time: number; value: number | null }>;
    ema_long?: Array<{ time: number; value: number | null }>;
    [key: string]: Array<{ time: number; value: number | null }> | undefined;
  };
  indicator_error?: string;
  metadata: {
    symbol: string;
    timeframe: string;
    total_bars: number;
    case_timeframe?: string;
    time_range: { start: number; end: number };
  };
}

interface ChartDataResponse {
  success: boolean;
  data?: ChartDataPayload;
  error?: { code: string; message: string };
}

type CaseTypeFilter = "all" | "positive" | "negative";

// ============ 輔助函數 ============

const INDICATOR_COLORS: Record<string, string> = {
  ema_short: "#34d399",
  ema_mid: "#60a5fa",
  ema_long: "#c084fc",
};

const hydrationSourceLabel: Record<HydrationSource, string> = {
  url: "URL 參數",
  storage: "LocalStorage",
  default: "預設值",
};

const formatTimestamp = (timestamp: number): string => {
  const date = new Date(timestamp * 1000);
  const year = date.getUTCFullYear();
  const month = String(date.getUTCMonth() + 1).padStart(2, "0");
  const day = String(date.getUTCDate()).padStart(2, "0");
  const hours = String(date.getUTCHours()).padStart(2, "0");
  const minutes = String(date.getUTCMinutes()).padStart(2, "0");
  return `${year}-${month}-${day} ${hours}:${minutes}`;
};

const formatTimestampDate = (timestamp?: number) => {
  if (typeof timestamp !== "number") return "—";
  return new Date(timestamp * 1000).toISOString().slice(0, 10);
};

// ============ 指標顏色配置 ============

const AVAILABLE_TIMEFRAMES = ["1m", "5m", "15m", "30m", "1h", "4h", "12h", "1d"];

// 空數組常量，避免重新渲染
const EMPTY_ARRAY: never[] = [];

// ============ 主組件 ============

export default function ChartsPage() {
  const router = useRouter();

  // 策略配置 Hook (用於 EMA 參數和窗口設定)
  const { state, hydrateFromCache, hydrateFromUrl, lastHydrationSource, isHydrated, lastSyncedQuery, syncToUrl } = useStrategyConfig();

  const [hydrationSource, setHydrationSource] = useState<HydrationSource>(lastHydrationSource ?? "default");

  // ============ 案例選擇狀態 ============
  const [loadingCases, setLoadingCases] = useState(true);
  const [caseListError, setCaseListError] = useState<string | null>(null);
  const [caseList, setCaseList] = useState<CaseRecord[]>([]);
  const [availableSymbols, setAvailableSymbols] = useState<string[]>([]);

  const [selectedSymbol, setSelectedSymbol] = useState<string>("");
  const [selectedTimeframe, setSelectedTimeframe] = useState<string>("1h");
  const [caseTypeFilter, setCaseTypeFilter] = useState<CaseTypeFilter>("all");
  const [selectedTimestamp, setSelectedTimestamp] = useState<number | null>(null);
  const [currentCase, setCurrentCase] = useState<CaseRecord | null>(null);

  // ============ 圖表數據狀態 ============
  const [loadingChartData, setLoadingChartData] = useState(false);
  const [chartDataError, setChartDataError] = useState<string | null>(null);
  const [chartData, setChartData] = useState<ChartDataPayload | null>(null);
  const [alignedCaseTimestamp, setAlignedCaseTimestamp] = useState<number | null>(null);
  const [alignedTcTimestamp, setAlignedTcTimestamp] = useState<number | null>(null);

  // ============ UI 控制狀態 ============
  const [indicatorVisibility, setIndicatorVisibility] = useState<Record<string, boolean>>({
    ema_short: true,
    ema_mid: true,
    ema_long: true,
  });
  const [refreshToken, setRefreshToken] = useState(0);

  // ============ 窗口參數 ============
  const lookbackBars = useMemo(() => {
    if (typeof window === "undefined") return 100;
    const stored = localStorage.getItem("kline_lookback_bars");
    return stored ? parseInt(stored, 10) : 100;
  }, []);

  const forwardBars = useMemo(() => {
    if (typeof window === "undefined") return 48;
    const stored = localStorage.getItem("kline_forward_bars");
    return stored ? parseInt(stored, 10) : 48;
  }, []);

  // ============ Hydration ============
  useEffect(() => {
    // 優先從 URL 讀取參數（從 Strategy Test 頁面跳轉時）
    if (typeof window !== "undefined") {
      const urlParams = window.location.search;
      if (urlParams && urlParams.length > 1) {
        const hydratedFromUrl = hydrateFromUrl(urlParams);
        if (hydratedFromUrl) {
          setHydrationSource("url");
          return;
        }
      }
    }

    // Fallback 到 cache/storage
    if (isHydrated) {
      setHydrationSource(lastHydrationSource ?? "storage");
    } else {
      const restored = hydrateFromCache();
      setHydrationSource(restored ? "storage" : "default");
    }
  }, [hydrateFromCache, hydrateFromUrl, isHydrated, lastHydrationSource]);

  // ============ 載入案例列表 ============
  useEffect(() => {
    const fetchCaseList = async () => {
      try {
        setLoadingCases(true);
        setCaseListError(null);
        const response = await fetch(`${API_BASE_URL}/api/v1/case/list`);
        if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
        const result: CaseListResponse = await response.json();
        setCaseList(result.cases);
        setAvailableSymbols(result.symbols);
        if (result.symbols.length > 0) setSelectedSymbol(result.symbols[0]);
      } catch (err) {
        console.error("Failed to fetch case list:", err);
        setCaseListError(err instanceof Error ? err.message : "載入案例列表失敗");
      } finally {
        setLoadingCases(false);
      }
    };
    fetchCaseList();
  }, []);

  // ============ 過濾案例 ============
  const filteredCases = useMemo(() => {
    return caseList.filter((c) => {
      if (selectedSymbol && c.symbol !== selectedSymbol) return false;
      if (caseTypeFilter === "positive" && !c.positive_case) return false;
      if (caseTypeFilter === "negative" && c.positive_case) return false;
      return true;
    });
  }, [caseList, selectedSymbol, caseTypeFilter]);

  // ============ 自動選擇第一個案例 ============
  useEffect(() => {
    if (filteredCases.length > 0) {
      setSelectedTimestamp(filteredCases[0].timestamp);
      setCurrentCase(filteredCases[0]);
    } else {
      setSelectedTimestamp(null);
      setCurrentCase(null);
    }
  }, [selectedSymbol, caseTypeFilter, filteredCases.length]);

  // ============ 更新當前案例 ============
  useEffect(() => {
    if (selectedTimestamp !== null) {
      const foundCase = filteredCases.find((c) => c.timestamp === selectedTimestamp);
      setCurrentCase(foundCase || null);
    }
  }, [selectedTimestamp, filteredCases]);

  // ============ 獲取 K 線數據（含指標計算）============
  useEffect(() => {
    if (!selectedSymbol || selectedTimestamp === null || !selectedTimeframe || !currentCase) return;

    let cancelled = false;
    const fetchChartData = async () => {
      try {
        setLoadingChartData(true);
        setChartDataError(null);
        setAlignedCaseTimestamp(null);
        setAlignedTcTimestamp(null);

        const caseTimeframe = currentCase.timeframe;

        // 防護性檢查：確保 case_timeframe 有效
        if (!caseTimeframe) {
          console.error(`[ChartsPage] ERROR: currentCase.timeframe is undefined for case ${currentCase.case_id}`);
          throw new Error("案例缺少時間框架資訊，請重新導入案例");
        }

        // 構建 URL 參數
        const params = new URLSearchParams({
          symbol: selectedSymbol,
          case_timestamp: selectedTimestamp.toString(),
          timeframe: selectedTimeframe,
          case_timeframe: caseTimeframe,
          lookback_bars: lookbackBars.toString(),
          forward_bars: forwardBars.toString(),
        });

        // 新增：指標計算參數
        const dataSource = state.dataSources ?? "close";
        const indicatorType = state.indicatorType ?? "ema";
        const strategyLogic = state.strategyLogic ?? "three_line";
        const indicatorParams = state.indicatorParams;

        if (indicatorParams) {
          params.append("indicator_type", indicatorType);
          params.append("data_source", dataSource);
          params.append("strategy_logic", strategyLogic);

          if (indicatorParams.short_period) {
            params.append("short_period", indicatorParams.short_period.toString());
          }
          if (indicatorParams.mid_period) {
            params.append("mid_period", indicatorParams.mid_period.toString());
          }
          if (indicatorParams.long_period) {
            params.append("long_period", indicatorParams.long_period.toString());
          }
        }

        const url = `${API_BASE_URL}/api/v1/chart/data?${params.toString()}`;

        console.log(`[ChartsPage] Fetching: case_tf=${caseTimeframe}, view_tf=${selectedTimeframe}, lookback=${lookbackBars}, forward=${forwardBars}, indicator=${indicatorType}, source=${dataSource}`);

        const response = await fetch(url);
        if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);

        const result: ChartDataResponse = await response.json();
        if (!result.success || !result.data) throw new Error(result.error?.message || "獲取K線數據失敗");

        if (!cancelled) {
          setChartData(result.data);
          setAlignedCaseTimestamp(result.data.aligned_case_timestamp ?? selectedTimestamp);
          setAlignedTcTimestamp(result.data.aligned_tc_timestamp ?? null);

          // 日誌：是否包含指標數據
          const hasIndicators = !!result.data.indicators;
          console.log(`[ChartsPage] Loaded ${result.data.klines.length} klines, TO at ${result.data.to_index}, TC at ${result.data.tc_index}, has_indicators=${hasIndicators}`);

          if (result.data.indicator_error) {
            console.warn(`[ChartsPage] Indicator calculation warning: ${result.data.indicator_error}`);
          }
        }
      } catch (err) {
        if (!cancelled) {
          console.error("Failed to fetch chart data:", err);
          setChartDataError(err instanceof Error ? err.message : "載入K線數據失敗");
          setChartData(null);
        }
      } finally {
        if (!cancelled) setLoadingChartData(false);
      }
    };

    fetchChartData();
    return () => { cancelled = true; };
  }, [selectedSymbol, selectedTimestamp, selectedTimeframe, currentCase, lookbackBars, forwardBars, refreshToken, state.dataSources, state.indicatorType, state.strategyLogic, state.indicatorParams]);

  // ============ 計算 EMA（支持不同數據源）============
  const calculateEMAForSource = (
    klines: ChartKline[],
    period: number,
    dataSource: string
  ): Array<{ time: number; value: number }> => {
    if (!period || klines.length === 0) return [];

    // 根據數據源選擇對應的欄位
    const getSourceValue = (kline: ChartKline): number => {
      switch (dataSource) {
        case "close": return kline.close;
        case "open": return kline.open;
        case "high": return kline.high;
        case "low": return kline.low;
        case "volume": return kline.volume;
        case "taker_buy_volume": return kline.taker_buy_volume ?? 0;
        case "taker_ratio": return kline.taker_ratio ?? 0;
        default: return kline.close;
      }
    };

    const multiplier = 2 / (period + 1);
    let ema = getSourceValue(klines[0]);

    return klines.map((kline, index) => {
      const value = getSourceValue(kline);
      if (index === 0) {
        ema = value;
      } else {
        ema = (value - ema) * multiplier + ema;
      }
      return { time: kline.timestamp, value: ema };
    });
  };

  // ============ 計算指標線並根據數據源分配到正確的圖表 ============
  const dataSource = state.dataSources ?? "close";

  // 判斷數據源屬於哪種類型的圖表
  const isVolumeSource = dataSource === "volume" || dataSource === "taker_buy_volume";
  const isTakerSource = dataSource === "taker_ratio";
  const isPriceSource = !isVolumeSource && !isTakerSource; // close, open, high, low

  const indicatorSeries = useMemo<IndicatorLineSeries[]>(() => {
    if (!chartData || chartData.klines.length === 0) return [];

    // 使用統一命名規範：short_period, mid_period, long_period
    const ema_short = state.indicatorParams.short_period;
    const ema_mid = state.indicatorParams.mid_period;
    const ema_long = state.indicatorParams.long_period;

    const indicatorConfigs = [
      { key: "ema_short", period: ema_short, label: `EMA Short (${ema_short})` },
      { key: "ema_mid", period: ema_mid, label: `EMA Mid (${ema_mid})` },
      { key: "ema_long", period: ema_long, label: `EMA Long (${ema_long})` },
    ].filter((item) => Number.isFinite(item.period) && item.period > 0);

    // 優先使用後端計算的指標數據
    const backendIndicators = chartData.indicators;

    return indicatorConfigs.map((item) => {
      let data: Array<{ time: number; value: number }>;

      if (backendIndicators && backendIndicators[item.key]) {
        // 使用後端數據（過濾掉 null 值）
        data = backendIndicators[item.key]!
          .filter((point): point is { time: number; value: number } => point.value !== null)
          .map((point) => ({ time: point.time, value: point.value }));
        console.log(`[ChartsPage] Using backend EMA for ${item.key}: ${data.length} points`);
      } else {
        // 回退到前端計算（兜底方案，不應該常發生）
        console.warn(`[ChartsPage] Fallback to frontend EMA calculation for ${item.key} - backend data not available`);
        data = calculateEMAForSource(chartData.klines, item.period, dataSource);
      }

      return {
        id: item.key,
        label: item.label,
        color: INDICATOR_COLORS[item.key] ?? "#64748b",
        data,
      };
    });
  }, [chartData, state.indicatorParams, dataSource]);

  const activeIndicatorSeries = useMemo<IndicatorLineSeries[]>(
    () => indicatorSeries.filter((series) => indicatorVisibility[series.id] !== false),
    [indicatorSeries, indicatorVisibility]
  );

  // 根據數據源將指標分配到對應的圖表（使用 useMemo 穩定引用）
  const priceIndicatorSeries = useMemo(() => isPriceSource ? activeIndicatorSeries : EMPTY_ARRAY as IndicatorLineSeries[], [isPriceSource, activeIndicatorSeries]);
  const volumeIndicatorSeries = useMemo(() => isVolumeSource ? activeIndicatorSeries : EMPTY_ARRAY as IndicatorLineSeries[], [isVolumeSource, activeIndicatorSeries]);
  const takerIndicatorSeries = useMemo(() => isTakerSource ? activeIndicatorSeries : EMPTY_ARRAY as IndicatorLineSeries[], [isTakerSource, activeIndicatorSeries]);

  // ============ 計算近窗口遮罩 (near window overlay) ============
  const windowOverlays = useMemo<WindowOverlayRange[]>(() => {
    // 需要 alignedCaseTimestamp (TO 時間戳) 和 timeframe 來計算
    const toTs = alignedCaseTimestamp ?? selectedTimestamp;
    if (!toTs || !selectedTimeframe) return [];

    // 從 state 獲取 lookback_bars (近窗口範圍)
    const nearWindowBars = state.windowConfig?.lookback_bars ?? 24;

    // 將 timeframe 轉換為秒數
    const getTimeframeSeconds = (tf: string): number => {
      const match = tf.match(/^(\d+)([mhdwM])$/);
      if (!match) return 43200; // 默認 12h
      const [, numStr, unit] = match;
      const num = parseInt(numStr, 10);
      switch (unit) {
        case "m": return num * 60;
        case "h": return num * 3600;
        case "d": return num * 86400;
        case "w": return num * 604800;
        case "M": return num * 2592000; // ~30 days
        default: return 43200;
      }
    };

    const barSeconds = getTimeframeSeconds(selectedTimeframe);

    // near window: TO - nearWindowBars 到 TO - 1
    // 使用 bar 的結束時間作為時間戳 (因為 K 線 timestamp 是開盤時間)
    const nearStartTs = toTs - nearWindowBars * barSeconds;
    const nearEndTs = toTs - barSeconds; // TO - 1 bar

    return [
      {
        type: "near" as const,
        startTimestamp: nearStartTs,
        endTimestamp: nearEndTs,
      },
    ];
  }, [alignedCaseTimestamp, selectedTimestamp, selectedTimeframe, state.windowConfig?.lookback_bars]);

  // ============ 計算策略信號點 ============
  const signalPoints = useMemo<SignalPoint[]>(() => {
    // 需要指標數據和策略邏輯
    if (!chartData || chartData.klines.length === 0) return [];
    if (indicatorSeries.length < 3) return []; // 需要至少 3 條 EMA 線

    const strategyLogic = state.strategyLogic;
    if (!strategyLogic) return [];

    // 獲取 EMA 數據
    const emaShort = indicatorSeries.find(s => s.id === 'ema_short')?.data ?? [];
    const emaMid = indicatorSeries.find(s => s.id === 'ema_mid')?.data ?? [];
    const emaLong = indicatorSeries.find(s => s.id === 'ema_long')?.data ?? [];

    if (emaShort.length === 0 || emaMid.length === 0 || emaLong.length === 0) return [];

    // 獲取窗口配置
    const toTs = alignedCaseTimestamp ?? selectedTimestamp;
    const nearBars = state.windowConfig?.lookback_bars ?? 24;
    const farBars = state.windowConfig?.far_lookback_bars; // 可能為 undefined

    // 計算 timeframe 秒數
    const getTimeframeSeconds = (tf: string): number => {
      const match = tf.match(/^(\d+)([mhdwM])$/);
      if (!match) return 43200;
      const [, numStr, unit] = match;
      const num = parseInt(numStr, 10);
      switch (unit) {
        case "m": return num * 60;
        case "h": return num * 3600;
        case "d": return num * 86400;
        case "w": return num * 604800;
        case "M": return num * 2592000;
        default: return 43200;
      }
    };

    const barSeconds = selectedTimeframe ? getTimeframeSeconds(selectedTimeframe) : 43200;

    // 計算窗口邊界時間戳
    const nearStartTs = toTs ? toTs - nearBars * barSeconds : 0;
    const nearEndTs = toTs ? toTs - barSeconds : 0; // TO - 1
    const farStartTs = toTs && farBars ? toTs - farBars * barSeconds : 0;
    const farEndTs = toTs ? toTs - (nearBars + 1) * barSeconds : 0; // TO - nearBars - 1

    const signals: SignalPoint[] = [];

    // 遍歷每個時間點檢查策略條件
    chartData.klines.forEach((kline, index) => {
      const ts = kline.timestamp;

      // 查找對應的 EMA 值
      const shortVal = emaShort.find(d => d.time === ts)?.value;
      const midVal = emaMid.find(d => d.time === ts)?.value;
      const longVal = emaLong.find(d => d.time === ts)?.value;

      if (shortVal === undefined || midVal === undefined || longVal === undefined) return;

      // 檢查策略條件
      let conditionMet = false;
      if (strategyLogic === 'three_line') {
        conditionMet = shortVal > midVal && midVal > longVal;
      } else if (strategyLogic === 'short_long_cross') {
        conditionMet = shortVal > longVal;
      } else if (strategyLogic === 'mid_long_cross') {
        conditionMet = midVal > longVal;
      }

      if (!conditionMet) return;

      // 判斷屬於哪個窗口
      let windowType: 'near' | 'far' | undefined;

      if (toTs) {
        if (ts >= nearStartTs && ts <= nearEndTs) {
          windowType = 'near';
        } else if (farBars) {
          // 有設定 far_lookback_bars
          if (ts >= farStartTs && ts <= farEndTs) {
            windowType = 'far';
          }
        } else {
          // 沒設定 far_lookback_bars，近期以外都是遠期
          if (ts < nearStartTs) {
            windowType = 'far';
          }
        }
      }

      // 只有在窗口內的信號才加入
      if (windowType) {
        signals.push({
          timestamp: ts,
          indicator_values: {
            ema_short: shortVal,
            ema_mid: midVal,
            ema_long: longVal,
          },
          windowType,
        });
      }
    });

    return signals;
  }, [chartData, indicatorSeries, state.strategyLogic, state.windowConfig, alignedCaseTimestamp, selectedTimestamp, selectedTimeframe]);

  // 根據數據源分配信號點到對應圖表（使用 useMemo 穩定引用）
  const priceSignalPoints = useMemo(() => isPriceSource ? signalPoints : EMPTY_ARRAY as SignalPoint[], [isPriceSource, signalPoints]);
  const volumeSignalPoints = useMemo(() => isVolumeSource ? signalPoints : EMPTY_ARRAY as SignalPoint[], [isVolumeSource, signalPoints]);
  const takerSignalPoints = useMemo(() => isTakerSource ? signalPoints : EMPTY_ARRAY as SignalPoint[], [isTakerSource, signalPoints]);

  const handleToggleSeries = (seriesId: string) => {
    setIndicatorVisibility((prev) => ({ ...prev, [seriesId]: !prev[seriesId] }));
  };

  const handleRetryFetch = () => setRefreshToken((t) => t + 1);

  const handleBack = () => {
    const query = state.syncToUrl ? (lastSyncedQuery ? `?${lastSyncedQuery}` : syncToUrl() ?? "") : "";
    router.push(`/strategy-test${query ?? ""}`);
  };

  // ============ 渲染 ============

  if (loadingCases) {
    return (
      <div className="min-h-screen bg-slate-950/40 flex items-center justify-center">
        <div className="text-center">
          <Loader2 className="h-8 w-8 animate-spin text-emerald-400 mx-auto mb-3" />
          <p className="text-slate-300">載入案例數據中...</p>
        </div>
      </div>
    );
  }

  if (caseListError) {
    return (
      <div className="min-h-screen bg-slate-950/40 flex items-center justify-center">
        <div className="glass-panel border border-rose-500/40 rounded-lg p-6 max-w-md">
          <h2 className="text-rose-200 text-lg font-semibold mb-2">載入失敗</h2>
          <p className="text-rose-200/80">{caseListError}</p>
          <button onClick={() => window.location.reload()} className="mt-4 px-4 py-2 bg-rose-500/20 text-rose-100 rounded border border-rose-400/40 hover:bg-rose-500/30">
            重新載入
          </button>
        </div>
      </div>
    );
  }

  if (caseList.length === 0) {
    return (
      <div className="min-h-screen bg-slate-950/40 flex items-center justify-center">
        <div className="glass-panel border border-amber-400/40 rounded-lg p-6 max-w-md text-center">
          <h2 className="text-amber-200 text-lg font-semibold mb-2">暫無數據</h2>
          <p className="text-amber-200/80 mb-4">尚未導入任何案例數據。請先到「數據準備」頁面導入案例 CSV 並下載 K 線數據。</p>
          <button onClick={() => router.push("/data-preparation")} className="px-4 py-2 bg-amber-500/20 text-amber-100 rounded border border-amber-400/40 hover:bg-amber-500/30">
            前往數據準備
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950/40">
      <header className="border-b border-slate-800/80 bg-slate-950/80">
        <div className="px-6 py-4">
          <div className="flex items-center justify-between">
            <div>
              <div className="flex items-center gap-3 text-sm text-slate-400">
                <button onClick={handleBack} className="inline-flex items-center gap-2 rounded-lg border border-slate-700 px-3 py-1 text-xs font-medium text-slate-300 hover:bg-slate-900/60">
                  <ArrowLeft className="h-3.5 w-3.5" /> 返回策略測試
                </button>
                <span className="flex items-center gap-1 text-emerald-300">
                  <LineChart className="h-4 w-4" /> /charts
                </span>
              </div>
              <h1 className="mt-2 text-2xl font-semibold text-slate-100">案例圖表查看</h1>
              <p className="text-sm text-slate-400">選擇案例查看 K 線圖表，包含 EMA 指標和窗口遮罩</p>
            </div>
            <div className="text-right text-xs text-slate-400">
              <p>策略設定來源: {hydrationSourceLabel[hydrationSource]}</p>
            </div>
          </div>
        </div>
      </header>

      <main className="px-6 py-6 space-y-6">
        {/* 案例選擇 */}
        <section className="glass-panel rounded-xl border border-slate-800/80 p-5">
          <h2 className="text-sm font-semibold text-slate-200 mb-4">案例選擇</h2>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div>
              <label className="block text-xs font-medium text-slate-400 mb-1">交易對</label>
              <select value={selectedSymbol} onChange={(e) => setSelectedSymbol(e.target.value)} className="w-full px-3 py-2 border border-slate-700 rounded-md text-slate-100 text-sm bg-slate-900/60">
                {availableSymbols.map((symbol) => (<option key={symbol} value={symbol}>{symbol}</option>))}
              </select>
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-400 mb-1">案例類型</label>
              <select value={caseTypeFilter} onChange={(e) => setCaseTypeFilter(e.target.value as CaseTypeFilter)} className="w-full px-3 py-2 border border-slate-700 rounded-md text-slate-100 text-sm bg-slate-900/60">
                <option value="all">全部</option>
                <option value="positive">正例</option>
                <option value="negative">反例</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-400 mb-1">時間框架（查看用）</label>
              <select value={selectedTimeframe} onChange={(e) => setSelectedTimeframe(e.target.value)} className="w-full px-3 py-2 border border-slate-700 rounded-md text-slate-100 text-sm bg-slate-900/60">
                {AVAILABLE_TIMEFRAMES.map((tf) => (<option key={tf} value={tf}>{tf}</option>))}
              </select>
              <p className="text-[10px] text-slate-500 mt-1">與案例時間框架獨立</p>
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-400 mb-1">案例時間點 ({filteredCases.length} 個)</label>
              <select value={selectedTimestamp || ""} onChange={(e) => setSelectedTimestamp(Number(e.target.value))} disabled={filteredCases.length === 0} className="w-full px-3 py-2 border border-slate-700 rounded-md text-slate-100 text-sm bg-slate-900/60">
                {filteredCases.map((c) => (<option key={c.case_id} value={c.timestamp}>{formatTimestamp(c.timestamp)} {c.positive_case ? "✓" : "✗"}</option>))}
              </select>
            </div>
          </div>
          {currentCase && (
            <div className="mt-4 pt-4 border-t border-slate-800/80 grid grid-cols-2 md:grid-cols-5 gap-4 text-xs">
              <div><span className="text-slate-400">案例ID：</span><span className="font-mono text-slate-100">{currentCase.case_id}</span></div>
              <div><span className="text-slate-400">類型：</span><span className={`font-semibold ${currentCase.positive_case ? "text-emerald-400" : "text-rose-400"}`}>{currentCase.positive_case ? "正例 ✓" : "反例 ✗"}</span></div>
              <div><span className="text-slate-400">案例時間框架：</span><span className="font-mono text-slate-100">{currentCase.timeframe}</span></div>
              <div><span className="text-slate-400">Lookback：</span><span className="font-mono text-slate-100">{lookbackBars} 根</span></div>
              <div><span className="text-slate-400">Forward：</span><span className="font-mono text-slate-100">{forwardBars} 根</span></div>
            </div>
          )}
        </section>

        {/* 指標控制 */}
        <section className="glass-panel rounded-xl border border-slate-800/80 p-4">
          <div className="flex flex-wrap items-center gap-2 text-xs text-slate-300">
            <span className="font-semibold text-slate-100">指標顯示：</span>
            <span className="px-2 py-0.5 rounded bg-emerald-500/10 text-emerald-200 font-medium border border-emerald-400/30">
              EMA: {state.indicatorParams.short_period} / {state.indicatorParams.mid_period} / {state.indicatorParams.long_period}
            </span>
            <span className="px-2 py-0.5 rounded bg-sky-500/10 text-sky-200 border border-sky-400/30">
              策略: {state.strategyLogic === 'three_line' ? '三線順勢' : state.strategyLogic}
            </span>
            <span className="px-2 py-0.5 rounded bg-slate-800/60 text-slate-400 border border-slate-700/60">
              數據源: {dataSource} → {isPriceSource ? "Price圖" : isVolumeSource ? "Volume圖" : "Taker圖"}
            </span>
            {indicatorSeries.map((series) => (
              <button key={series.id} onClick={() => handleToggleSeries(series.id)} className={`rounded-full border px-3 py-1 font-medium ${indicatorVisibility[series.id] !== false ? "border-emerald-400/40 bg-emerald-500/10 text-emerald-200" : "border-slate-700 text-slate-400"}`}>
                <span className="inline-flex items-center gap-1">
                  <span className="inline-block h-2 w-2 rounded-full" style={{ backgroundColor: series.color }} />
                  {series.label}
                </span>
              </button>
            ))}
          </div>
        </section>

        {/* 圖表區域 */}
        <section className="glass-panel rounded-xl border border-slate-800/80 p-4">
          {selectedTimestamp !== null ? (
            loadingChartData ? (
              <div className="flex items-center justify-center bg-slate-900/40 rounded-lg" style={{ height: "640px" }}>
                <div className="text-center">
                  <Loader2 className="h-8 w-8 animate-spin text-emerald-400 mx-auto mb-2" />
                  <p className="text-slate-300 text-sm">載入 K 線數據中...</p>
                </div>
              </div>
            ) : chartDataError ? (
              <div className="flex items-center justify-center bg-rose-500/10 rounded-lg border border-rose-500/30" style={{ height: "640px" }}>
                <div className="text-center">
                  <AlertCircle className="h-8 w-8 text-rose-300 mx-auto mb-2" />
                  <p className="text-rose-200 text-sm mb-3">{chartDataError}</p>
                  <button onClick={handleRetryFetch} className="inline-flex items-center gap-2 px-4 py-2 bg-rose-500/20 text-rose-100 rounded-md border border-rose-400/40 hover:bg-rose-500/30 text-sm">
                    <RefreshCcw className="h-4 w-4" /> 重新載入
                  </button>
                </div>
              </div>
            ) : chartData && chartData.klines.length > 0 ? (
              <div className="space-y-3">
                <div className="flex flex-wrap items-center justify-between gap-3">
                  <div>
                    <p className="text-sm font-semibold text-slate-100">{selectedSymbol} / {selectedTimeframe} — Price / Volume / Taker Ratio</p>
                    <p className="text-xs text-slate-400">{formatTimestampDate(chartData.metadata.time_range.start)} → {formatTimestampDate(chartData.metadata.time_range.end)} ・ {chartData.metadata.total_bars} 根 K 線</p>
                  </div>
                  <button onClick={handleRetryFetch} className="inline-flex items-center gap-2 px-3 py-1 border border-slate-700 rounded-md text-xs text-slate-300 hover:bg-slate-900/60">
                    <RefreshCcw className="h-3.5 w-3.5" /> 刷新
                  </button>
                </div>
                <TradingChartWithSignals
                  symbol={selectedSymbol}
                  timeframe={selectedTimeframe}
                  klines={chartData.klines}
                  signalPoints={priceSignalPoints}
                  toTimestamp={alignedCaseTimestamp ?? selectedTimestamp ?? 0}
                  tcTimestamp={alignedTcTimestamp ?? undefined}
                  totalHeight={700}
                  showSignalMarkers={priceSignalPoints.length > 0}
                  priceIndicatorSeries={priceIndicatorSeries}
                  volumeIndicatorSeries={volumeIndicatorSeries}
                  takerIndicatorSeries={takerIndicatorSeries}
                  volumeSignalPoints={volumeSignalPoints}
                  takerSignalPoints={takerSignalPoints}
                  showVolumeToTcMarkers={false}
                  windowOverlays={EMPTY_ARRAY}
                />
              </div>
            ) : (
              <div className="flex items-center justify-center bg-slate-900/40 rounded-lg" style={{ height: "640px" }}>
                <div className="text-center"><LineChart className="h-8 w-8 text-slate-600 mx-auto mb-2" /><p className="text-slate-400">無 K 線數據</p></div>
              </div>
            )
          ) : (
            <div className="flex items-center justify-center bg-slate-900/40 rounded-lg" style={{ height: "640px" }}>
              <div className="text-center"><LineChart className="h-8 w-8 text-slate-600 mx-auto mb-2" /><p className="text-slate-400">請選擇案例以查看圖表</p></div>
            </div>
          )}
        </section>

        {/* 信號統計 */}
        {chartData && (
          <section className="glass-panel border border-slate-800/80 rounded-lg p-4 text-xs text-slate-300">
            <p className="font-semibold mb-2 text-slate-100">信號統計</p>
            {(() => {
              const nearCount = signalPoints.filter(s => s.windowType === 'near').length;
              const farCount = signalPoints.filter(s => s.windowType === 'far').length;
              const totalBars = chartData.metadata.total_bars;
              const nearBars = state.windowConfig?.lookback_bars ?? 24;
              const farBars = state.windowConfig?.far_lookback_bars ?? (totalBars - nearBars);
              const nearRatio = nearBars > 0 ? (nearCount / nearBars * 100) : 0;
              const farRatio = farBars > 0 ? (farCount / farBars * 100) : 0;
              // Near/Far 比率 = Near密度 / Far密度
              const densityRatio = farRatio > 0 ? (nearRatio / farRatio).toFixed(2) : (nearRatio > 0 ? '∞' : '0.00');

              return (
                <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                  <div className="flex items-center gap-2">
                    <span className="inline-block w-3 h-3 rounded" style={{ backgroundColor: '#60a5fa' }}></span>
                    <span>Near 信號: <strong>{nearCount}</strong></span>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="inline-block w-3 h-3 rounded" style={{ backgroundColor: '#fbbf24' }}></span>
                    <span>Far 信號: <strong>{farCount}</strong></span>
                  </div>
                  <div>
                    Near 密度: <strong>{nearRatio.toFixed(1)}%</strong>
                    <span className="text-slate-500 ml-1">({nearCount}/{nearBars} bars)</span>
                  </div>
                  <div>
                    Far 密度: <strong>{farRatio.toFixed(1)}%</strong>
                    <span className="text-slate-500 ml-1">({farCount}/{farBars} bars)</span>
                  </div>
                  <div>
                    Near/Far 密度比: <strong className={parseFloat(String(densityRatio)) > 1 ? 'text-emerald-400' : parseFloat(String(densityRatio)) < 1 ? 'text-rose-400' : ''}>{densityRatio}</strong>
                  </div>
                </div>
              );
            })()}
          </section>
        )}
      </main>
    </div>
  );
}

