  const [pattern, setPattern] = useState<Pattern | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string>('');

  useEffect(() => {
    loadPattern();
  }, [patternId]);

  const loadPattern = async () => {
    try {
      setLoading(true);
