        {/* ===== 保持現有的無數據狀態 ===== */}
        {!searchResults && !isLoading && !error && (
          <div className="glass-panel rounded-xl p-12 text-center">
            <Search className="w-16 h-16 text-slate-500 mx-auto mb-4" />
