        <div className="grid grid-cols-1 xl:grid-cols-12 gap-6">
          {/* 左側: 配置面板 (緊湊版) */}
          <div className="xl:col-span-3 space-y-4">
            {/* 測試範圍 */}
            <div className="glass-panel rounded-xl p-4">
              <h2 className="text-sm font-semibold text-slate-100 mb-3">
                🎯 測試範圍
              </h2>
              <div className="space-y-3">
                <div>
                  <label className="block text-xs font-medium text-slate-300 mb-1">
                    交易標的
                  </label>
                  <input
                    type="text"
                    value={symbol}
                    onChange={(e) => setSymbol(e.target.value)}
                    className="w-full px-3 py-1.5 border border-slate-700 rounded text-sm bg-slate-900/60 text-slate-100"
                    placeholder="BTCUSDT"
                  />
                </div>
                <div>
                  <label className="block text-xs font-medium text-slate-300 mb-1">
                    時間框架
                  </label>
                  <select
                    value={timeframe}
                    onChange={(e) => setTimeframe(e.target.value)}
                    className="w-full px-3 py-1.5 border border-slate-700 rounded text-sm bg-slate-900/60 text-slate-100"
                  >
                    <option value="1m">1分鐘</option>
                    <option value="5m">5分鐘</option>
                    <option value="15m">15分鐘</option>
                    <option value="1h">1小時</option>
                    <option value="4h">4小時</option>
                    <option value="1d">1天</option>
                  </select>
                </div>
              </div>
            </div>

            {/* 策略配置 */}
            <div className="glass-panel rounded-xl p-4 space-y-4">
              <h2 className="text-sm font-semibold text-slate-100">⚙️ 策略配置</h2>

              <DataSourceSelector
                value={config.data_source}
                onChange={(v) => updateConfig("data_source", v)}
                disabled={isLoading}
              />

              <IndicatorSelector
                value={config.indicator_type}
                onChange={(v) => updateConfig("indicator_type", v)}
                disabled={isLoading}
              />

              <StrategyLogicSelector
                value={config.strategy_logic}
                onChange={(v) => updateConfig("strategy_logic", v)}
                disabled={isLoading}
              />

              <TestModeSelector
                value={config.test_mode}
