                    <span
                      className={`rounded-full px-2 py-0.5 text-[10px] font-semibold ${
                        currentStrategyGuide.status === "active"
                          ? "bg-emerald-500/20 text-emerald-200"
                          : "bg-slate-800 text-slate-400"
                      }`}
                    >
                      {currentStrategyGuide.status === "active" ? "已啟用" : "開發中"}
                    </span>
                    {currentStrategyGuide.note && (
                      <span className="text-[10px] text-slate-500">{currentStrategyGuide.note}</span>
                    )}
                  </div>
                  <p className="mt-2 leading-relaxed text-slate-300">
                    {currentStrategyGuide.description}
                  </p>
                  {currentStrategyGuide.bullets && (
                    <ul className="mt-2 list-inside list-disc space-y-1 text-[11px] text-slate-400">
                      {currentStrategyGuide.bullets.map((tip, index) => (
                        <li key={`${currentStrategyGuide.title}-${index}`}>{tip}</li>
                      ))}
                    </ul>
                  )}
                </div>
              </div>
            </AccordionItem>

            <AccordionItem id="indicator" title="指標參數" badge="EMA">
              <div className="grid grid-cols-1 gap-4">
                <NumberInput
                  label="EMA Short"
                  value={state.indicatorParams.short_period}
                  min={2}
                  max={500}
                  onChange={(value) => handleIndicatorParamChange("short_period", value)}
                />
                <NumberInput
                  label="EMA Mid"
                  value={state.indicatorParams.mid_period}
                  min={state.indicatorParams.short_period + 1}
                  max={500}
                  onChange={(value) => handleIndicatorParamChange("mid_period", value)}
                />
                <NumberInput
                  label="EMA Long"
                  value={state.indicatorParams.long_period}
                  min={state.indicatorParams.mid_period + 1}
                  max={500}
                  onChange={(value) => handleIndicatorParamChange("long_period", value)}
                />
              </div>
            </AccordionItem>

            <AccordionItem
              id="window"
              title="窗口配置"
              badge={state.windowConfig.far_lookback_bars ? "雙密度" : "單密度"}
            >
              <div className="space-y-4">
                <WindowConfigPanel
                  value={state.windowConfig}
                  onChange={handleWindowConfigChange}
                />
                <button
                  type="button"
                  onClick={handleApplyDualWindowPreset}
                  className="inline-flex items-center gap-2 rounded-lg border border-sky-400/40 bg-sky-500/10 px-3 py-2 text-xs font-medium text-sky-200 transition hover:bg-sky-500/20"
                >
                  套用 Near 24 / Far 100 預設
                </button>
              </div>
            </AccordionItem>

            <AccordionItem 
              id="range" 
              title="測試範圍" 
              badge={
                state.symbols?.includes("ALL_SYMBOLS") 
                  ? `全部交易對 (${availableSymbols.length})` 
                  : `${state.symbols?.length || 0} 個交易對`
              }
            >
              <div className="space-y-4">
                {/* 多選交易對選擇器 */}
                <div className="space-y-1">
                  <label className="text-xs font-medium text-slate-400">交易對選擇</label>
                  <SymbolMultiSelect
                    value={state.symbols}
                    onChange={(symbols) => setField("symbols", symbols)}
                    availableSymbols={availableSymbols}
                    isLoading={isLoadingSymbols}
                    error={symbolsError}
                  />
                </div>

                <CustomSelect
                  label="時間框架"
                  options={TIMEFRAME_OPTIONS}
                  value={state.timeframe}
                  onChange={(value) => setField("timeframe", value ?? state.timeframe)}
                />
                <DateRangePicker
                  label="時間範圍"
                  startDate={state.dateRange.start}
                  endDate={state.dateRange.end}
                  onChange={(start, end) =>
                    setField("dateRange", {
                      start,
                      end,
                    })
                  }
                />
                <label className="flex items-center gap-2 text-sm text-slate-400">
                  <input
                    type="checkbox"
                    checked={state.syncToUrl}
                    onChange={(event) => setField("syncToUrl", event.target.checked)}
                    className="h-4 w-4 rounded border-slate-600 text-emerald-400 focus:ring-emerald-400"
                  />
                  轉跳 /charts 時同步參數至 URL
                </label>
              </div>
            </AccordionItem>

            <AccordionItem id="optimizer" title="優化參數" badge={`${(state.clusteringWeight * 100).toFixed(0)}% 聚集權重`}>
              <div className="space-y-3">
                <label className="text-sm font-medium text-slate-300">clustering_weight (0=只看區分度, 1=只看聚集度)</label>
                <input
                  type="range"
                  min={0}
                  max={1}
                  step={0.05}
                  value={state.clusteringWeight}
                  onChange={(event) => setField("clusteringWeight", Number(event.target.value))}
                  className="w-full"
                />
                <div className="flex items-center justify-between text-xs text-slate-400">
                  <span>偏重 Near/Far Ratio</span>
                  <span className="font-semibold text-slate-200">{state.clusteringWeight.toFixed(2)}</span>
                  <span>偏重 正反例區分</span>
                </div>
              </div>
            </AccordionItem>

            <AccordionItem
              id="optuna"
              title="Optuna 參數優化"
              badge={optunaConfig.enabled ? `已啟用 (${optunaConfig.n_trials} trials)` : "未啟用"}
            >
              <OptunaConfigPanel
                config={optunaConfig}
                onChange={handleOptunaConfigChange}
                disabled={isRunning}
              />
            </AccordionItem>
          </Accordion>

          <button
            type="button"
            disabled={isRunning || isOptimizing}
            onClick={handleRunTest}
            className="flex w-full items-center justify-center gap-2 rounded-lg bg-emerald-500/20 px-4 py-3 text-sm font-semibold text-emerald-100 border border-emerald-400/40 shadow-sm transition hover:bg-emerald-500/30 disabled:cursor-not-allowed disabled:bg-slate-700/60 disabled:text-slate-400"
          >
            {isRunning ? (
              <>
                <Loader2 className="h-4 w-4 animate-spin" /> 執行中...
              </>
            ) : (
              <>
                <RefreshCw className="h-4 w-4" /> 執行測試
              </>
            )}
          </button>

          {/* Optuna 優化按鈕 - 僅在啟用時顯示 */}
          {optunaConfig.enabled && (
            <button
              type="button"
              disabled={isOptimizing || isRunning}
              onClick={handleStartOptimization}
              className="flex w-full items-center justify-center gap-2 rounded-lg bg-sky-500/20 px-4 py-3 text-sm font-semibold text-sky-100 border border-sky-400/40 shadow-sm transition hover:bg-sky-500/30 disabled:cursor-not-allowed disabled:bg-slate-700/60 disabled:text-slate-400"
            >
              {isOptimizing ? (
                <>
                  <Loader2 className="h-4 w-4 animate-spin" /> 優化中...
                </>
              ) : (
                <>
                  <Sparkles className="h-4 w-4" /> 開始優化 ({optunaConfig.n_trials} trials)
                </>
              )}
            </button>
          )}

          {validationErrors.length > 0 && (
            <div className="rounded-lg border border-amber-400/30 bg-amber-500/10 p-3 text-xs text-amber-200">
              <div className="mb-1 font-semibold">需先修正：</div>
              <ul className="list-inside list-disc space-y-1">
                {validationErrors.map((error) => (
                  <li key={error}>{error}</li>
                ))}
              </ul>
            </div>
          )}
        </div>

        <div className="space-y-4">
          <div className="glass-panel rounded-xl border border-slate-800/80 p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm uppercase tracking-wide text-slate-400">密度統計</p>
                <h2 className="text-2xl font-semibold text-slate-100">模型指標</h2>
              </div>
              <BarChart2 className="h-6 w-6 text-emerald-300" />
            </div>
            {/* 正例密度指標 */}
            <div className="mt-5">
              <div className="text-sm font-semibold text-slate-200 mb-3">正例密度指標</div>
              <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
                {densityMetrics?.positive_avg_density !== undefined && (
                  <StatMetricCard
                    label="正例近期密度"
                    value={densityMetrics.positive_avg_density}
                    std={densityMetrics.positive_std}
                    helper={`TO前${state.windowConfig.lookback_bars}根K線的策略信號密度`}
                    format="decimal"
                    colorCode={true}
                  />
                )}
                {densityMetrics?.positive_far_avg_density !== undefined && (
                  <StatMetricCard
                    label="正例遠期密度"
                    value={densityMetrics.positive_far_avg_density}
                    std={densityMetrics.positive_far_std}
                    helper={`TO-${state.windowConfig.far_lookback_bars}至TO-${state.windowConfig.lookback_bars + 1}根K線的背景密度`}
                    format="decimal"
                    colorCode={true}
                  />
                )}
                {densityMetrics?.positive_near_far_ratio !== undefined && (
                  <StatMetricCard
                    label="正例 Near/Far Ratio"
                    value={densityMetrics.positive_near_far_ratio}
                    std={densityMetrics.positive_ratio_std}
                    helper="近期密度 / 遠期密度"
                    format="ratio"
                    colorCode={true}
                  />
                )}
                {densityMetrics?.positive_sample_size !== undefined && (
                  <StatMetricCard
                    label="正例樣本數"
                    value={densityMetrics.positive_sample_size}
                    helper="有效的正例案例數量"
                    format="number"
                  />
                )}
                {densityMetrics?.positive_weighted_mean_m !== undefined && (
                  <StatMetricCard
                    label="正例 加權平均M 值"
                    value={densityMetrics.positive_weighted_mean_m}
                    std={densityMetrics.positive_m_std}
                    helper="歸一化指標 M ∈ [-1, 1]，越接近 1 表示信號越聚集於近期"
                    format="decimal"
                    colorCode={true}
                  />
                )}
                {densityMetrics?.positive_m_cv !== undefined && (
                  <StatMetricCard
                    label="正例 M 穩定性 CV"
                    value={densityMetrics.positive_m_cv}
                    helper="月度 M 值的變異係數 (<0.3穩定, <0.5可接受)"
                    format="decimal"
                    source={densityMetrics.excluded_months_count !== undefined
                      ? `${densityMetrics.included_months_count || 0}個月納入計算，${densityMetrics.excluded_months_count}個月排除`
                      : undefined}
                  />
                )}
              </div>
            </div>

            {/* 反例密度指標 */}
            <div className="mt-5">
              <div className="text-sm font-semibold text-slate-200 mb-3">反例密度指標</div>
              <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
                {densityMetrics?.negative_avg_density !== undefined && (
                  <StatMetricCard
                    label="反例近期密度"
                    value={densityMetrics.negative_avg_density}
                    std={densityMetrics.negative_std}
                    helper={`TO前${state.windowConfig.lookback_bars}根K線的策略信號密度`}
                    format="decimal"
                    colorCode={true}
                  />
                )}
                {densityMetrics?.negative_far_avg_density !== undefined && (
                  <StatMetricCard
                    label="反例遠期密度"
                    value={densityMetrics.negative_far_avg_density}
                    std={densityMetrics.negative_far_std}
                    helper={`TO-${state.windowConfig.far_lookback_bars}至TO-${state.windowConfig.lookback_bars + 1}根K線的背景密度`}
                    format="decimal"
                    colorCode={true}
                  />
                )}
                {densityMetrics?.negative_near_far_ratio !== undefined && (
                  <StatMetricCard
                    label="反例 Near/Far Ratio"
                    value={densityMetrics.negative_near_far_ratio}
                    std={densityMetrics.negative_ratio_std}
                    helper="近期密度 / 遠期密度"
                    format="ratio"
                    colorCode={true}
                  />
                )}
                {densityMetrics?.negative_sample_size !== undefined && (
                  <StatMetricCard
                    label="反例樣本數"
                    value={densityMetrics.negative_sample_size}
                    helper="有效的反例案例數量"
                    format="number"
                  />
                )}
                {densityMetrics?.negative_weighted_mean_m !== undefined && (
                  <StatMetricCard
                    label="反例 加權平均M 值"
                    value={densityMetrics.negative_weighted_mean_m}
                    std={densityMetrics.negative_m_std}
                    helper="歸一化指標 M ∈ [-1, 1]，反例應接近 0 或負值"
                    format="decimal"
                    colorCode={true}
                  />
                )}
              </div>
            </div>

            {/* M 值優化指標 (Golden Formula v2.0) */}
            {(densityMetrics?.m_separation !== undefined || densityMetrics?.optuna_golden_score !== undefined) && (
              <div className="mt-5">
                <div className="text-sm font-semibold text-slate-200 mb-3">M 值優化指標</div>
                <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
                  {densityMetrics?.m_separation !== undefined && (
                    <StatMetricCard
                      label="M Separation"
                      value={densityMetrics.m_separation}
                      helper="正反例 M 值差異 (μ_pos - μ_neg)"
                      format="decimal"
                      colorCode={true}
                      source="= 正例加權平均 M − 反例加權平均 M"
                    />
                  )}
                  {densityMetrics?.m_separation_cv !== undefined && (
                    <StatMetricCard
                      label="M Separation 穩定性"
                      value={densityMetrics.m_separation_cv}
                      helper="M Separation 月度穩定性 (<0.3穩定, <0.5可接受)"
                      format="decimal"
                      source="= Std(每月M差異) / |Mean(每月M差異)|"
                    />
                  )}
                  {densityMetrics?.optuna_golden_score !== undefined && (
                    <StatMetricCard
                      label="Golden Score"
                      value={densityMetrics.optuna_golden_score}
                      helper="黃金公式得分 (Optuna 優化目標)"
                      format="decimal"
                      colorCode={true}
                      source="= M Separation − λ×(σ_pos + 0.5×σ_neg)"
                    />
                  )}
                  {densityMetrics?.positive_total_weight !== undefined && (
                    <StatMetricCard
                      label="正例信號強度"
                      value={densityMetrics.positive_total_weight}
                      helper="正例權重總和 (Near + Far 信號數)"
                      format="decimal"
                      source={`有效案例: ${densityMetrics.positive_active_cases || 0}`}
                    />
                  )}
                  {densityMetrics?.negative_total_weight !== undefined && (
                    <StatMetricCard
                      label="反例信號強度"
                      value={densityMetrics.negative_total_weight}
                      helper="反例權重總和 (Near + Far 信號數)"
                      format="decimal"
                      source={`有效案例: ${densityMetrics.negative_active_cases || 0}`}
                    />
                  )}
                </div>
              </div>
            )}

            {/* 統計檢驗指標 */}
            <div className="mt-5">
              <div className="text-sm font-semibold text-slate-200 mb-3">統計檢驗指標</div>
              <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
                {densityMetrics?.separation !== undefined && (
                  <StatMetricCard
                    label="Density Separation"
                    value={densityMetrics.separation}
                    helper="正反例密度差異 (優化目標)"
                    format="decimal"
                    source="= 正例 Near 密度均值 − 反例 Near 密度均值"
                  />
                )}
                {densityMetrics?.ratio_separation !== undefined && (
                  <StatMetricCard
                    label="Ratio Separation"
                    value={densityMetrics.ratio_separation}
                    helper="正反例比率差異 (雙密度優化目標)"
                    format="decimal"
                    source="= 正例 Near/Far Ratio − 反例 Near/Far Ratio"
                  />
                )}
                {densityMetrics?.p_value !== undefined && (
                  <StatMetricCard
                    label="p-value"
                    value={densityMetrics.p_value}
                    helper="統計顯著性 (<0.05為顯著)"
                    format="decimal"
                    source="獨立 t-test: 正例 M 值 vs 反例 M 值"
                  />
                )}
                {densityMetrics?.cohens_d !== undefined && (
                  <StatMetricCard
                    label="Cohen's d"
                    value={densityMetrics.cohens_d}
                    helper="效果量 (>0.5為中等, >0.8為大效果)"
                    format="decimal"
                    source="= (正例 M 均值 − 反例 M 均值) / 合併標準差"
                  />
                )}
                {densityMetrics?.stability_cv !== undefined && (
                  <StatMetricCard
                    label="Stability CV"
                    value={densityMetrics.stability_cv}
                    helper="穩定性係數 (<0.3穩定, <0.5可接受)"
                    format="decimal"
                    source="= 正例每月 Near 密度均值的標準差 / 整體均值"
                  />
                )}
                {densityMetrics?.positive_ratio_cv !== undefined && (
                  <StatMetricCard
                    label="正例 Ratio 穩定性"
                    value={densityMetrics.positive_ratio_cv}
                    helper="正例 Near/Far Ratio 跨月穩定性 (<0.3穩定, <0.5可接受)"
                    format="decimal"
                    source="= 每月正例 Ratio 均值的標準差 / 整體 Ratio 均值"
                  />
                )}
                {densityMetrics?.separation_cv !== undefined && (
                  <StatMetricCard
                    label="Separation 穩定性"
                    value={densityMetrics.separation_cv}
                    helper="每月分離度穩定性 (<0.3穩定, <0.5可接受)"
                    format="decimal"
                    source="= 每月 Separation 的標準差 / |Separation 均值|"
                  />
                )}
              </div>
            </div>

            {/* 樣本不足警告 */}
            {densityMetrics?.sample_warnings && densityMetrics.sample_warnings.length > 0 && (
              <div className="mt-4 rounded-lg border border-amber-400/30 bg-amber-500/10 p-4">
                <div className="flex items-center gap-2 text-amber-200">
                  <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                  </svg>
                  <span className="text-sm font-medium">樣本警告</span>
                </div>
                <ul className="mt-2 list-inside list-disc text-xs text-amber-200/80">
                  {densityMetrics.sample_warnings.map((warning, i) => (
                    <li key={i}>{warning}</li>
                  ))}
                </ul>
                {densityMetrics.excluded_months_count !== undefined && densityMetrics.excluded_months_count > 0 && (
                  <p className="mt-2 text-xs text-amber-200/70">
                    {densityMetrics.excluded_months_count} 個月份因樣本不足被排除於穩定性計算
                    {densityMetrics.included_months_count !== undefined && (
                      <span>（納入 {densityMetrics.included_months_count} 個月份）</span>
                    )}
                  </p>
                )}
              </div>
            )}

            {/* 零值統計 (v1.1 新增) */}
            {(densityMetrics?.positive_far_zero_count !== undefined ||
              densityMetrics?.negative_far_zero_count !== undefined) && (
              <div className="mt-5">
                <div className="text-sm font-semibold text-slate-200 mb-3">零值統計 (透明化)</div>
                <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
                  <div className="glass-panel p-4 rounded-lg border border-slate-800/80">
                    <div className="text-sm font-medium text-slate-400 mb-1">正例 Near=0</div>
                    <div className="text-2xl font-bold text-slate-100">
                      {densityMetrics.positive_near_zero_count ?? 0}
                      <span className="text-base font-normal text-slate-400 ml-2">
                        ({((densityMetrics.positive_near_zero_ratio ?? 0) * 100).toFixed(1)}%)
                      </span>
                    </div>
                    <div className="text-xs text-slate-500 mt-2">策略信號完全未觸發的案例</div>
                  </div>
                  <div className="glass-panel p-4 rounded-lg border border-slate-800/80">
                    <div className="text-sm font-medium text-slate-400 mb-1">正例 Far=0</div>
                    <div className="text-2xl font-bold text-amber-300">
                      {densityMetrics.positive_far_zero_count ?? 0}
                      <span className="text-base font-normal text-slate-400 ml-2">
                        ({((densityMetrics.positive_far_zero_ratio ?? 0) * 100).toFixed(1)}%)
                      </span>
                    </div>
                    <div className="text-xs text-slate-500 mt-2">被排除於 ratio 統計的案例</div>
                  </div>
                  <div className="glass-panel p-4 rounded-lg border border-slate-800/80">
                    <div className="text-sm font-medium text-slate-400 mb-1">反例 Near=0</div>
                    <div className="text-2xl font-bold text-slate-100">
                      {densityMetrics.negative_near_zero_count ?? 0}
                      <span className="text-base font-normal text-slate-400 ml-2">
                        ({((densityMetrics.negative_near_zero_ratio ?? 0) * 100).toFixed(1)}%)
                      </span>
                    </div>
                    <div className="text-xs text-slate-500 mt-2">策略信號完全未觸發的案例</div>
                  </div>
                  <div className="glass-panel p-4 rounded-lg border border-slate-800/80">
                    <div className="text-sm font-medium text-slate-400 mb-1">反例 Far=0</div>
                    <div className="text-2xl font-bold text-amber-300">
                      {densityMetrics.negative_far_zero_count ?? 0}
                      <span className="text-base font-normal text-slate-400 ml-2">
                        ({((densityMetrics.negative_far_zero_ratio ?? 0) * 100).toFixed(1)}%)
                      </span>
                    </div>
                    <div className="text-xs text-slate-500 mt-2">被排除於 ratio 統計的案例</div>
                  </div>
                </div>
              </div>
            )}
            {!densityMetrics && (
              <p className="mt-4 rounded-lg bg-slate-900/60 px-3 py-2 text-xs text-slate-400">
                後端尚未回傳密度統計，或尚未執行測試。
              </p>
            )}
          </div>

          {/* Combined Boxplot 密度分佈視覺化 - 三種指標橫向對比 */}
          {densityMetrics &&
            positiveCaseIds.length > 0 &&
            negativeCaseIds.length > 0 &&
            Object.keys(caseLevelDensities).length > 0 && (
              <CombinedDensityBoxplot
                caseLevelDensities={caseLevelDensities}
                positiveCases={positiveCaseIds}
                negativeCases={negativeCaseIds}
                title="密度分佈對比 (Near / Far / Ratio)"
              />
            )}

          <div className="glass-panel rounded-xl border border-slate-800/80 p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm uppercase tracking-wide text-slate-400">時間範圍統計</p>
                <h2 className="text-2xl font-semibold text-slate-100">測試結果</h2>
              </div>
              <Share2 className="h-6 w-6 text-emerald-300" />
            </div>
            {testResult ? (
              <div className="mt-6 grid gap-4 md:grid-cols-2">
                <SummaryItem label="時間範圍內信號數" value={formatCount(testResult.signal_count)} />
                <SummaryItem label="時間範圍內K線數" value={formatCount(testResult.total_bars)} />
                <SummaryItem
                  label="計算耗時"
                  value={
                    testResult.metadata?.calculation_time_ms !== undefined
                      ? `${testResult.metadata.calculation_time_ms.toFixed(1)} ms`
