"use client";

import { useState, useEffect } from "react";

interface BatchDownloadPanelProps {
  totalCases: number;
  onDownloadComplete?: () => void;
}

interface DownloadProgress {
  task_id: string;
  status: "pending" | "running" | "completed" | "failed";
  total_cases: number;
  completed_cases: number;
  failed_cases: number;
  progress_percent: number;
  current_symbol?: string;
  estimated_time_remaining?: number;
  failed_case_ids: string[];
  error_messages: string[];
}

export default function BatchDownloadPanel({
  totalCases,
  onDownloadComplete,
}: BatchDownloadPanelProps) {
  const [warmupBars, setWarmupBars] = useState(150); // 新增：Warmup期K線數
  const [lookbackBars, setLookbackBars] = useState(100);
  const [forwardBars, setForwardBars] = useState(48);
  const [downloadTimeframe, setDownloadTimeframe] = useState("1h"); // 新增：K線下載時間框架（預設1h）
  const [downloading, setDownloading] = useState(false);
  const [taskId, setTaskId] = useState<string | null>(null);
  const [progress, setProgress] = useState<DownloadProgress | null>(null);
  const [error, setError] = useState<string | null>(null);

  // 輪詢進度（優化版：動態間隔）
  useEffect(() => {
    if (!taskId) return;

    let pollCount = 0;
    let timeoutId: NodeJS.Timeout;

    const pollProgress = async () => {
      try {
        const response = await fetch(
          `/api/v1/kline/download-status/${taskId}`
        );

        if (!response.ok) {
          throw new Error("Failed to fetch progress");
        }

        const data: DownloadProgress = await response.json();
        setProgress(data);

        // 如果任務完成或失敗，停止輪詢
        if (data.status === "completed" || data.status === "failed") {
          setDownloading(false);

          if (data.status === "completed" && onDownloadComplete) {
            onDownloadComplete();
          }
          return;
        }

        // 動態調整輪詢間隔：從1秒開始，逐漸增加到3秒
        pollCount++;
        const interval = Math.min(1000 + pollCount * 200, 3000);

        // 繼續輪詢
        timeoutId = setTimeout(pollProgress, interval);
      } catch (err) {
        console.error("Failed to fetch progress:", err);

        // 錯誤時使用較長間隔重試（5秒）
        timeoutId = setTimeout(pollProgress, 5000);
      }
    };

    // 開始輪詢
    pollProgress();

    // 清理函數
    return () => {
      if (timeoutId) {
        clearTimeout(timeoutId);
      }
    };
  }, [taskId, onDownloadComplete]);

  const handleStartDownload = async () => {
    setDownloading(true);
    setError(null);
    setProgress(null);

    // 計算總lookback（warmup + 有效K線）
    const totalLookbackBars = warmupBars + lookbackBars;

    // 保存lookback/forward設定到localStorage，供圖表頁面使用
    localStorage.setItem('kline_warmup_bars', warmupBars.toString());
    localStorage.setItem('kline_lookback_bars', lookbackBars.toString());
    localStorage.setItem('kline_forward_bars', forwardBars.toString());

    try {
      const response = await fetch("/api/v1/kline/batch-download", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          case_ids: null, // 下載全部案例
          lookback_bars: lookbackBars, // 傳送真正的 lookback（不含 warmup）
          warmup_bars: warmupBars, // 明確傳送 warmup_bars
          forward_bars: forwardBars,
          force_redownload: false,
          timeframe: downloadTimeframe, // 新增：K線下載時間框架
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || "Download failed");
      }

      const data = await response.json();
      setTaskId(data.task_id);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Download failed");
      setDownloading(false);
    }
  };

  return (
    <div className="glass-panel rounded-xl p-6 border border-white/10">
      <h3 className="text-lg font-semibold text-slate-100 mb-4">批量K線下載</h3>

      {totalCases === 0 && (
        <div className="mb-4 p-3 bg-amber-500/10 border border-amber-400/30 rounded">
          <p className="text-sm font-medium text-amber-200">
            請先導入案例CSV文件
          </p>
        </div>
      )}

      {/* Configuration */}
      <div className="mb-4 grid grid-cols-2 gap-4">
        {/* K線時間框架選擇器 */}
        <div>
          <label className="block text-sm font-medium text-slate-300 mb-2">
            K線時間框架
          </label>
          <select
            value={downloadTimeframe}
            onChange={(e) => setDownloadTimeframe(e.target.value)}
            className="w-full border border-slate-700 rounded px-3 py-2 bg-slate-900/60 text-slate-100 font-medium focus:border-blue-400/40 focus:ring-1 focus:ring-blue-400/40"
            disabled={downloading}
          >
            <option value="1m">1 分鐘</option>
            <option value="5m">5 分鐘</option>
            <option value="15m">15 分鐘</option>
            <option value="30m">30 分鐘</option>
            <option value="1h">1 小時 (預設)</option>
            <option value="4h">4 小時</option>
            <option value="12h">12 小時</option>
            <option value="1d">1 天</option>
          </select>
          <p className="text-xs text-slate-400 mt-1 font-medium">
            用於ML訓練（與案例搜尋時間框架獨立）
          </p>
        </div>

        {/* 新增：Warmup期輸入框 */}
        <div>
          <label className="block text-sm font-medium text-slate-300 mb-2">
            Warmup期K線數
          </label>
          <input
            type="number"
            value={warmupBars}
            onChange={(e) => setWarmupBars(Number(e.target.value))}
            min={0}
            max={500}
            className="w-full border border-slate-700 rounded px-3 py-2 bg-slate-900/60 text-slate-100 font-medium focus:border-blue-400/40 focus:ring-1 focus:ring-blue-400/40"
            disabled={downloading}
            placeholder="150"
          />
          <p className="text-xs text-slate-500 mt-1 font-medium">
            建議：最長EMA週期×4.5 (例如：EMA50 → 225)
          </p>
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-300 mb-2">
            TO前有效K線數（不含Warmup）
          </label>
          <input
            type="number"
            value={lookbackBars}
            onChange={(e) => setLookbackBars(Number(e.target.value))}
            min={1}
            max={1000}
            className="w-full border border-slate-700 rounded px-3 py-2 bg-slate-900/60 text-slate-100 font-medium focus:border-blue-400/40 focus:ring-1 focus:ring-blue-400/40"
            disabled={downloading}
            placeholder="100"
          />
          <p className="text-xs text-blue-300 mt-1 font-medium">
            密度計算基數（實際有效K線數）
          </p>
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-300 mb-2">
            往後K線根數 (Forward)
          </label>
          <input
            type="number"
            value={forwardBars}
            onChange={(e) => setForwardBars(Number(e.target.value))}
            min={1}
            max={500}
            className="w-full border border-slate-700 rounded px-3 py-2 bg-slate-900/60 text-slate-100 font-medium focus:border-blue-400/40 focus:ring-1 focus:ring-blue-400/40"
            disabled={downloading}
            placeholder="48"
          />
          <p className="text-xs text-slate-400 mt-1 font-medium">
            範圍: 1-500（預設: 48）
          </p>
        </div>
      </div>

      {/* Download Info */}
      <div className="mb-4 p-3 bg-blue-500/10 border border-blue-400/30 rounded">
        <p className="text-sm font-semibold text-blue-200 mb-2">
          下載配置
        </p>
        <p className="text-sm font-medium text-slate-300 mb-1">
          案例數量：<span className="font-semibold text-blue-300">{totalCases}</span> 個
        </p>
        <p className="text-sm font-medium text-slate-300 mb-1">
          時間框架：<span className="font-semibold text-blue-300">{downloadTimeframe}</span>
        </p>
        <p className="text-sm font-semibold text-slate-100 mt-2 mb-1">
          每個案例下載：
        </p>
        <p className="text-sm font-medium text-slate-300">
          <span className="font-semibold text-blue-300">{warmupBars + lookbackBars + forwardBars}</span> 根K線
          <span className="text-slate-500 text-xs ml-2">
            = {warmupBars} (Warmup) + {lookbackBars} (有效) + {forwardBars} (往後)
          </span>
        </p>
        <p className="text-xs text-emerald-300 mt-2 font-medium">
          ✓ 密度計算基數：{lookbackBars} 根有效K線
        </p>
      </div>

      {/* Download Button */}
      <button
        onClick={handleStartDownload}
        disabled={totalCases === 0 || downloading}
        className={`w-full py-3 px-4 rounded-lg font-semibold transition-colors ${
          totalCases === 0 || downloading
            ? "bg-slate-700/60 text-slate-400 cursor-not-allowed"
            : "bg-emerald-500/20 text-emerald-100 border border-emerald-400/40 hover:bg-emerald-500/30"
        }`}
      >
        {downloading ? "下載中..." : "開始批量下載"}
      </button>

      {/* Error Message */}
      {error && (
        <div className="mt-4 p-3 bg-rose-500/10 border border-rose-400/30 rounded">
          <p className="text-sm font-medium text-rose-200">{error}</p>
        </div>
      )}

      {/* Progress Bar */}
      {progress && (
        <div className="mt-4">
          <div className="mb-2 flex justify-between text-sm font-medium text-slate-100">
            <span>進度: {progress.completed_cases} / {progress.total_cases}</span>
            <span className="font-semibold">{progress.progress_percent.toFixed(1)}%</span>
          </div>

          <div className="w-full bg-slate-800 rounded-full h-4 overflow-hidden">
            <div
              className={`h-full transition-all duration-300 ${
                progress.status === "completed"
                  ? "bg-emerald-500"
                  : progress.status === "failed"
                  ? "bg-rose-500"
                  : "bg-blue-400"
              }`}
              style={{ width: `${progress.progress_percent}%` }}
            ></div>
          </div>

          {/* Status Info */}
          <div className="mt-3 text-sm font-medium text-slate-100">
            <div className="grid grid-cols-2 gap-2">
              <div>狀態: <span className="font-semibold">{progress.status}</span></div>
              <div>當前: <span className="font-semibold">{progress.current_symbol || "N/A"}</span></div>
              <div>成功: <span className="text-emerald-300 font-semibold">{progress.completed_cases}</span></div>
              <div>失敗: <span className="text-rose-300 font-semibold">{progress.failed_cases}</span></div>
            </div>

            {progress.estimated_time_remaining && (
              <div className="mt-2 text-slate-300 font-medium">
                預估剩餘時間: {Math.round(progress.estimated_time_remaining / 60)} 分鐘
              </div>
            )}
          </div>

          {/* Failed Cases */}
          {progress.failed_case_ids.length > 0 && (
            <div className="mt-4 p-3 bg-rose-500/10 border border-rose-400/30 rounded">
              <p className="text-sm font-semibold text-rose-200 mb-2">
                失敗案例 ({progress.failed_case_ids.length}):
              </p>
              <ul className="list-disc list-inside text-sm font-medium text-rose-200/80">
                {progress.failed_case_ids.slice(0, 5).map((caseId, idx) => (
                  <li key={idx}>{caseId}</li>
                ))}
                {progress.failed_case_ids.length > 5 && (
                  <li className="text-slate-500">
                    ...還有 {progress.failed_case_ids.length - 5} 個
                  </li>
                )}
              </ul>

              {progress.error_messages.length > 0 && (
                <div className="mt-2">
                  <p className="text-sm font-semibold text-rose-200 mb-1">錯誤訊息:</p>
                  <ul className="list-disc list-inside text-sm text-rose-200/80">
                    {progress.error_messages.slice(0, 3).map((msg, idx) => (
                      <li key={idx}>{msg}</li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          )}

          {/* Completion Message */}
          {progress.status === "completed" && (
            <div className="mt-4 p-3 bg-emerald-500/10 border border-emerald-400/30 rounded">
              <p className="text-sm text-emerald-200 font-semibold">
                ✅ 批量下載完成！
                成功: {progress.completed_cases}, 失敗: {progress.failed_cases}
              </p>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/**
 * StrategySignalChart.tsx - 帶策略信號標記的價格圖表
 *
 * Phase 3.3+3.4 - Task C1: 圖表信號標記整合
 *
 * 功能:
 * - 繼承 PriceChart 的所有功能
 * - 添加策略信號箭頭標記 (綠色向上箭頭)
 * - 支持最多 500 個信號標記
 * - 懸停顯示信號詳情 (指標數值、信號密度)
 * - 與 TO/TC 標記區分顯示
 *
 * Ultra Think 記錄:
 * - 步驟 1: 初版代碼 (當前)
 * - 步驟 2: 審查優化 (待執行)
 * - 步驟 3: 最終優化 (待執行)
 */

"use client";

import { useEffect, useState, useRef } from "react";
import { useChartSync } from "@/hooks/useChartSync";
import { darkChartOptions } from "@/utils/chartConfig";
import {
  candlestickSeriesOptions,
  formatTime,
  formatPrice,
  formatVolume,
  chartColors,
} from "@/utils/chartConfig";
import {
  ISeriesApi,
  SeriesMarker,
  Time,
  MouseEventParams,
  UTCTimestamp,
} from "lightweight-charts";
import type { IndicatorLineSeries } from "./TradingChartWithSignals";

const toUtcTime = (timestamp: number): UTCTimestamp =>
  timestamp as UTCTimestamp;

const extractNumericTime = (time: Time | undefined): number | null =>
  typeof time === "number" ? time : null;
 // moved above

/**
 * K線數據接口
 */
export interface KlineData {
  timestamp: number;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
  taker_buy_volume?: number;
  taker_ratio?: number;
  quote_volume?: number;
  number_of_trades?: number;
}

/**
 * 策略信號點接口
 */
export interface SignalPoint {
  timestamp: number;
  indicator_values: Record<string, number>; // 例: { ema_short: 7, ema_mid: 18, ema_long: 35 }
  signal_density?: number; // 信號密度 (0-1)
  windowType?: 'near' | 'far'; // 窗口類型: 近期窗口或遠期窗口
}

/**
 * 懸停信號資訊
 */
export interface HoveredSignalInfo {
  timestamp: number;
  indicator_values: Record<string, number>;
  signal_density?: number;
  price: number;
}

/**
 * StrategySignalChart 組件 Props
 */
export interface StrategySignalChartProps {
  /**
   * 交易對 symbol
   */
  symbol: string;

  /**
   * 時間框架
   */
  timeframe: string;

  /**
   * K線數據數組
   */
  klines: KlineData[];

  /**
   * 策略信號點數組 (最多 500 個)
   */
  signalPoints?: SignalPoint[];

  /**
   * 案例時間點 T (Unix 秒)
   */
  caseTimestamp?: number;

  /**
   * TO 時間戳 (對齊後的案例開始時間)
   */
  toTimestamp?: number;

  /**
   * TC 時間戳 (對齊後的案例結束時間)
   */
  tcTimestamp?: number;

  /**
   * 圖表高度 (像素)
   */
  height?: number;

  /**
   * 是否顯示案例標記 (TO/TC)
   */
  showCaseMarker?: boolean;

  /**
   * 是否顯示策略信號標記
   */
  showSignalMarkers?: boolean;

  /**
   * 圖表唯一ID (用於同步)
   */
  chartId?: string;

  /**
   * 是否啟用同步
   */
  enableSync?: boolean;

  /**
   * 信號點擊回調
   */
  onSignalClick?: (signal: SignalPoint) => void;

  /**
   * 信號懸停回調
   */
  onSignalHover?: (signal: HoveredSignalInfo | null) => void;

  /**
   * 指標線資料
   */
  indicatorSeries?: IndicatorLineSeries[];
}

/**
 * StrategySignalChart 組件 - 帶策略信號標記的價格圖表
 */
export function StrategySignalChart({
  symbol,
  timeframe,
  klines,
  signalPoints = [],
  caseTimestamp,
  toTimestamp,
  tcTimestamp,
  height = 400,
  showCaseMarker = true,
  showSignalMarkers = true,
  chartId = "strategy-signal-chart",
  enableSync = false,
  onSignalClick,
  onSignalHover,
  indicatorSeries = [],
}: StrategySignalChartProps) {

  const { chartContainerRef, chartInstance, isReady } = useChartSync({
    chartId,
    toTimestamp: toTimestamp || caseTimestamp || 0,
    enableSync,
    debug: true,
    chartOptions: darkChartOptions,
  });

  // 狀態管理
  const [error, setError] = useState<string | null>(null);
  const [hoveredData, setHoveredData] = useState<KlineData | null>(null);
  const [hoveredSignal, setHoveredSignal] = useState<SignalPoint | null>(null);
  const [hoveredIndicators, setHoveredIndicators] = useState<Record<string, number>>({});

  // 保存 series 引用，用於 cleanup
  const candlestickSeriesRef = useRef<ISeriesApi<"Candlestick"> | null>(null);
  const indicatorLineRefs = useRef<ISeriesApi<"Line">[]>([]);

  // 追蹤用戶是否手動縮放了 Y 軸
  const userScaledYAxisRef = useRef(false);

  // 使用 ref 存儲回調函數，避免依賴變化導致 useEffect 重新執行
  const onSignalHoverRef = useRef(onSignalHover);
  const onSignalClickRef = useRef(onSignalClick);

  // 使用 ref 緩存 indicatorSeries，避免不必要的重渲染
  const indicatorSeriesRef = useRef(indicatorSeries);

  // 更新 ref 當 props 變化時
  useEffect(() => {
    onSignalHoverRef.current = onSignalHover;
    onSignalClickRef.current = onSignalClick;
    indicatorSeriesRef.current = indicatorSeries;
  }, [onSignalHover, onSignalClick, indicatorSeries]);

  // 更新 indicatorSeries ref（淺比較）
  useEffect(() => {
    indicatorSeriesRef.current = indicatorSeries;
  }, [indicatorSeries]);

  /**
   * 獨立的 Y 軸縮放控制 useEffect
   * 這個 useEffect 只依賴 chartInstance 和 isReady，不會因為其他狀態變化而重新執行
   */
  useEffect(() => {
    if (!chartInstance || !isReady) return;

    const container = chartContainerRef.current;
    if (!container) return;

    const priceScale = chartInstance.priceScale('right');

    const handleMouseDown = (e: MouseEvent) => {
      // 檢查是否點擊在右側 Y 軸區域（大約右邊 60px）
      const rect = container.getBoundingClientRect();
      const clickX = e.clientX - rect.left;
      const isYAxisArea = clickX > rect.width - 60;

      if (isYAxisArea) {
        // 用戶開始拖曳 Y 軸
        const handleMouseUp = () => {
          // 拖曳結束後，禁用 autoScale 以維持縮放
          userScaledYAxisRef.current = true;
          priceScale.applyOptions({ autoScale: false });
          document.removeEventListener('mouseup', handleMouseUp);
        };
        document.addEventListener('mouseup', handleMouseUp);
      }
    };

    // 雙擊重置 Y 軸
    const handleDoubleClick = (e: MouseEvent) => {
      const rect = container.getBoundingClientRect();
      const clickX = e.clientX - rect.left;
      const isYAxisArea = clickX > rect.width - 60;

      if (isYAxisArea) {
        userScaledYAxisRef.current = false;
        priceScale.applyOptions({ autoScale: true });
      }
    };

    container.addEventListener('mousedown', handleMouseDown);
    container.addEventListener('dblclick', handleDoubleClick);

    return () => {
      container.removeEventListener('mousedown', handleMouseDown);
      container.removeEventListener('dblclick', handleDoubleClick);
    };
  }, [chartInstance, isReady]);

  /**
   * 渲染 K線數據和信號標記到圖表
   */
  useEffect(() => {
    if (!chartInstance || !isReady || !klines || klines.length === 0) {
      return;
    }

    try {
      // 添加 K線系列
      const candlestickSeries =
        chartInstance.addCandlestickSeries(candlestickSeriesOptions);
      candlestickSeriesRef.current = candlestickSeries;

      // 配置 right price scale - 根據用戶是否已縮放來決定 autoScale
      const priceScale = chartInstance.priceScale('right');
      priceScale.applyOptions({
        autoScale: !userScaledYAxisRef.current,
        scaleMargins: {
          top: 0.1,
          bottom: 0.1,
        },
      });

      // 轉換數據格式 (Lightweight Charts 格式)
      const formattedKlines = klines.map((kline) => ({
        time: toUtcTime(kline.timestamp),
        open: kline.open,
        high: kline.high,
        low: kline.low,
        close: kline.close,
      }));

      // 設置 K線數據
      candlestickSeries.setData(formattedKlines);

      // 構建標記數組
      const markers: SeriesMarker<UTCTimestamp>[] = [];

      // 1. 添加 TO/TC 標記 (案例標記)
      if (showCaseMarker) {
        if (toTimestamp && tcTimestamp) {
          // 標記 TO 和 TC 兩個點
          markers.push({
            time: toUtcTime(toTimestamp),
            position: "aboveBar" as const,
            color: "#60a5fa", // 藍色 - TO
            shape: "arrowDown" as const,
            text: "TO",
          });
          markers.push({
            time: toUtcTime(tcTimestamp),
            position: "aboveBar" as const,
            color: "#fb923c", // 橙色 - TC
            shape: "arrowDown" as const,
            text: "TC",
          });
        } else if (caseTimestamp) {
          // 只標記一個 T 點 (向後兼容)
          markers.push({
            time: toUtcTime(caseTimestamp),
            position: "aboveBar" as const,
            color: chartColors.caseMarkerColor,
            shape: "arrowDown" as const,
            text: "T",
          });
        }
      }

      // 2. 添加策略信號標記 (根據窗口類型使用不同顏色)
      if (showSignalMarkers && signalPoints.length > 0) {
        signalPoints.forEach((signal) => {
          // 根據 windowType 決定顏色: 近期窗口藍色，遠期窗口土黃色
          const color = signal.windowType === 'near' ? '#60a5fa' : '#fbbf24';
          const text = signal.windowType === 'near' ? 'N' : 'F';

          markers.push({
            time: toUtcTime(signal.timestamp),
            position: "belowBar" as const,
            color: color,
            shape: "arrowUp" as const,
            text: text,
            id: `signal-${signal.timestamp}`,
          });
        });
      }

      // 按時間排序標記（Lightweight Charts 要求）
      markers.sort((a, b) => (a.time as number) - (b.time as number));

      // 設置所有標記
      candlestickSeries.setMarkers(markers);

      // 不再手動設置可見範圍，讓同步機制控制
      // 首次載入時使用 fitContent，但只在非同步模式下
      if (!enableSync && formattedKlines.length > 0) {
        chartInstance.timeScale().fitContent();
      }

      // 訂閱懸停事件 (用於顯示 OHLCV 和信號資訊)
      const handleCrosshairMove = (param: MouseEventParams<Time>) => {
        const hoveredTime = extractNumericTime(param.time);

        if (hoveredTime !== null) {
          // 查找懸停的 K線
          const hoveredKline = klines.find((k) => k.timestamp === hoveredTime);
          if (hoveredKline) {
            setHoveredData(hoveredKline);
          }

          // 查找懸停的指標值
          const indicatorValues: Record<string, number> = {};
          indicatorSeriesRef.current.forEach((series) => {
            const point = series.data.find((d) => d.time === hoveredTime);
            if (point) {
              indicatorValues[series.id] = point.value;
            }
          });
          setHoveredIndicators(indicatorValues);

          // 查找懸停的信號點
          const hoveredSignalPoint = signalPoints.find(
            (s) => s.timestamp === hoveredTime
          );
          if (hoveredSignalPoint) {
            setHoveredSignal(hoveredSignalPoint);

            // 觸發回調（使用 ref 避免依賴問題）
            if (onSignalHoverRef.current) {
              const price =
                hoveredKline?.close || klines[klines.length - 1].close;
              onSignalHoverRef.current({
                timestamp: hoveredSignalPoint.timestamp,
                indicator_values: hoveredSignalPoint.indicator_values,
                signal_density: hoveredSignalPoint.signal_density,
                price,
              });
            }
          } else {
            setHoveredSignal(null);
            if (onSignalHoverRef.current) {
              onSignalHoverRef.current(null);
            }
          }
        } else {
          setHoveredData(null);
          setHoveredSignal(null);
          setHoveredIndicators({});
          if (onSignalHoverRef.current) {
            onSignalHoverRef.current(null);
          }
        }
      };

      chartInstance.subscribeCrosshairMove(handleCrosshairMove);

      // 訂閱點擊事件 (用於信號點擊)
      const handleClick = (param: MouseEventParams<Time>) => {
        const clickedTime = extractNumericTime(param.time);
        if (clickedTime !== null && onSignalClickRef.current) {
          const clickedSignal = signalPoints.find(
            (s) => s.timestamp === clickedTime
          );
          if (clickedSignal) {
            onSignalClickRef.current(clickedSignal);
          }
        }
      };

      chartInstance.subscribeClick(handleClick);

      // cleanup 函數: 移除 series 和事件訂閱
      return () => {
        try {
          chartInstance.unsubscribeCrosshairMove(handleCrosshairMove);
          chartInstance.unsubscribeClick(handleClick);
          indicatorLineRefs.current.forEach((line) => {
            try {
              chartInstance.removeSeries(line);
            } catch (err) {
              console.error("[StrategySignalChart] Indicator cleanup error", err);
            }
          });
          indicatorLineRefs.current = [];
          if (candlestickSeries) {
            chartInstance.removeSeries(candlestickSeries);
          }
        } catch (err) {
          console.error("[StrategySignalChart] Cleanup error:", err);
        }
      };
    } catch (err) {
      console.error("[StrategySignalChart] Failed to render chart:", err);
      setError(
        err instanceof Error ? err.message : "Failed to render chart"
      );
    }
  }, [
    chartInstance,
    isReady,
    klines,
    signalPoints,
    caseTimestamp,
    toTimestamp,
    tcTimestamp,
    showCaseMarker,
    showSignalMarkers,
    symbol,
    enableSync,
  ]);

  /**
   * 指標線渲染 useEffect
   * 使用 JSON 字符串比較來避免不必要的重渲染
   */
  const prevIndicatorSeriesJsonRef = useRef<string>("");

  useEffect(() => {
    if (!chartInstance || !isReady) return;

    // 序列化當前 indicatorSeries 用於比較
    const currentJson = JSON.stringify(
      indicatorSeries.map(s => ({ id: s.id, color: s.color, dataLength: s.data.length }))
    );

    // 如果內容相同，跳過更新
    if (currentJson === prevIndicatorSeriesJsonRef.current && indicatorLineRefs.current.length > 0) {
      return;
    }

    // 更新緩存
    prevIndicatorSeriesJsonRef.current = currentJson;

    // 清除舊的指標線
    indicatorLineRefs.current.forEach((line) => {
      try {
        chartInstance.removeSeries(line);
      } catch (err) {
        console.error("[StrategySignalChart] Indicator cleanup error", err);
      }
    });
    indicatorLineRefs.current = [];

    // 添加新的指標線
    indicatorSeries.forEach((series) => {
      if (!series.data.length) return;
      const line = chartInstance.addLineSeries({
        color: series.color,
        lineWidth: 2,
        priceScaleId: "right",
        lastValueVisible: false,
        priceLineVisible: false,
      });
      line.setData(
        series.data.map((point) => ({
          time: toUtcTime(point.time),
          value: point.value,
        }))
      );
      indicatorLineRefs.current.push(line);
    });

    return () => {
      indicatorLineRefs.current.forEach((line) => {
        try {
          chartInstance.removeSeries(line);
        } catch (err) {
          console.error("[StrategySignalChart] Indicator cleanup error", err);
        }
      });
      indicatorLineRefs.current = [];
    };
  }, [chartInstance, indicatorSeries, isReady]);

  return (
    <div
      className="w-full flex flex-col bg-[#0A0F1C]"
      style={{ height: `${height}px` }}
    >
      {/* 頂部資訊欄 */}
      <div className="px-4 py-2 border-b border-white/10 flex items-center justify-between">
        <div className="flex items-center gap-4">
          <h3 className="text-sm font-semibold text-slate-100">
            {symbol} / {timeframe}
          </h3>
          <span className="text-xs text-slate-400">策略信號圖表</span>

          {/* 信號統計 - 顯示 Near(藍) 和 Far(土黃) 計數 */}
          {showSignalMarkers && signalPoints.length > 0 && (
            <div className="flex items-center gap-2">
              <span className="text-xs px-2 py-0.5 bg-blue-400/15 text-blue-300 rounded flex items-center gap-1">
                <span style={{ color: '#60a5fa' }}>▼</span>
                N: {signalPoints.filter(s => s.windowType === 'near').length}
              </span>
              <span className="text-xs px-2 py-0.5 bg-amber-400/15 text-amber-300 rounded flex items-center gap-1">
                <span style={{ color: '#fbbf24' }}>▼</span>
                F: {signalPoints.filter(s => s.windowType === 'far').length}
              </span>
            </div>
          )}
        </div>

        {/* OHLCV 懸停資訊 */}
        {hoveredData && (
          <div className="flex items-center gap-3 text-xs flex-wrap">
            <span className="text-slate-300">
              O: <span className="font-mono">{formatPrice(hoveredData.open)}</span>
            </span>
            <span className="text-slate-300">
              H: <span className="font-mono">{formatPrice(hoveredData.high)}</span>
            </span>
            <span className="text-slate-300">
              L: <span className="font-mono">{formatPrice(hoveredData.low)}</span>
            </span>
            <span className="text-slate-300">
              C:{" "}
              <span
                className={`font-mono ${
                  hoveredData.close >= hoveredData.open
                    ? "text-emerald-400"
                    : "text-rose-400"
                }`}
              >
                {formatPrice(hoveredData.close)}
              </span>
            </span>
            <span className="text-slate-300">
              V: <span className="font-mono">{formatVolume(hoveredData.volume)}</span>
            </span>
            {/* 指標值顯示 */}
            {indicatorSeries.map((series) => {
              const value = hoveredIndicators[series.id];
              if (value === undefined) return null;
              return (
                <span key={series.id} className="text-slate-300">
                  <span style={{ color: series.color }}>●</span>{" "}
                  {series.label || series.id}:{" "}
                  <span className="font-mono" style={{ color: series.color }}>
                    {formatPrice(value)}
                  </span>
                </span>
              );
            })}
            <span className="text-slate-500">
              {formatTime(hoveredData.timestamp)}
            </span>
          </div>
        )}
      </div>

      {/* 圖表容器 */}
      <div className="flex-1 relative">
        <div
          ref={chartContainerRef}
          className="w-full h-full"
        />

        {/* 錯誤提示 */}
        {error && (
          <div className="absolute inset-0 flex items-center justify-center bg-[#0A0F1C]">
            <div className="text-sm text-rose-400">
              <span className="mr-2">⚠️</span>
              {error}
            </div>
          </div>
        )}

        {/* 載入中提示 */}
        {!isReady && !error && (
          <div className="absolute inset-0 flex items-center justify-center bg-[#0A0F1C]">
            <div className="text-sm text-slate-400">載入圖表中...</div>
          </div>
        )}
      </div>

      {/* 底部信號詳情 (懸停時顯示) */}
      {hoveredSignal && (
        <div className="px-4 py-2 border-t border-emerald-400/30 bg-emerald-400/10">
          <div className="flex items-center gap-4 text-xs">
            <span className="font-semibold text-emerald-300">📍 信號詳情:</span>
            {Object.entries(hoveredSignal.indicator_values).map(
              ([key, value]) => (
                <span key={key} className="text-slate-300">
                  {key}: <span className="font-mono">{value.toFixed(2)}</span>
                </span>
              )
            )}
            {hoveredSignal.signal_density !== undefined && (
              <span className="text-slate-300">
                密度:{" "}
                <span className="font-mono">
                  {(hoveredSignal.signal_density * 100).toFixed(1)}%
                </span>
              </span>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * TakerRatioChart組件 - Taker Ratio線圖
 *
 * 功能：
 * - 顯示Taker Ratio線圖（LineSeries）
 * - 0.5水平參考線（虛線，中性線）
 * - Y軸範圍固定0-1
 * - 背景色區域（>0.5偏綠，<0.5偏紅）
 * - 懸停顯示taker_ratio數值
 *
 * Ultra Think步驟3：優化版本
 * 修復：P0-3（Y軸固定）、P0-4（數據檢查）、P0-6（cleanup）、P1-3（硬編碼）
 */

'use client';

import { useEffect, useState, useRef, useMemo } from 'react';
import { useChartSync } from '../../hooks/useChartSync';
import { darkChartOptions } from '../../utils/chartConfig';
import { useTimeAxis } from '@/contexts/TimeAxisContext';
import {
  formatPercentage,
  chartColors
} from '../../utils/chartConfig';
import { ISeriesApi, LineStyle, UTCTimestamp } from 'lightweight-charts';
import { KlineData } from './PriceChart';
import type { WindowOverlayRange, IndicatorLineSeries } from './TradingChartWithSignals';
import type { SignalPoint } from './StrategySignalChart';

const toUtcTime = (timestamp: number): UTCTimestamp =>
  timestamp as UTCTimestamp;

/**
 * TakerRatioChart組件Props
 */
export interface TakerRatioChartProps {
  /**
   * 交易對symbol
   */
  symbol: string;

  /**
   * 時間框架
   */
  timeframe: string;

  /**
   * K線數據數組（需要taker_ratio欄位）
   */
  klines: KlineData[];

  /**
   * 圖表高度（像素），預設120px
   */
  height?: number;

  /**
   * 圖表唯一ID（用於同步）
   */
  chartId?: string;

  /**
   * 是否啟用同步
   */
  enableSync?: boolean;

  /**
   * TO時間戳（用於初始可見範圍）
   */
  toTimestamp?: number;

  /**
   * TC時間戳（案例結束點，用於垂直參考線）
   */
  tcTimestamp?: number;

  /**
   * 近/遠窗口覆蓋範圍
   */
  windowOverlays?: WindowOverlayRange[];

  /**
   * 指標線資料（基於 taker_ratio/taker_buy_volume 計算的 EMA 等指標）
   */
  indicatorSeries?: IndicatorLineSeries[];

  /**
   * 策略信號點（用於標記策略條件符合的 K 線）
   */
  signalPoints?: SignalPoint[];
}

/**
 * TakerRatioChart組件 - Taker Ratio線圖
 */
export function TakerRatioChart({
  symbol,
  timeframe,
  klines,
  height = 120,
  chartId = 'taker-ratio-chart',
  enableSync = false,
  toTimestamp,
  tcTimestamp,
  windowOverlays = [],
  indicatorSeries = [],
  signalPoints = []
}: TakerRatioChartProps) {
  const { chartContainerRef, chartInstance, isReady } = useChartSync({
    chartId,
    toTimestamp: toTimestamp || (klines.length > 0 ? klines[0].timestamp : Date.now() / 1000),
    enableSync,
    debug: true,
    chartOptions: darkChartOptions
  });
  const { subscribeCrosshairChange } = useTimeAxis();

  // 狀態管理
  const [error, setError] = useState<string | null>(null);
  const [hoveredRatio, setHoveredRatio] = useState<number | null>(null);
  const [hoveredIndicators, setHoveredIndicators] = useState<Record<string, number>>({});

  // 保存series引用，用於cleanup
  const lineSeriesRef = useRef<ISeriesApi<'Line'> | null>(null);

  // 使用 ref 緩存 indicatorSeries，避免閉包問題
  const indicatorSeriesRef = useRef(indicatorSeries);
  useEffect(() => {
    indicatorSeriesRef.current = indicatorSeries;
  }, [indicatorSeries]);
  const buyAreaSeriesRef = useRef<ISeriesApi<'Area'> | null>(null);
  const sellAreaSeriesRef = useRef<ISeriesApi<'Area'> | null>(null);

  const timelineRange = useMemo(() => {
    if (!klines.length) return null;
    const start = klines[0].timestamp;
    const end = klines[klines.length - 1].timestamp;
    return {
      start,
      end,
      total: Math.max(end - start, 1),
    };
  }, [klines]);

  const overlayRects = useMemo(() => {
    if (!timelineRange || windowOverlays.length === 0) return [];
    return windowOverlays
      .map((overlay) => {
        const clampedStart = Math.max(
          timelineRange.start,
          Math.min(overlay.startTimestamp, timelineRange.end)
        );
        const clampedEnd = Math.max(
          timelineRange.start,
          Math.min(overlay.endTimestamp, timelineRange.end)
        );
        if (clampedEnd <= clampedStart) {
          return null;
        }
        const left =
          ((clampedStart - timelineRange.start) / timelineRange.total) * 100;
        const width =
          ((clampedEnd - clampedStart) / timelineRange.total) * 100;
        return {
          ...overlay,
          left,
          width,
        };
      })
      .filter(
        (
          rect
        ): rect is WindowOverlayRange & { left: number; width: number } =>
          rect !== null && rect.width > 0
      );
  }, [timelineRange, windowOverlays]);

  const verticalLines = useMemo(() => {
    if (!timelineRange) return [];
    const positions: Array<{ label: string; color: string; left: number }> = [];

    const toPercent = (timestamp?: number) => {
      if (!timestamp) return null;
      const clamped = Math.max(
        timelineRange.start,
        Math.min(timestamp, timelineRange.end)
      );
      return ((clamped - timelineRange.start) / timelineRange.total) * 100;
    };

    const toLeft = toPercent(toTimestamp);
    if (toLeft !== null) {
      positions.push({ label: 'TO', color: '#818cf8', left: toLeft });
    }

    const tcLeft = toPercent(tcTimestamp);
    if (tcLeft !== null) {
      positions.push({ label: 'TC', color: '#fb923c', left: tcLeft });
    }

    return positions;
  }, [timelineRange, toTimestamp, tcTimestamp]);

  /**
   * 渲染Taker Ratio數據到圖表
   * 修復P0-3: 正確固定Y軸範圍0-1
   * 修復P0-4: 過濾後檢查數據是否為空
   * 修復P0-6: 正確cleanup三個series
   * 修復P1-3: 使用chartColors配置，避免硬編碼
   */
  useEffect(() => {
    if (!chartInstance || !isReady || !klines || klines.length === 0) {
      return;
    }

    try {
      // 過濾有效的taker_ratio數據
      const takerRatioData = klines
        .filter(k => k.taker_ratio !== undefined && k.taker_ratio !== null)
        .map(kline => ({
          time: kline.timestamp as unknown,
          value: kline.taker_ratio!,
        }));

      // 修復P0-4: 檢查過濾後是否有數據
      if (takerRatioData.length === 0) {
        console.warn(`[TakerRatioChart] No valid taker_ratio data for ${symbol}`);
        setError('無有效的Taker Ratio數據');
        return;
      }

      // 創建背景色區域 - 賣盤強勢區域（0-0.5，紅色）
      // 修復P1-3: 使用chartColors而非硬編碼
      const sellAreaSeries = chartInstance.addAreaSeries({
        topColor: `rgba(251, 113, 133, 0.12)`,
        bottomColor: `rgba(251, 113, 133, 0.04)`,
        lineColor: 'transparent',
        priceScaleId: 'taker_ratio',
        lastValueVisible: false,
        priceLineVisible: false,
      });
      sellAreaSeriesRef.current = sellAreaSeries;

      // 創建背景色區域 - 買盤強勢區域（0.5-1，綠色）
      const buyAreaSeries = chartInstance.addAreaSeries({
        topColor: `rgba(52, 211, 153, 0.12)`,
        bottomColor: `rgba(52, 211, 153, 0.04)`,
        lineColor: 'transparent',
        priceScaleId: 'taker_ratio',
        lastValueVisible: false,
        priceLineVisible: false,
      });
      buyAreaSeriesRef.current = buyAreaSeries;

      // 創建主線圖（Taker Ratio線）
      const lineSeries = chartInstance.addLineSeries({
        color: '#60a5fa',
        lineWidth: 2,
        priceScaleId: 'taker_ratio',
        priceFormat: {
          type: 'percent',
          precision: 2,
          minMove: 0.01,
        },
        lastValueVisible: false,
        priceLineVisible: false,
      });
      lineSeriesRef.current = lineSeries;

      // 背景區域數據（賣盤強勢區：0到實際ratio，只在<0.5時顯示）
      const sellAreaData = takerRatioData.map(d => ({
        time: d.time,
        value: d.value <= 0.5 ? d.value : 0.5,
      }));

      // 背景區域數據（買盤強勢區：0.5到實際ratio，只在>0.5時顯示）
      const buyAreaData = takerRatioData.map(d => ({
        time: d.time,
        value: d.value >= 0.5 ? d.value : 0.5,
      }));

      // 設置數據
      sellAreaSeries.setData(sellAreaData);
      buyAreaSeries.setData(buyAreaData);
      lineSeries.setData(takerRatioData);

      // 在主線上設置信號標記
      if (signalPoints.length > 0) {
        const markers = signalPoints.map((signal) => ({
          time: toUtcTime(signal.timestamp),
          position: 'aboveBar' as const,
          color: signal.windowType === 'near' ? '#60a5fa' : '#fbbf24',
          shape: 'arrowDown' as const,
          text: signal.windowType === 'near' ? 'N' : 'F',
        }));
        lineSeries.setMarkers(markers);
        console.log(`[TakerRatioChart] Set ${markers.length} signal markers on main line`);
      }

      // 添加0.5參考線（中性線，虛線）
      lineSeries.createPriceLine({
        price: 0.5,
        color: '#64748b',
        lineWidth: 1,
        lineStyle: LineStyle.Dashed,
        axisLabelVisible: true,
        title: '中性',
      });

      // 修復P0-3: 正確配置Y軸範圍（固定0-1）
      chartInstance.priceScale('taker_ratio').applyOptions({
        scaleMargins: {
          top: 0.1,
          bottom: 0.1,
        },
        mode: 1,  // Logarithmic模式改為Percentage模式
        autoScale: false,
      });

      // 不再手動調用 fitContent，讓同步機制控制時間軸
      // 首次載入時使用 fitContent，但只在非同步模式下
      if (!enableSync) {
        chartInstance.timeScale().fitContent();
      }

      console.log(`[TakerRatioChart] Rendered ${takerRatioData.length} taker ratio data for ${symbol}`);

      // 訂閱懸停事件（用於顯示 Taker Ratio 和指標值）
      const handleCrosshairMove = (param: unknown) => {
        if (param.time) {
          const hoveredKline = klines.find(k => k.timestamp === param.time);
          if (hoveredKline && hoveredKline.taker_ratio !== undefined) {
            setHoveredRatio(hoveredKline.taker_ratio);
          }
          // 查找指標值（使用 ref 避免閉包問題）
          const indicatorValues: Record<string, number> = {};
          indicatorSeriesRef.current.forEach((series) => {
            const point = series.data.find((d) => d.time === param.time);
            if (point) {
              indicatorValues[series.id] = point.value;
            }
          });
          setHoveredIndicators(indicatorValues);
        } else {
          setHoveredRatio(null);
          setHoveredIndicators({});
        }
      };

      chartInstance.subscribeCrosshairMove(handleCrosshairMove);

      // 訂閱 Context 十字線時間變化（修復數值同步問題）
      const unsubscribeCrosshair = subscribeCrosshairChange(chartId, (time) => {
        if (time !== null) {
          const hoveredKline = klines.find(k => k.timestamp === time);
          setHoveredRatio(hoveredKline?.taker_ratio ?? null);

          // 查找指標值（使用 ref 避免閉包問題）
          const indicatorValues: Record<string, number> = {};
          indicatorSeriesRef.current.forEach((series) => {
            const point = series.data.find((d) => d.time === time);
            if (point) {
              indicatorValues[series.id] = point.value;
            }
          });
          setHoveredIndicators(indicatorValues);
        } else {
          setHoveredRatio(null);
          setHoveredIndicators({});
        }
      });

      // 修復P0-6: 正確cleanup三個series
      return () => {
        try {
          chartInstance.unsubscribeCrosshairMove(handleCrosshairMove);
          unsubscribeCrosshair();

          if (lineSeries) {
            chartInstance.removeSeries(lineSeries);
          }
          if (buyAreaSeries) {
            chartInstance.removeSeries(buyAreaSeries);
          }
          if (sellAreaSeries) {
            chartInstance.removeSeries(sellAreaSeries);
          }
        } catch (err) {
          console.error('[TakerRatioChart] Cleanup error:', err);
        }
      };

    } catch (err) {
      console.error('[TakerRatioChart] Failed to render chart:', err);
      setError(err instanceof Error ? err.message : 'Failed to render taker ratio chart');
    }
  }, [chartInstance, isReady, klines, symbol, signalPoints]);

  // 指標線渲染 refs
  const indicatorLineRefs = useRef<ISeriesApi<'Line'>[]>([]);
  const prevIndicatorSeriesJsonRef = useRef<string>("");

  /**
   * 指標線渲染 useEffect（基於 taker_ratio/taker_buy_volume 計算的 EMA 等指標）
   */
  useEffect(() => {
    if (!chartInstance || !isReady) return;

    // 序列化當前 indicatorSeries 用於比較
    const currentJson = JSON.stringify(
      indicatorSeries.map(s => ({ id: s.id, color: s.color, dataLength: s.data.length }))
    );

    // 如果內容相同，跳過更新
    if (currentJson === prevIndicatorSeriesJsonRef.current && indicatorLineRefs.current.length > 0) {
      return;
    }

    // 更新緩存
    prevIndicatorSeriesJsonRef.current = currentJson;

    // 清除舊的指標線
    indicatorLineRefs.current.forEach((line) => {
      try {
        chartInstance.removeSeries(line);
      } catch (err) {
        console.error("[TakerRatioChart] Indicator cleanup error", err);
      }
    });
    indicatorLineRefs.current = [];

    // 添加新的指標線
    indicatorSeries.forEach((series) => {
      if (!series.data.length) return;
      const line = chartInstance.addLineSeries({
        color: series.color,
        lineWidth: 2,
        priceScaleId: "taker_ratio",
        lastValueVisible: false,
        priceLineVisible: false,
      });
      line.setData(
        series.data.map((point) => ({
          time: toUtcTime(point.time),
          value: point.value,
        }))
      );
      indicatorLineRefs.current.push(line);
    });

    return () => {
      indicatorLineRefs.current.forEach((line) => {
        try {
          chartInstance.removeSeries(line);
        } catch (err) {
          console.error("[TakerRatioChart] Indicator cleanup error", err);
        }
      });
      indicatorLineRefs.current = [];
    };
  }, [chartInstance, indicatorSeries, isReady]);

  return (
    <div className="w-full flex flex-col bg-[#0A0F1C] border-t border-white/10" style={{ height: `${height}px` }}>
      {/* 頂部標籤 */}
      <div className="px-4 py-1 flex items-center justify-between border-b border-white/10">
        <div className="flex items-center gap-2 flex-wrap">
          <span className="text-xs font-medium text-slate-300">Taker Ratio</span>

          {/* 信號統計 - 顯示 Near(藍) 和 Far(土黃) 計數 */}
          {signalPoints.length > 0 && (
            <div className="flex items-center gap-2">
              <span className="text-xs px-2 py-0.5 bg-blue-400/15 text-blue-300 rounded flex items-center gap-1">
                <span style={{ color: '#60a5fa' }}>▼</span>
                N: {signalPoints.filter(s => s.windowType === 'near').length}
              </span>
              <span className="text-xs px-2 py-0.5 bg-amber-400/15 text-amber-300 rounded flex items-center gap-1">
                <span style={{ color: '#fbbf24' }}>▼</span>
                F: {signalPoints.filter(s => s.windowType === 'far').length}
              </span>
            </div>
          )}

          {hoveredRatio !== null && (
            <span className="text-xs text-slate-300">
              {formatPercentage(hoveredRatio)}
              {' - '}
              {hoveredRatio > 0.5 ? (
                <span className="text-emerald-400">買盤強</span>
              ) : hoveredRatio < 0.5 ? (
                <span className="text-rose-400">賣盤強</span>
              ) : (
                <span className="text-slate-400">中性</span>
              )}
            </span>
          )}
          {/* 指標值顯示 */}
          {indicatorSeries.map((series) => {
            const value = hoveredIndicators[series.id];
            if (value === undefined) return null;
            return (
              <span key={series.id} className="text-xs text-slate-300">
                <span style={{ color: series.color }}>●</span>{" "}
                {series.label?.replace(/\s*\(\d+\)/, "") || series.id}:{" "}
                <span className="font-mono" style={{ color: series.color }}>
                  {formatPercentage(value)}
                </span>
              </span>
            );
          })}
        </div>
      </div>

      {/* 圖表容器 */}
      <div className="flex-1 relative">
        {error && (
          <div className="absolute inset-0 flex items-center justify-center bg-[#0A0F1C] z-20">
            <div className="text-center">
              <div className="text-rose-400 text-xl mb-1">⚠️</div>
              <p className="text-xs text-rose-300">{error}</p>
            </div>
          </div>
        )}

        {klines.length === 0 && (
          <div className="absolute inset-0 flex items-center justify-center bg-[#0A0F1C] z-20">
            <p className="text-xs text-slate-400">無Taker Ratio數據</p>
          </div>
        )}

        <div
          ref={chartContainerRef}
          className="w-full h-full"
        />
        {(overlayRects.length > 0 || verticalLines.length > 0) && (
          <div className="pointer-events-none absolute inset-0 z-10">
            {overlayRects.map((overlay) => (
              <div
                key={`${overlay.type}-${overlay.left.toFixed(3)}`}
                className="absolute inset-y-0"
                style={{
                  left: `${overlay.left}%`,
                  width: `${overlay.width}%`,
                  backgroundColor:
                    overlay.type === 'near'
                      ? 'rgba(96, 165, 250, 0.08)'
                      : 'rgba(251, 191, 36, 0.08)',
                }}
              />
            ))}
            {verticalLines.map((line) => (
              <div
                key={`taker-${line.label}`}
                className="absolute inset-y-0"
                style={{
                  left: `${line.left}%`,
                  width: '1px',
                  backgroundColor: line.color,
                }}
              >
                <span className="absolute -top-1 -translate-x-1/2 rounded bg-slate-900 px-1 text-[10px] font-semibold text-white">
                  {line.label}
                </span>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * TestChart組件
 *
 * 用於測試圖表基礎設施和API調用的測試組件
 *
 * 功能：
 * - 測試圖表初始化和渲染
 * - 測試API調用與數據獲取
 * - 測試K線數據顯示
 * - 測試T點標記
 */

'use client';

import { useEffect, useState } from 'react';
import { useChart } from '../../hooks/useChart';
import { candlestickSeriesOptions, formatTime, formatPrice } from '../../utils/chartConfig';

/**
 * K線數據接口
 */
interface KlineData {
  timestamp: number;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
  taker_buy_volume: number;
  taker_ratio: number;
}

/**
 * API響應接口
 */
interface ChartDataResponse {
  success: boolean;
  data?: {
    case_timestamp: number;
    klines: KlineData[];
    center_index: number;
    metadata: {
      symbol: string;
      timeframe: string;
      total_bars: number;
      time_range: {
        start: number;
        end: number;
      };
    };
  };
  error?: {
    code: string;
    message: string;
  };
}

/**
 * TestChart組件Props
 */
interface TestChartProps {
  symbol: string;
  caseTimestamp: number;
  timeframe: string;
  maxBars?: number;
}

/**
 * TestChart組件
 */
export function TestChart({
  symbol,
  caseTimestamp,
  timeframe,
  maxBars = 200
}: TestChartProps) {
  const { chartContainerRef, chartInstance, isReady } = useChart();

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [chartData, setChartData] = useState<ChartDataResponse['data'] | null>(null);

  // 獲取圖表數據
  useEffect(() => {
    const fetchChartData = async () => {
      setLoading(true);
      setError(null);

      try {
        // 構建API URL
        const apiUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000';
        const url = `${apiUrl}/api/v1/chart/data?symbol=${symbol}&case_timestamp=${caseTimestamp}&timeframe=${timeframe}&max_bars=${maxBars}`;

        console.log('Fetching chart data from:', url);

        // 發送API請求
        const response = await fetch(url);
        const data: ChartDataResponse = await response.json();

        if (!response.ok) {
          throw new Error(data.error?.message || `HTTP error! status: ${response.status}`);
        }

        if (!data.success || !data.data) {
          throw new Error(data.error?.message || 'Failed to fetch chart data');
        }

        console.log('Chart data received:', data.data);
        setChartData(data.data);

      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : 'Unknown error';
        console.error('Failed to fetch chart data:', errorMessage);
        setError(errorMessage);
      } finally {
        setLoading(false);
      }
    };

    fetchChartData();
  }, [symbol, caseTimestamp, timeframe, maxBars]);

  // 渲染K線數據到圖表
  useEffect(() => {
    if (!chartInstance || !isReady || !chartData) {
      return;
    }

    try {
      // 添加K線系列
      const candlestickSeries = chartInstance.addCandlestickSeries(candlestickSeriesOptions);

      // 轉換數據格式
      const formattedKlines = chartData.klines.map(kline => ({
        time: kline.timestamp as unknown, // Lightweight Charts使用timestamp作為time
        open: kline.open,
        high: kline.high,
        low: kline.low,
        close: kline.close,
      }));

      // 設置數據
      candlestickSeries.setData(formattedKlines);

      // 標記T點（案例時間點）
      const tMarker = {
        time: chartData.case_timestamp as unknown,
        position: 'aboveBar' as const,
        color: '#fb7185',
        shape: 'arrowDown' as const,
        text: 'T',
      };

      candlestickSeries.setMarkers([tMarker]);

      // 自動縮放到適合的範圍
      chartInstance.timeScale().fitContent();

      console.log('Chart rendered successfully with', formattedKlines.length, 'klines');
      console.log('Center index (T position):', chartData.center_index);

    } catch (err) {
      console.error('Failed to render chart:', err);
      setError(err instanceof Error ? err.message : 'Failed to render chart');
    }
  }, [chartInstance, isReady, chartData]);

  return (
    <div className="w-full h-full flex flex-col">
      {/* 信息欄 */}
      <div className="p-4 glass-panel border-b border-white/10">
        <h3 className="text-lg font-semibold text-slate-100">
          測試圖表：{symbol} / {timeframe}
        </h3>
        <p className="text-sm text-slate-400">
          案例時間點T：{formatTime(caseTimestamp)}
        </p>
        {chartData && (
          <div className="mt-2 text-sm text-slate-400">
            <p>
              數據範圍：{formatTime(chartData.metadata.time_range.start)} 至{' '}
              {formatTime(chartData.metadata.time_range.end)}
            </p>
            <p>
              K線數量：{chartData.metadata.total_bars} 根，T點位置：第 {chartData.center_index + 1} 根
            </p>
          </div>
        )}
      </div>

      {/* 圖表容器 */}
      <div className="flex-1 relative">
        {loading && (
          <div className="absolute inset-0 flex items-center justify-center bg-[#1a233a]/90 backdrop-blur-xl z-10">
            <div className="text-center">
              <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-slate-100 mx-auto mb-4"></div>
              <p className="text-slate-400">載入圖表數據中...</p>
            </div>
          </div>
        )}

        {error && (
          <div className="absolute inset-0 flex items-center justify-center bg-[#1a233a]/90 backdrop-blur-xl z-10 p-8">
            <div className="max-w-md text-center">
              <div className="text-rose-400 text-4xl mb-4">⚠️</div>
              <h4 className="text-lg font-semibold text-slate-100 mb-2">載入失敗</h4>
              <p className="text-rose-300">{error}</p>
              <button
                onClick={() => window.location.reload()}
                className="mt-4 px-4 py-2 bg-blue-500/20 text-blue-100 border border-blue-500/40 rounded hover:bg-blue-500/30"
              >
                重試
              </button>
            </div>
          </div>
        )}

        <div
          ref={chartContainerRef}
          className="w-full h-full"
          style={{ minHeight: '400px' }}
        />
      </div>
    </div>
  );
}

/**
 * TradingChartContainer 組件 - 圖表容器整合
 *
 * 功能：
 * - 垂直堆疊三個圖表組件 (PriceChart, VolumeChart, TakerRatioChart)
 * - 實現響應式高度分配 (5:3:2 比例)
 * - 自定義十字線貫穿三個圖表
 * - 時間軸同步機制
 * - 圖表互動操作
 *
 * Ultra Think 步驟 1：初版代碼生成
 * Phase 2.3 步驟 2：圖表容器與佈局結構
 */

'use client';

import React, { useRef, useEffect, useState } from 'react';
import { PriceChart, KlineData } from './PriceChart';
import { VolumeChart } from './VolumeChart';
import { TakerRatioChart } from './TakerRatioChart';
import { TimeAxisProvider, useTimeAxis } from '@/contexts/TimeAxisContext';

/**
 * TradingChartContainer Props
 */
export interface TradingChartContainerProps {
  /**
   * 交易對 symbol
   */
  symbol: string;

  /**
   * 時間框架
   */
  timeframe: string;

  /**
   * K 線數據數組
   */
  klines: KlineData[];

  /**
   * TO 時間戳（對齊後的案例開始時間，Unix 秒）
   */
  toTimestamp: number;

  /**
   * TC 時間戳（對齊後的案例結束時間，Unix 秒，可選）
   */
  tcTimestamp?: number;

  /**
   * 容器總高度（像素），默認 640px
   */
  totalHeight?: number;

  /**
   * 是否顯示 TO 點標記
   */
  showToMarker?: boolean;
}

/**
 * TradingChartContainer 組件
 * 
 * 垂直堆疊三個圖表，實現統一的時間軸同步和 TO 點標記
 */
export function TradingChartContainer(props: TradingChartContainerProps) {
  console.log('[TradingChartContainer] Rendering with props:', {
    symbol: props.symbol,
    timeframe: props.timeframe,
    toTimestamp: props.toTimestamp,
    klinesCount: props.klines.length
  });

  return (
    <TimeAxisProvider debug={true}>
      <TradingChartContainerInner {...props} />
    </TimeAxisProvider>
  );
}

/**
 * 內部組件（可以使用 TimeAxisContext）
 */
function TradingChartContainerInner({
  symbol,
  timeframe,
  klines,
  toTimestamp,
  tcTimestamp,
  totalHeight = 640,
  showToMarker = true
}: TradingChartContainerProps) {
  // ===== Refs =====
  const containerRef = useRef<HTMLDivElement>(null);

  // ===== Context =====
  const { updateCrosshair } = useTimeAxis();

  // ===== State =====
  const [containerWidth, setContainerWidth] = useState<number>(0);
  const [crosshairX, setCrosshairX] = useState<number | null>(null); // 十字線 X 座標
  const [crosshairTime, setCrosshairTime] = useState<number | null>(null); // 十字線時間戳
  const [isInitialized, setIsInitialized] = useState(false); // 初始化狀態（避免刷新歪掉）

  // ===== 高度分配（5:3:2 比例）=====
  const priceHeight = Math.floor(totalHeight * 0.5); // 50% = 320px
  const volumeHeight = Math.floor(totalHeight * 0.3); // 30% = 192px
  const takerRatioHeight = Math.floor(totalHeight * 0.2); // 20% = 128px

  /**
   * 初始化延遲（避免刷新歪掉）
   */
  useEffect(() => {
    const timer = setTimeout(() => {
      setIsInitialized(true);
    }, 50);
    return () => clearTimeout(timer);
  }, []);

  /**
   * 監聽容器寬度變化（響應式設計）
   */
  useEffect(() => {
    if (!containerRef.current) return;

    const resizeObserver = new ResizeObserver((entries) => {
      for (const entry of entries) {
        setContainerWidth(entry.contentRect.width);
      }
    });

    resizeObserver.observe(containerRef.current);

    return () => {
      resizeObserver.disconnect();
    };
  }, []);

  /**
   * 監聽滑鼠移動，實現十字線貫穿效果 + 廣播時間戳
   */
  useEffect(() => {
    if (!containerRef.current) return;

    const handleMouseMove = (e: MouseEvent) => {
      const rect = containerRef.current?.getBoundingClientRect();
      if (!rect) return;

      const x = e.clientX - rect.left;

      // 只在圖表區域內顯示十字線（排除左側標籤和右側 padding）
      const chartStartX = 60; // 左側標籤寬度
      const chartEndX = rect.width - 80; // 右側價格標籤寬度

      if (x >= chartStartX && x <= chartEndX) {
        setCrosshairX(x);

        // 將 X 座標轉換為時間戳（粗略估算）
        // 使用第一個和最後一個 kline 的時間戳
        if (klines.length > 1) {
          const chartWidth = chartEndX - chartStartX;
          const relativeX = x - chartStartX;
          const ratio = relativeX / chartWidth;

          const firstTime = klines[0].timestamp;
          const lastTime = klines[klines.length - 1].timestamp;
          const estimatedTime = Math.floor(firstTime + (lastTime - firstTime) * ratio);

          setCrosshairTime(estimatedTime);
          // 廣播時間戳到 Context，讓其他圖表更新數值
          updateCrosshair(estimatedTime, 'container');
        }
      } else {
        setCrosshairX(null);
        setCrosshairTime(null);
        updateCrosshair(null, 'container');
      }
    };

    const handleMouseLeave = () => {
      setCrosshairX(null);
      setCrosshairTime(null);
      updateCrosshair(null, 'container');
    };

    const container = containerRef.current;
    container.addEventListener('mousemove', handleMouseMove);
    container.addEventListener('mouseleave', handleMouseLeave);

    return () => {
      container.removeEventListener('mousemove', handleMouseMove);
      container.removeEventListener('mouseleave', handleMouseLeave);
    };
  }, [klines, updateCrosshair]);

  return (
    <div 
      ref={containerRef}
      className="relative w-full glass-panel rounded-xl overflow-hidden"
      style={{ height: `${totalHeight}px` }}
    >
      {/* 十字線疊層（貫穿三個圖表的灰色虛線） */}
      {crosshairX !== null && (
        <div
          className="absolute top-0 bottom-0 pointer-events-none z-10"
          style={{
            left: `${crosshairX}px`,
            width: '1px',
            borderLeft: '1px dashed rgba(255, 255, 255, 0.1)',
          }}
        />
      )}

      {/* 三個圖表垂直堆疊 */}
      <div className="relative w-full h-full flex flex-col">
        {!isInitialized ? (
          <div className="flex items-center justify-center w-full h-full">
            <div className="text-slate-400 text-sm">初始化中...</div>
          </div>
        ) : (
          <>
            {/* 1. Price Chart (K線圖) - 50% 高度 */}
            <div 
              className="w-full border-b border-white/10"
              style={{ height: `${priceHeight}px` }}
            >
              <PriceChart
            symbol={symbol}
            timeframe={timeframe}
            klines={klines}
            caseTimestamp={toTimestamp}
            toTimestamp={toTimestamp}
            tcTimestamp={tcTimestamp}
            height={priceHeight}
            showCaseMarker={true}
            chartId="price-chart"
            enableSync={true}
          />
        </div>

        {/* 2. Volume Chart (成交量圖) - 30% 高度 */}
        <div 
          className="w-full border-b border-white/10"
          style={{ height: `${volumeHeight}px` }}
        >
          <VolumeChart
            symbol={symbol}
            timeframe={timeframe}
            klines={klines}
            height={volumeHeight}
            chartId="volume-chart"
            enableSync={true}
            toTimestamp={toTimestamp}
          />
        </div>

        {/* 3. Taker Ratio Chart (Taker 比率圖) - 20% 高度 */}
        <div 
          className="w-full"
          style={{ height: `${takerRatioHeight}px` }}
        >
          <TakerRatioChart
            symbol={symbol}
            timeframe={timeframe}
            klines={klines}
            height={takerRatioHeight}
            chartId="taker-ratio-chart"
            enableSync={true}
            toTimestamp={toTimestamp}
          />
        </div>
          </>
        )}
      </div>
    </div>
  );
}

