/**
 * TradingChartWithSignals 組件
 *
 * 垂直堆疊三個圖表，並添加策略信號可視化
 */
export function TradingChartWithSignals(props: TradingChartWithSignalsProps) {
  return (
    <TimeAxisProvider debug={false}>
      <TradingChartWithSignalsInner {...props} />
    </TimeAxisProvider>
  );
}

/**
 * 內部組件（可以使用 TimeAxisContext）
 */
function TradingChartWithSignalsInner({
  symbol,
  timeframe,
  klines,
  signalPoints = [],
  toTimestamp,
  tcTimestamp,
  totalHeight = 800,
  showCaseMarker = true,
  showSignalMarkers = true,
  showVolumeToTcMarkers = true,
  onSignalClick,
  indicatorSeries = [],
  priceIndicatorSeries,
  volumeIndicatorSeries = [],
  takerIndicatorSeries = [],
  windowOverlays = [],
  volumeSignalPoints = [],
  takerSignalPoints = [],
}: TradingChartWithSignalsProps) {
  // 合併 indicatorSeries 和 priceIndicatorSeries（向後兼容）
  const effectivePriceIndicatorSeries = priceIndicatorSeries ?? indicatorSeries;
  const containerRef = useRef<HTMLDivElement>(null);

  // ===== Context =====
  const { resetToCenter } = useTimeAxis();

  // 使用 ref 穩定 resetToCenter，避免 useEffect 重複執行
  const resetToCenterRef = useRef(resetToCenter);
  resetToCenterRef.current = resetToCenter;

  // ===== State =====
  const [isInitialized, setIsInitialized] = useState(false);
  const [hoveredSignal, setHoveredSignal] = useState<SignalTooltipData | null>(
    null
  );
  const [mousePosition, setMousePosition] = useState<{ x: number; y: number }>({
    x: 0,
    y: 0,
  });
  const [crosshairX, setCrosshairX] = useState<number | null>(null);

  // ===== 高度分配（調整為 K線:成交量:Taker = 10:7:7 比例）=====
  const priceHeight = Math.floor(totalHeight * 0.42); // 42% - 策略信號圖
  const volumeHeight = Math.floor(totalHeight * 0.29); // 29% - 成交量圖（約為 K 線的 70%）
  const takerRatioHeight = Math.floor(totalHeight * 0.29); // 29% - Taker Ratio 圖（約為 K 線的 70%）

  const timelineRange = useMemo(() => {
    if (!klines.length) return null;
    const first = klines[0].timestamp;
    const last = klines[klines.length - 1].timestamp;
    return {
      start: first,
      end: last,
      total: Math.max(last - first, 1),
    };
  }, [klines]);

  const overlayRects = useMemo(() => {
    if (!timelineRange || windowOverlays.length === 0) return [];
    return windowOverlays
      .map((overlay) => {
        const clampedStart = Math.max(
          timelineRange.start,
          Math.min(overlay.startTimestamp, timelineRange.end)
        );
        const clampedEnd = Math.max(
          timelineRange.start,
          Math.min(overlay.endTimestamp, timelineRange.end)
        );
        if (clampedEnd <= clampedStart) {
          return null;
        }
        const left = ((clampedStart - timelineRange.start) / timelineRange.total) * 100;
        const width = ((clampedEnd - clampedStart) / timelineRange.total) * 100;
        return {
          ...overlay,
          left,
          width,
        };
      })
      .filter((rect): rect is WindowOverlayRange & { left: number; width: number } =>
        rect !== null && rect.width > 0
      );
  }, [timelineRange, windowOverlays]);

  const verticalLines = useMemo(() => {
    if (!timelineRange) return [];
    const toPercent = (timestamp?: number) => {
      if (!timestamp) return null;
      const clamped = Math.max(
        timelineRange.start,
        Math.min(timestamp, timelineRange.end)
      );
      return ((clamped - timelineRange.start) / timelineRange.total) * 100;
    };

    const lines: Array<{ label: string; color: string; left: number }> = [];
    const toLeft = toPercent(toTimestamp);
    if (toLeft !== null) {
      lines.push({ label: "TO", color: "#818cf8", left: toLeft });
    }
    const tcLeft = toPercent(tcTimestamp);
    if (tcLeft !== null) {
      lines.push({ label: "TC", color: "#fb923c", left: tcLeft });
    }
    return lines.filter((line) => line.left >= 0 && line.left <= 100);
  }, [timelineRange, toTimestamp, tcTimestamp]);

  /**
   * 初始化延遲（避免刷新歪掉）+ 初始同步
   */
  useEffect(() => {
    const timer = setTimeout(() => {
      setIsInitialized(true);
      // 初始化完成後，觸發一次 fitContent 同步所有圖表
      setTimeout(() => {
        resetToCenterRef.current(toTimestamp || 0);
      }, 100);
    }, 50);
    return () => clearTimeout(timer);
  }, [toTimestamp]); // 移除 resetToCenter 依賴，使用 ref

  /**
   * 監聽滑鼠移動，用於 tooltip 位置
   */
  useEffect(() => {
    if (!containerRef.current) return;

    const handleMouseMove = (e: MouseEvent) => {
      // 更新滑鼠位置（用於 tooltip）
      setMousePosition({ x: e.clientX, y: e.clientY });
    };

    const handleMouseLeave = () => {
      setHoveredSignal(null);
    };

    const container = containerRef.current;
    container.addEventListener("mousemove", handleMouseMove);
    container.addEventListener("mouseleave", handleMouseLeave);

    return () => {
      container.removeEventListener("mousemove", handleMouseMove);
      container.removeEventListener("mouseleave", handleMouseLeave);
    };
  }, []);

  /**
   * 處理信號懸停
   */
  const handleSignalHover = useCallback((signal: SignalTooltipData | null) => {
    setHoveredSignal(signal);
  }, []);

  /**
   * 處理信號點擊
   */
  const handleSignalClick = useCallback((signal: SignalPoint) => {
    console.log("[TradingChartWithSignals] Signal clicked:", signal);
    onSignalClick?.(signal);
  }, [onSignalClick]);

  return (
    <div
      ref={containerRef}
      className="relative w-full bg-white rounded-lg shadow-md overflow-hidden"
      style={{ height: `${totalHeight}px` }}
    >
      {overlayRects.map((overlay) => (
        <div
          key={`${overlay.type}-${overlay.left.toFixed(2)}`}
          className="absolute inset-y-0 pointer-events-none"
          style={{
            left: `${overlay.left}%`,
            width: `${overlay.width}%`,
            backgroundColor:
              overlay.type === "near"
                ? "rgba(96, 165, 250, 0.08)"
                : "rgba(168, 85, 247, 0.08)",
          }}
        />
      ))}

      {verticalLines.map((line) => (
        <div
          key={`line-${line.label}`}
          className="absolute top-0 bottom-0 pointer-events-none"
          style={{
            left: `${line.left}%`,
            width: "1px",
            backgroundColor: line.color,
          }}
        >
          <span className="absolute -top-2 -translate-x-1/2 rounded bg-slate-900 px-1 text-[10px] font-semibold text-white">
            {line.label}
          </span>
        </div>
      ))}

      {/* 十字線疊層（貫穿三個圖表的灰色虛線） */}
      {crosshairX !== null && (
        <div
          className="absolute top-0 bottom-0 pointer-events-none z-30"
          style={{
            left: `${crosshairX}px`,
            width: "1px",
            borderLeft: "1px dashed rgba(255, 255, 255, 0.1)",
          }}
        />
      )}

      {/* 三個圖表垂直堆疊 */}
      <div className="relative z-10 w-full h-full flex flex-col">
        {!isInitialized ? (
          <div className="flex items-center justify-center w-full h-full">
            <div className="text-slate-400 text-sm">初始化中...</div>
          </div>
        ) : (
          <>
            {/* 1. Strategy Signal Chart (策略信號圖) - 50% 高度 */}
            <div
              className="w-full border-b border-white/10"
              style={{ height: `${priceHeight}px` }}
            >
              <StrategySignalChart
                symbol={symbol}
                timeframe={timeframe}
                klines={klines}
                signalPoints={signalPoints}
                toTimestamp={toTimestamp}
                tcTimestamp={tcTimestamp}
                height={priceHeight}
                showCaseMarker={showCaseMarker}
                showSignalMarkers={showSignalMarkers}
                chartId="strategy-signal-chart"
                enableSync={true}
                onSignalHover={handleSignalHover}
                onSignalClick={handleSignalClick}
                indicatorSeries={effectivePriceIndicatorSeries}
              />
            </div>

            {/* 2. Volume Chart (成交量圖) - 25% 高度 */}
            <div
              className="w-full border-b border-white/10"
              style={{ height: `${volumeHeight}px` }}
            >
              <VolumeChart
                symbol={symbol}
                timeframe={timeframe}
                klines={klines}
                height={volumeHeight}
                chartId="volume-chart"
                enableSync={true}
                toTimestamp={showVolumeToTcMarkers ? toTimestamp : undefined}
                tcTimestamp={showVolumeToTcMarkers ? tcTimestamp : undefined}
                windowOverlays={windowOverlays}
                indicatorSeries={volumeIndicatorSeries}
                signalPoints={volumeSignalPoints}
              />
            </div>

            {/* 3. Taker Ratio Chart (Taker 比率圖) - 25% 高度 */}
            <div className="w-full" style={{ height: `${takerRatioHeight}px` }}>
              <TakerRatioChart
                symbol={symbol}
                timeframe={timeframe}
                klines={klines}
                height={takerRatioHeight}
                chartId="taker-ratio-chart"
                enableSync={true}
                toTimestamp={showVolumeToTcMarkers ? toTimestamp : undefined}
                tcTimestamp={showVolumeToTcMarkers ? tcTimestamp : undefined}
                windowOverlays={windowOverlays}
                indicatorSeries={takerIndicatorSeries}
                signalPoints={takerSignalPoints}
              />
            </div>
          </>
        )}
      </div>

      {/* 信號工具提示 */}
      <SignalTooltip
        data={hoveredSignal}
        mousePosition={mousePosition}
        showArrow={true}
      />
    </div>
  );
}

/**
 * VolumeChart組件 - 成交量柱狀圖
 *
 * 功能：
 * - 顯示成交量柱狀圖（HistogramSeries）
 * - 顏色跟隨價格漲跌（比較close和前一根的close）
 * - 高度約為Price圖的30%
 * - 懸停顯示成交量數值
 *
 * Ultra Think步驟1：初版代碼生成
 */

'use client';

import { useEffect, useState, useRef, useMemo } from 'react';
import { useChartSync } from '../../hooks/useChartSync';
import { darkChartOptions } from '../../utils/chartConfig';
import { useTimeAxis } from '@/contexts/TimeAxisContext';
import {
  formatVolume,
  chartColors
} from '../../utils/chartConfig';
import { ISeriesApi, UTCTimestamp } from 'lightweight-charts';
import { KlineData } from './PriceChart';
import type { WindowOverlayRange, IndicatorLineSeries } from './TradingChartWithSignals';
import type { SignalPoint } from './StrategySignalChart';

const toUtcTime = (timestamp: number): UTCTimestamp =>
  timestamp as UTCTimestamp;

/**
 * 計算成交量柱的顏色（跟隨價格漲跌）
 * 修復P0-2: 移到組件外部，避免重複創建
 */
const calculateVolumeColor = (currentClose: number, prevClose: number | null, upColor: string, downColor: string): string => {
  if (prevClose === null) {
    // 第一根K線，默認綠色
    return upColor;
  }
  // 漲綠跌紅
  return currentClose >= prevClose ? upColor : downColor;
};

/**
 * VolumeChart組件Props
 */
export interface VolumeChartProps {
  /**
   * 交易對symbol
   */
  symbol: string;

  /**
   * 時間框架
   */
  timeframe: string;

  /**
   * K線數據數組（需要volume和close欄位）
   */
  klines: KlineData[];

  /**
   * 圖表高度（像素），預設120px（約為400px的30%）
   */
  height?: number;

  /**
   * 圖表唯一ID（用於同步）
   */
  chartId?: string;

  /**
   * 是否啟用同步
   */
  enableSync?: boolean;

  /**
   * TO時間戳（用於初始可見範圍）
   */
  toTimestamp?: number;

  /**
   * TC時間戳（案例結束點，用於垂直參考線）
   */
  tcTimestamp?: number;

  /**
   * 近/遠窗口覆蓋範圍
   */
  windowOverlays?: WindowOverlayRange[];

  /**
   * 指標線資料（基於 volume 計算的 EMA 等指標）
   */
  indicatorSeries?: IndicatorLineSeries[];

  /**
   * 策略信號點（用於標記策略條件符合的 K 線）
   */
  signalPoints?: SignalPoint[];
}

/**
 * 成交量柱狀圖數據格式
 */
interface VolumeBarData {
  time: unknown;  // Lightweight Charts Time type
  value: number;
  color: string;
}

/**
 * VolumeChart組件 - 成交量柱狀圖
 */
export function VolumeChart({
  symbol,
  timeframe,
  klines,
  height = 120,
  chartId = 'volume-chart',
  enableSync = false,
  toTimestamp,
  tcTimestamp,
  windowOverlays = [],
  indicatorSeries = [],
  signalPoints = []
}: VolumeChartProps) {
  const { chartContainerRef, chartInstance, isReady } = useChartSync({
    chartId,
    toTimestamp: toTimestamp || (klines.length > 0 ? klines[0].timestamp : Date.now() / 1000),
    enableSync,
    debug: true,
    chartOptions: darkChartOptions
  });
  const { subscribeCrosshairChange } = useTimeAxis();

  // 狀態管理
  const [error, setError] = useState<string | null>(null);
  const [hoveredVolume, setHoveredVolume] = useState<number | null>(null);
  const [hoveredIndicators, setHoveredIndicators] = useState<Record<string, number>>({});

  // 保存series引用，用於cleanup
  const volumeSeriesRef = useRef<ISeriesApi<'Histogram'> | null>(null);

  // 使用 ref 緩存 indicatorSeries，避免閉包問題
  const indicatorSeriesRef = useRef(indicatorSeries);
  useEffect(() => {
    indicatorSeriesRef.current = indicatorSeries;
  }, [indicatorSeries]);

  const timelineRange = useMemo(() => {
    if (!klines.length) return null;
    const start = klines[0].timestamp;
    const end = klines[klines.length - 1].timestamp;
    return {
      start,
      end,
      total: Math.max(end - start, 1),
    };
  }, [klines]);

  const overlayRects = useMemo(() => {
    if (!timelineRange || windowOverlays.length === 0) return [];
    return windowOverlays
      .map((overlay) => {
        const clampedStart = Math.max(
          timelineRange.start,
          Math.min(overlay.startTimestamp, timelineRange.end)
        );
        const clampedEnd = Math.max(
          timelineRange.start,
          Math.min(overlay.endTimestamp, timelineRange.end)
        );
        if (clampedEnd <= clampedStart) {
          return null;
        }
        const left =
          ((clampedStart - timelineRange.start) / timelineRange.total) * 100;
        const width =
          ((clampedEnd - clampedStart) / timelineRange.total) * 100;
        return {
          ...overlay,
          left,
          width,
        };
      })
      .filter(
        (
          rect
        ): rect is WindowOverlayRange & { left: number; width: number } =>
          rect !== null && rect.width > 0
      );
  }, [timelineRange, windowOverlays]);

  const verticalLines = useMemo(() => {
    if (!timelineRange) return [];
    const positions: Array<{ label: string; color: string; left: number }> = [];

    const toPercent = (timestamp?: number) => {
      if (!timestamp) return null;
      const clamped = Math.max(
        timelineRange.start,
        Math.min(timestamp, timelineRange.end)
      );
      return ((clamped - timelineRange.start) / timelineRange.total) * 100;
    };

    const toLeft = toPercent(toTimestamp);
    if (toLeft !== null) {
      positions.push({ label: 'TO', color: '#818cf8', left: toLeft });
    }

    const tcLeft = toPercent(tcTimestamp);
    if (tcLeft !== null) {
      positions.push({ label: 'TC', color: '#fb923c', left: tcLeft });
    }

    return positions;
  }, [timelineRange, toTimestamp, tcTimestamp]);

  /**
   * 渲染成交量數據到圖表
   * 修復P0-1: 正確的cleanup邏輯
   * 修復P1-4: 配置priceScale選項
   */
  useEffect(() => {
    if (!chartInstance || !isReady || !klines || klines.length === 0) {
      return;
    }

    try {
      // 添加柱狀圖系列（使用默認的 right price scale）
      const volumeSeries = chartInstance.addHistogramSeries({
        color: chartColors.upColor,
        priceFormat: {
          type: 'volume',
        },
        lastValueVisible: false,
        priceLineVisible: false,
        // 移除 priceScaleId，使用默認的 'right'，這樣可以啟用 Y 軸拖曳縮放
      });
      volumeSeriesRef.current = volumeSeries;

      // 配置 right price scale 的顯示範圍
      chartInstance.priceScale('right').applyOptions({
        autoScale: true,
        scaleMargins: {
          top: 0.1,
          bottom: 0.1,
        },
      });

      // 轉換數據格式並計算顏色
      const volumeData: VolumeBarData[] = klines.map((kline, index) => {
        const prevClose = index > 0 ? klines[index - 1].close : null;
        const color = calculateVolumeColor(kline.close, prevClose, chartColors.upColor, chartColors.downColor);

        return {
          time: kline.timestamp as unknown,
          value: kline.volume,
          color: color,
        };
      });

      // 設置成交量數據
      volumeSeries.setData(volumeData);

      // 不再手動調用 fitContent，讓同步機制控制時間軸
      // 首次載入時使用 fitContent，但只在非同步模式下
      if (!enableSync) {
        chartInstance.timeScale().fitContent();
      }

      console.log(`[VolumeChart] Rendered ${volumeData.length} volume bars for ${symbol}`);

      // 訂閱懸停事件（用於顯示成交量數值和指標值）
      const handleCrosshairMove = (param: unknown) => {
        if (param.time) {
          const hoveredKline = klines.find(k => k.timestamp === param.time);
          if (hoveredKline) {
            setHoveredVolume(hoveredKline.volume);
          }
          // 查找指標值（使用 ref 避免閉包問題）
          const indicatorValues: Record<string, number> = {};
          indicatorSeriesRef.current.forEach((series) => {
            const point = series.data.find((d) => d.time === param.time);
            if (point) {
              indicatorValues[series.id] = point.value;
            }
          });
          setHoveredIndicators(indicatorValues);
        } else {
          setHoveredVolume(null);
          setHoveredIndicators({});
        }
      };

      chartInstance.subscribeCrosshairMove(handleCrosshairMove);

      // 訂閱 Context 十字線時間變化（修復數值同步問題）
      const unsubscribeCrosshair = subscribeCrosshairChange(chartId, (time) => {
        if (time !== null) {
          const hoveredKline = klines.find(k => k.timestamp === time);
          setHoveredVolume(hoveredKline?.volume ?? null);

          // 查找指標值（使用 ref 避免閉包問題）
          const indicatorValues: Record<string, number> = {};
          indicatorSeriesRef.current.forEach((series) => {
            const point = series.data.find((d) => d.time === time);
            if (point) {
              indicatorValues[series.id] = point.value;
            }
          });
          setHoveredIndicators(indicatorValues);
        } else {
          setHoveredVolume(null);
          setHoveredIndicators({});
        }
      });

      // cleanup函數：移除series和事件訂閱（修復P0-1）
      return () => {
        try {
          chartInstance.unsubscribeCrosshairMove(handleCrosshairMove);
          unsubscribeCrosshair();
          if (volumeSeries) {
            chartInstance.removeSeries(volumeSeries);
          }
        } catch (err) {
          console.error('[VolumeChart] Cleanup error:', err);
        }
      };

    } catch (err) {
      console.error('[VolumeChart] Failed to render chart:', err);
      setError(err instanceof Error ? err.message : 'Failed to render volume chart');
    }
  }, [chartInstance, isReady, klines, symbol, chartId, enableSync, subscribeCrosshairChange]);

  // 指標線渲染 refs
  const indicatorLineRefs = useRef<ISeriesApi<'Line'>[]>([]);
  const prevIndicatorSeriesJsonRef = useRef<string>("");

  /**
   * 指標線渲染 useEffect（基於 volume 計算的 EMA 等指標）
   */
  useEffect(() => {
    if (!chartInstance || !isReady) return;

    // 序列化當前 indicatorSeries 用於比較
    const currentJson = JSON.stringify(
      indicatorSeries.map(s => ({ id: s.id, color: s.color, dataLength: s.data.length }))
    );

    // 如果內容相同，跳過更新
    if (currentJson === prevIndicatorSeriesJsonRef.current && indicatorLineRefs.current.length > 0) {
      return;
    }

    // 更新緩存
    prevIndicatorSeriesJsonRef.current = currentJson;

    // 清除舊的指標線
    indicatorLineRefs.current.forEach((line) => {
      try {
        chartInstance.removeSeries(line);
      } catch (err) {
        console.error("[VolumeChart] Indicator cleanup error", err);
      }
    });
    indicatorLineRefs.current = [];

    // 添加新的指標線
    indicatorSeries.forEach((series, index) => {
      if (!series.data.length) return;
      const line = chartInstance.addLineSeries({
        color: series.color,
        lineWidth: 2,
        priceScaleId: "right",
        lastValueVisible: false,
        priceLineVisible: false,
      });
      line.setData(
        series.data.map((point) => ({
          time: toUtcTime(point.time),
          value: point.value,
        }))
      );

      // 在第一條指標線上設置信號標記
      if (index === 0 && signalPoints.length > 0) {
        const markers = signalPoints.map((signal) => ({
          time: toUtcTime(signal.timestamp),
          position: 'aboveBar' as const,
          color: signal.windowType === 'near' ? '#60a5fa' : '#fbbf24',
          shape: 'arrowDown' as const,
          text: signal.windowType === 'near' ? 'N' : 'F',
        }));
        line.setMarkers(markers);
        console.log(`[VolumeChart] Set ${markers.length} signal markers on indicator line`);
      }

      indicatorLineRefs.current.push(line);
    });

    return () => {
      indicatorLineRefs.current.forEach((line) => {
        try {
          chartInstance.removeSeries(line);
        } catch (err) {
          console.error("[VolumeChart] Indicator cleanup error", err);
        }
      });
      indicatorLineRefs.current = [];
    };
  }, [chartInstance, indicatorSeries, isReady, signalPoints]);

  return (
    <div className="w-full flex flex-col bg-[#0A0F1C] border-t border-white/10" style={{ height: `${height}px` }}>
      {/* 頂部標籤 */}
      <div className="px-4 py-1 flex items-center justify-between border-b border-white/10">
        <div className="flex items-center gap-2 flex-wrap">
          <span className="text-xs font-medium text-slate-300">成交量</span>

          {/* 信號統計 - 顯示 Near(藍) 和 Far(土黃) 計數 */}
          {signalPoints.length > 0 && (
            <div className="flex items-center gap-2">
              <span className="text-xs px-2 py-0.5 bg-blue-400/15 text-blue-300 rounded flex items-center gap-1">
                <span style={{ color: '#60a5fa' }}>▼</span>
                N: {signalPoints.filter(s => s.windowType === 'near').length}
              </span>
              <span className="text-xs px-2 py-0.5 bg-amber-400/15 text-amber-300 rounded flex items-center gap-1">
                <span style={{ color: '#fbbf24' }}>▼</span>
                F: {signalPoints.filter(s => s.windowType === 'far').length}
              </span>
            </div>
          )}

          {hoveredVolume !== null && (
            <span className="text-xs text-slate-300">
              {formatVolume(hoveredVolume)}
            </span>
          )}
          {/* 指標值顯示 */}
          {indicatorSeries.map((series) => {
            const value = hoveredIndicators[series.id];
            if (value === undefined) return null;
            return (
              <span key={series.id} className="text-xs text-slate-300">
                <span style={{ color: series.color }}>●</span>{" "}
                {series.label?.replace(/\s*\(\d+\)/, "") || series.id}:{" "}
                <span className="font-mono" style={{ color: series.color }}>
                  {formatVolume(value)}
                </span>
              </span>
            );
          })}
        </div>
      </div>

      {/* 圖表容器 */}
      <div className="flex-1 relative">
        {error && (
          <div className="absolute inset-0 flex items-center justify-center bg-[#0A0F1C] z-20">
            <div className="text-center">
              <div className="text-rose-400 text-xl mb-1">⚠️</div>
              <p className="text-xs text-rose-300">{error}</p>
            </div>
          </div>
        )}

        {klines.length === 0 && (
          <div className="absolute inset-0 flex items-center justify-center bg-[#0A0F1C] z-20">
            <p className="text-xs text-slate-400">無成交量數據</p>
          </div>
        )}

        <div
          ref={chartContainerRef}
          className="w-full h-full"
        />
        {(overlayRects.length > 0 || verticalLines.length > 0) && (
          <div className="pointer-events-none absolute inset-0 z-10">
            {overlayRects.map((overlay) => (
              <div
                key={`${overlay.type}-${overlay.left.toFixed(3)}`}
                className="absolute inset-y-0"
                style={{
                  left: `${overlay.left}%`,
                  width: `${overlay.width}%`,
                  backgroundColor:
                    overlay.type === 'near'
                      ? 'rgba(96, 165, 250, 0.08)'
                      : 'rgba(251, 191, 36, 0.08)',
                }}
              />
            ))}
            {verticalLines.map((line) => (
              <div
                key={`volume-${line.label}`}
                className="absolute inset-y-0"
                style={{
                  left: `${line.left}%`,
                  width: '1px',
                  backgroundColor: line.color,
                }}
              >
                <span className="absolute -top-1 -translate-x-1/2 rounded bg-slate-900 px-1 text-[10px] font-semibold text-white">
                  {line.label}
                </span>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { useMemo } from 'react';
import { CorrelationMatrix } from '@/lib/types';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';

interface CorrelationHeatmapProps {
  matrix?: CorrelationMatrix | null;
  maxFeatures?: number;
}

const getCellColor = (value: number) => {
  const intensity = Math.min(Math.abs(value), 1);
  const alpha = 0.15 + intensity * 0.75;
  if (value >= 0) {
    return `rgba(52, 211, 153, ${alpha})`;
  }
  return `rgba(251, 113, 133, ${alpha})`;
};

export default function CorrelationHeatmap({ matrix, maxFeatures = 18 }: CorrelationHeatmapProps) {
  const safeMatrix = matrix?.matrix ?? [];
  const features = matrix?.features ?? [];

  const trimmed = useMemo(() => {
    const size = Math.min(features.length, maxFeatures);
    const trimmedFeatures = features.slice(0, size);
    const trimmedMatrix = safeMatrix.slice(0, size).map((row) => row.slice(0, size));
    return { trimmedFeatures, trimmedMatrix };
  }, [features, maxFeatures, safeMatrix]);

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-base">相關性熱力圖</CardTitle>
        <CardDescription>顯示 Top 特徵相關性矩陣</CardDescription>
      </CardHeader>
      <CardContent>
        {trimmed.trimmedFeatures.length === 0 ? (
          <div className="flex items-center justify-center h-[240px] text-slate-400">
            暫無相關性矩陣
          </div>
        ) : (
          <div className="space-y-3">
            <div
              className="grid gap-1"
              style={{
                gridTemplateColumns: `120px repeat(${trimmed.trimmedFeatures.length}, minmax(32px, 1fr))`,
              }}
            >
              <div></div>
              {trimmed.trimmedFeatures.map((feature) => (
                <div key={`col-${feature}`} className="text-[10px] text-slate-400 truncate">
                  {feature}
                </div>
              ))}
              {trimmed.trimmedFeatures.map((feature, rowIndex) => (
                <div key={`row-${feature}`} className="contents">
                  <div className="text-[10px] text-slate-400 truncate pr-2">{feature}</div>
                  {trimmed.trimmedMatrix[rowIndex]?.map((value, colIndex) => (
                    <div
                      key={`cell-${rowIndex}-${colIndex}`}
                      title={`${feature} vs ${trimmed.trimmedFeatures[colIndex]}: ${value.toFixed(3)}`}
                      className="h-6 rounded-sm"
                      style={{ backgroundColor: getCellColor(value) }}
                    />
                  ))}
                </div>
              ))}
            </div>
            <div className="flex items-center justify-between text-xs text-slate-400">
              <span>負相關</span>
              <span>正相關</span>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

/**
 * MultiIndicatorConfig.tsx - 多指標配置組件
 * 
 * 功能：
 * 1. 配置多個指標組合（EMA + RSI + MACD）
 * 2. 動態添加/刪除指標
 * 3. 每個指標獨立配置參數和數據源
 * 4. 預覽生成的特徵名稱
 * 
 * Author: AI Agent
 * Date: 2026-01-11
 */

'use client'

import { useState, useEffect } from 'react'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { Badge } from '@/components/ui/badge'
import { Plus, Trash2, Eye } from 'lucide-react'
import { Alert, AlertDescription } from '@/components/ui/alert'

interface IndicatorConfig {
  id: string
  indicator: string
  data_source: string
  params: Record<string, unknown>
}

interface MultiIndicatorConfigProps {
  value: IndicatorConfig[]
  onChange: (configs: IndicatorConfig[]) => void
}

// 可用指標定義
const AVAILABLE_INDICATORS = [
  {
    value: 'ema_three_line',
    label: 'EMA 三線順勢',
    params: {
      ema_short: { type: 'number', label: '短期 EMA', default: 5, step: 1, min: 1 },
      ema_mid: { type: 'number', label: '中期 EMA', default: 20, step: 1, min: 1 },
      ema_long: { type: 'number', label: '長期 EMA', default: 60, step: 1, min: 1 },
      volume_threshold: { type: 'number', label: '成交量閾值（0=不考慮）', default: 0.6, step: 0.01, min: 0, max: 1 }
    }
  },
  {
    value: 'rsi',
    label: 'RSI 指標',
    params: {
      period: { type: 'number', label: '週期', default: 14 },
      overbought: { type: 'number', label: '超買線', default: 70 },
      oversold: { type: 'number', label: '超賣線', default: 30 }
    }
  },
  {
    value: 'macd',
    label: 'MACD 指標',
    params: {
      fast: { type: 'number', label: '快線', default: 12 },
      slow: { type: 'number', label: '慢線', default: 26 },
      signal: { type: 'number', label: '信號線', default: 9 }
    }
  }
]

const DATA_SOURCES = [
  { value: 'close', label: 'Close（收盤價）' },
  { value: 'open', label: 'Open（開盤價）' },
  { value: 'high', label: 'High（最高價）' },
  { value: 'low', label: 'Low（最低價）' },
  { value: 'volume', label: 'Volume（成交量）' },
  { value: 'taker_ratio', label: 'Taker Ratio（主動買入比）' }
]

export default function MultiIndicatorConfig({ value = [], onChange }: MultiIndicatorConfigProps) {
  const [previewFeatures, setPreviewFeatures] = useState<string[]>([])
  const [showPreview, setShowPreview] = useState(false)

  // 初始化：如果 value 是空的，添加一個預設指標
  useEffect(() => {
    if (value.length === 0) {
      const defaultIndicator: IndicatorConfig = {
        id: `indicator_${Date.now()}`,
        indicator: 'ema_three_line',
        data_source: 'close',
        params: {
          ema_short: 5,
          ema_mid: 20,
          ema_long: 60,
          volume_threshold: 0.6
        }
      }
      onChange([defaultIndicator])
    }
  }, [])

  // 添加指標
  const handleAddIndicator = () => {
    const newIndicator: IndicatorConfig = {
      id: `indicator_${Date.now()}`,
      indicator: 'ema_three_line',
      data_source: 'close',
      params: {
        ema_short: 5,
        ema_mid: 20,
        ema_long: 60,
        volume_threshold: 0.6
      }
    }
    onChange([...value, newIndicator])
  }

  // 刪除指標
  const handleRemoveIndicator = (id: string) => {
    onChange(value.filter(config => config.id !== id))
  }

  // 更新指標類型
  const handleIndicatorChange = (id: string, indicator: string) => {
    const indicatorDef = AVAILABLE_INDICATORS.find(i => i.value === indicator)
    if (!indicatorDef) return

    // 生成默認參數
    const defaultParams: Record<string, unknown> = {}
    Object.entries(indicatorDef.params).forEach(([key, config]) => {
      defaultParams[key] = config.default
    })

    onChange(value.map(config =>
      config.id === id
        ? { ...config, indicator, params: defaultParams }
        : config
    ))
  }

  // 更新數據源
  const handleDataSourceChange = (id: string, dataSource: string) => {
    onChange(value.map(config =>
      config.id === id
        ? { ...config, data_source: dataSource }
        : config
    ))
  }

  // 更新參數
  const handleParamChange = (id: string, paramKey: string, paramValue: unknown) => {
    onChange(value.map(config =>
      config.id === id
        ? { ...config, params: { ...config.params, [paramKey]: paramValue } }
        : config
    ))
  }

  // 預覽特徵名稱 - 完整列出所有會生成的特徵
  const handlePreview = () => {
    const features: string[] = []

    // 基礎價格特徵（8個）- 固定生成
    const priceFeatures = [
      'price_change_pct',
      'high_low_range_pct',
      'close_position_in_range',
      'price_volatility_5',
      'price_momentum_3_pct',  // ✅ 修正：改為百分比（跨標的兼容）
      'upper_shadow_pct',
      'lower_shadow_pct',
      'body_pct'
    ]
    features.push(...priceFeatures)

    // 基礎成交量特徵（6個）- 固定生成
    const volumeFeatures = [
      'volume_change_pct',
      'volume_ma_ratio_5',
      'taker_buy_ratio',
      'taker_buy_value_ratio',
      'volume_price_correlation_5',
      'abnormal_volume_flag'
    ]
    features.push(...volumeFeatures)

    // 策略特徵（依據配置動態生成）
    value.forEach(config => {
      const { indicator, data_source, params } = config

      if (indicator === 'ema_three_line') {
        // EMA 策略特徵（11個）
        // ✅ 跨標的訓練：只使用相對特徵，不使用 EMA 絕對值

        // 價格與 EMA 的相對距離（3個，百分比）
        features.push(`${data_source}_price_ema_short_distance_pct`)
        features.push(`${data_source}_price_ema_mid_distance_pct`)
        features.push(`${data_source}_price_ema_long_distance_pct`)

        // EMA 之間的相對距離（2個，百分比）
        features.push(`${data_source}_ema${params.ema_short}_${params.ema_mid}_distance_pct`)
        features.push(`${data_source}_ema${params.ema_mid}_${params.ema_long}_distance_pct`)

        // EMA 趨勢特徵（2個）
        features.push(`${data_source}_ema_trend_aligned`)
        features.push(`${data_source}_ema${params.ema_short}_${params.ema_mid}_cross_signal`)

        // EMA 斜率（2個，百分比變化率）
        features.push(`${data_source}_ema_short_slope_pct`)
        features.push(`${data_source}_ema_mid_slope_pct`)

        // 成交量特徵（2個）
        features.push(`volume_spike_${Math.round(params.volume_threshold * 100)}`)
        features.push(`taker_ratio_distance_${Math.round(params.volume_threshold * 100)}`)

        // 信號組合特徵（3個）
        features.push(`${data_source}_ema_entry_signal_score`)
        features.push(`${data_source}_ema_trend_consistency_5`)
        features.push(`${data_source}_ema_signal_strength`)
      } else if (indicator === 'rsi') {
        features.push(`${data_source}_rsi${params.period}_value`)
        features.push(`${data_source}_rsi_overbought_signal`)
        features.push(`${data_source}_rsi_oversold_signal`)
        features.push(`${data_source}_rsi_divergence`)
      } else if (indicator === 'macd') {
        features.push(`${data_source}_macd_line`)
        features.push(`${data_source}_macd_signal`)
        features.push(`${data_source}_macd_histogram`)
        features.push(`${data_source}_macd_cross_signal`)
        features.push(`${data_source}_macd_divergence`)
      }
    })

    setPreviewFeatures(features)
    setShowPreview(true)
  }

  return (
    <div className="space-y-4">
      {/* 指標列表 */}
      {value.map((config, index) => {
        const indicatorDef = AVAILABLE_INDICATORS.find(i => i.value === config.indicator)

        return (
          <Card key={config.id} className="glass-panel border-white/10">
            <CardHeader>
              <CardTitle className="flex items-center justify-between">
                <span className="text-base text-slate-100">指標 #{index + 1}</span>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => handleRemoveIndicator(config.id)}
                  disabled={value.length === 1}
                >
                  <Trash2 className="h-4 w-4 text-rose-300" />
                </Button>
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              {/* 指標類型 */}
              <div className="space-y-2">
                <Label className="text-slate-200 font-medium">指標類型</Label>
                <Select
                  value={config.indicator}
                  onValueChange={(val) => handleIndicatorChange(config.id, val)}
                >
                  <SelectTrigger className="bg-slate-900/60 border-slate-700 text-slate-100 [&>span]:text-slate-100">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent className="bg-slate-950 border border-slate-800 shadow-lg z-50">
                    {AVAILABLE_INDICATORS.map(indicator => (
                      <SelectItem key={indicator.value} value={indicator.value} className="text-slate-100 hover:bg-slate-900 cursor-pointer">
                        {indicator.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              {/* 數據源 */}
              <div className="space-y-2">
                <Label className="text-slate-200">數據源</Label>
                <Select
                  value={config.data_source}
                  onValueChange={(val) => handleDataSourceChange(config.id, val)}
                >
                  <SelectTrigger className="bg-slate-900/60 border-slate-700 text-slate-100 [&>span]:text-slate-100">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent className="bg-slate-950 border border-slate-800 shadow-lg z-50">
                    {DATA_SOURCES.map(source => (
                      <SelectItem key={source.value} value={source.value} className="text-slate-100 hover:bg-slate-900 cursor-pointer">
                        {source.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              {/* 參數配置 */}
              {indicatorDef && (
                <div className="space-y-3">
                  <Label className="text-slate-200 font-medium">參數配置</Label>
                  <div className="grid grid-cols-2 gap-3">
                    {Object.entries(indicatorDef.params).map(([paramKey, paramConfig]) => (
                      <div key={paramKey} className="space-y-1">
                        <Label className="text-xs text-slate-400">{paramConfig.label}</Label>
                        <Input
                          type="number"
                          value={config.params[paramKey] ?? paramConfig.default}
                          onChange={(e) => {
                            const val = e.target.value
                            // 允許空值和任意數字輸入
                            if (val === '' || val === '-') {
                              handleParamChange(config.id, paramKey, val)
                            } else {
                              const num = parseFloat(val)
                              if (!isNaN(num)) {
                                handleParamChange(config.id, paramKey, num)
                              }
                            }
                          }}
                          onBlur={(e) => {
                            // 失焦時確保是有效數字，否則恢復預設值
                            const val = e.target.value
                            if (val === '' || isNaN(parseFloat(val))) {
                              handleParamChange(config.id, paramKey, paramConfig.default)
                            }
                          }}
                          step="unknown"
                          min={paramConfig.min}
                          max={paramConfig.max}
                          className="bg-slate-900/60 border-slate-700 text-slate-100"
                        />
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </CardContent>
          </Card>
        )
      })}

      {/* 操作按鈕 */}
      <div className="flex gap-2">
        <Button onClick={handleAddIndicator} variant="outline" className="bg-white/10 border-white/10 text-slate-100 hover:bg-white/15">
          <Plus className="h-4 w-4 mr-2" />
          添加指標
        </Button>
        <Button onClick={handlePreview} variant="outline" className="bg-white/10 border-white/10 text-slate-100 hover:bg-white/15">
          <Eye className="h-4 w-4 mr-2" />
          預覽特徵
        </Button>
      </div>

      {/* 特徵預覽 */}
      {showPreview && (
        <Alert className="glass-panel border-white/10">
          <AlertDescription>
            <div className="space-y-2">
              <p className="font-semibold text-slate-100">將生成 {previewFeatures.length} 個特徵：</p>
              <div className="text-xs text-slate-400 mb-2">
                包含：8 個價格特徵 + 6 個成交量特徵 + 策略特徵（依配置）
                <br />
                <span className="text-emerald-300 font-medium">✅ 跨標的訓練兼容：所有特徵均為相對值（百分比/比例/標記），無絕對價格/成交量</span>
              </div>
              <div className="flex flex-wrap gap-2 max-h-48 overflow-y-auto">
                {previewFeatures.map(feature => (
                  <Badge key={feature} variant="secondary" className="font-mono text-xs bg-white/10 text-slate-200 border border-white/10">
                    {feature}
                  </Badge>
                ))}
              </div>
            </div>
          </AlertDescription>
        </Alert>
      )}
    </div>
  )
}

// frontend/src/components/pattern/PatternComparison.tsx
/**
 * PatternComparison.tsx
 * 
 * 樣式比較組件
 * 
 * Features:
 * - 多樣式選擇（最多 4 個）
 * - 效能指標並排比較
 * - 規則差異對比
 * - 雷達圖視覺化
 */

'use client';

import React, { useState, useEffect } from 'react';
import { RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar, Legend, ResponsiveContainer } from 'recharts';
import { usePatternStore } from '@/store/patternStore';
import { getPattern } from '@/lib/api/patternApi';
import type { Pattern } from '@/lib/patternTypes';

const MAX_PATTERNS = 4;
const COLORS = ['#60a5fa', '#34d399', '#fbbf24', '#fb7185'];

export default function PatternComparison() {
  const { patterns } = usePatternStore();
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [selectedPatterns, setSelectedPatterns] = useState<Pattern[]>([]);
  const [loading, setLoading] = useState(false);

  // 載入選中的樣式
  useEffect(() => {
    if (selectedIds.length === 0) {
      setSelectedPatterns([]);
      return;
    }

    loadSelectedPatterns();
  }, [selectedIds]);

  const loadSelectedPatterns = async () => {
    try {
      setLoading(true);
      const promises = selectedIds.map(id => getPattern(id));
      const loaded = await Promise.all(promises);
      setSelectedPatterns(loaded);
    } catch (error) {
      console.error('載入樣式失敗:', error);
    } finally {
      setLoading(false);
    }
  };

  // 新增樣式
  const handleAddPattern = (patternId: string) => {
    if (selectedIds.includes(patternId)) return;
    if (selectedIds.length >= MAX_PATTERNS) {
      alert(`最多只能比較 ${MAX_PATTERNS} 個樣式`);
      return;
    }
    setSelectedIds([...selectedIds, patternId]);
  };

  // 移除樣式
  const handleRemovePattern = (patternId: string) => {
    setSelectedIds(selectedIds.filter(id => id !== patternId));
  };

  // 準備雷達圖資料
  const radarData = [
    { metric: '準確度', ...Object.fromEntries(selectedPatterns.map((p, i) => [`pattern${i}`, p.performance_metrics.accuracy])) },
    { metric: '精確度', ...Object.fromEntries(selectedPatterns.map((p, i) => [`pattern${i}`, p.performance_metrics.precision])) },
    { metric: '召回率', ...Object.fromEntries(selectedPatterns.map((p, i) => [`pattern${i}`, p.performance_metrics.recall])) },
    { metric: 'F1 分數', ...Object.fromEntries(selectedPatterns.map((p, i) => [`pattern${i}`, p.performance_metrics.f1_score])) }
  ];

  return (
    <div className="space-y-6">
      {/* 樣式選擇器 */}
      <div className="glass-panel rounded-xl border border-white/10 p-6">
        <h2 className="text-lg font-semibold text-slate-100 mb-4">選擇要比較的樣式 (最多 {MAX_PATTERNS} 個)</h2>
        <select
          onChange={(e) => handleAddPattern(e.target.value)}
          value=""
          className="w-full px-3 py-2 border border-white/10 rounded bg-slate-900/60 text-slate-200"
          disabled={selectedIds.length >= MAX_PATTERNS}
        >
          <option value="">-- 選擇樣式 --</option>
          {patterns
            .filter(p => !selectedIds.includes(p.pattern_id))
            .map(pattern => (
              <option key={pattern.pattern_id} value={pattern.pattern_id}>
                {pattern.name} ({pattern.case_id})
              </option>
            ))}
        </select>

        {/* 已選樣式列表 */}
        {selectedIds.length > 0 && (
          <div className="mt-4 space-y-2">
            {selectedPatterns.map((pattern, index) => (
              <div key={pattern.pattern_id} className="flex items-center justify-between p-3 bg-white/5 border border-white/10 rounded">
                <div className="flex items-center gap-3">
                  <div 
                    className="w-4 h-4 rounded-full"
                    style={{ backgroundColor: COLORS[index] }}
                  />
                  <div>
                    <p className="font-semibold text-slate-100">{pattern.name}</p>
                    <p className="text-sm text-slate-400">{pattern.case_id}</p>
                  </div>
                </div>
                <button
                  onClick={() => handleRemovePattern(pattern.pattern_id)}
                  className="text-rose-300 hover:text-rose-200"
                >
                  移除
                </button>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* 比較結果 */}
      {selectedPatterns.length >= 2 && (
        <div className="space-y-6">
          {/* 雷達圖 */}
          <div className="glass-panel rounded-xl border border-white/10 p-6">
            <h3 className="text-lg font-semibold text-slate-100 mb-4">效能雷達圖</h3>
            <ResponsiveContainer width="100%" height={400}>
              <RadarChart data={radarData}>
                <PolarGrid />
                <PolarAngleAxis dataKey="metric" />
                <PolarRadiusAxis angle={90} domain={[0, 1]} />
                {selectedPatterns.map((pattern, index) => (
                  <Radar
                    key={pattern.pattern_id}
                    name={pattern.name}
                    dataKey={`pattern${index}`}
                    stroke={COLORS[index]}
                    fill={COLORS[index]}
                    fillOpacity={0.3}
                  />
                ))}
                <Legend />
              </RadarChart>
            </ResponsiveContainer>
          </div>

          {/* 指標對比表 */}
          <div className="glass-panel rounded-xl border border-white/10 overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-white/5 text-slate-200">
                <tr>
                  <th className="px-4 py-3 text-left">指標</th>
                  {selectedPatterns.map((pattern, index) => (
                    <th key={pattern.pattern_id} className="px-4 py-3 text-center">
                      <div className="flex items-center justify-center gap-2">
                        <div 
                          className="w-3 h-3 rounded-full"
                          style={{ backgroundColor: COLORS[index] }}
                        />
                        {pattern.name}
                      </div>
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                <tr className="border-b">
                  <td className="px-4 py-3 font-semibold text-slate-100">準確度</td>
                  {selectedPatterns.map(p => (
                    <td key={p.pattern_id} className="px-4 py-3 text-center text-slate-200">
                      {(p.performance_metrics.accuracy * 100).toFixed(1)}%
                    </td>
                  ))}
                </tr>
                <tr className="border-b">
                  <td className="px-4 py-3 font-semibold text-slate-100">精確度</td>
                  {selectedPatterns.map(p => (
                    <td key={p.pattern_id} className="px-4 py-3 text-center text-slate-200">
                      {(p.performance_metrics.precision * 100).toFixed(1)}%
                    </td>
                  ))}
                </tr>
                <tr className="border-b">
                  <td className="px-4 py-3 font-semibold text-slate-100">召回率</td>
                  {selectedPatterns.map(p => (
                    <td key={p.pattern_id} className="px-4 py-3 text-center text-slate-200">
                      {(p.performance_metrics.recall * 100).toFixed(1)}%
                    </td>
                  ))}
                </tr>
                <tr className="border-b">
                  <td className="px-4 py-3 font-semibold text-slate-100">F1 分數</td>
                  {selectedPatterns.map(p => (
                    <td key={p.pattern_id} className="px-4 py-3 text-center text-slate-200">
                      {p.performance_metrics.f1_score.toFixed(3)}
                    </td>
                  ))}
                </tr>
                <tr className="border-b">
                  <td className="px-4 py-3 font-semibold text-slate-100">規則數量</td>
                  {selectedPatterns.map(p => (
                    <td key={p.pattern_id} className="px-4 py-3 text-center text-slate-200">
                      {p.rules.length}
                    </td>
                  ))}
                </tr>
                <tr className="border-b">
                  <td className="px-4 py-3 font-semibold text-slate-100">樣本數</td>
                  {selectedPatterns.map(p => (
                    <td key={p.pattern_id} className="px-4 py-3 text-center text-slate-200">
                      {p.performance_metrics.sample_count}
                    </td>
                  ))}
                </tr>
                <tr className="border-b">
                  <td className="px-4 py-3 font-semibold text-slate-100">狀態</td>
                  {selectedPatterns.map(p => (
                    <td key={p.pattern_id} className="px-4 py-3 text-center">
                      <span className={`px-2 py-1 rounded-full text-xs ${
                        p.status === 'active' ? 'bg-emerald-500/20 text-emerald-200' :
