                    </td>
                  ))}
                </tr>
              </tbody>
            </table>
          </div>

          {/* 規則對比 */}
          <div className="glass-panel rounded-xl border border-white/10 p-6">
            <h3 className="text-lg font-semibold text-slate-100 mb-4">規則對比</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
