      {/* 空狀態 */}
      {selectedPatterns.length < 2 && (
        <div className="glass-panel rounded-xl border-2 border-dashed border-white/10 p-12 text-center">
          <p className="text-slate-400 text-lg">請選擇至少 2 個樣式進行比較</p>
        </div>
      )}
    </div>
  );
}

// frontend/src/components/pattern/PatternList.tsx
/**
 * PatternList.tsx
 * 
 * 顯示所有模式的列表，支援過濾和排序
 * 
 * Features:
 * - 顯示模式卡片（名稱、描述、規則數、效能指標）
 * - 依狀態過濾（active/archived/testing）
 * - 依標籤過濾
 * - 點擊卡片查看詳情
 * - 刪除模式功能
 */

'use client';

import React, { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { usePatternStore } from '@/store/patternStore';
import { listPatterns, deletePattern } from '@/lib/api/patternApi';
import type { Pattern } from '@/lib/patternTypes';

export default function PatternList() {
  const {
    patterns,
    setPatterns,
    selectPattern,
    filters,
    getFilteredPatterns
  } = usePatternStore();

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // 載入模式列表
  useEffect(() => {
    loadPatterns();
  }, [filters.status, filters.tags]);

  const loadPatterns = async () => {
    setLoading(true);
    setError(null);

    try {
      const response = await listPatterns(
        filters.status || undefined,
        filters.tags.length > 0 ? filters.tags : undefined
      );

      if (response.success) {
        setPatterns(response.patterns);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load patterns');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (patternId: string) => {
    if (!confirm('確定要刪除此模式嗎？')) return;

    try {
      const response = await deletePattern(patternId);
      if (response.success) {
        loadPatterns(); // 重新載入
      }
    } catch (err) {
      alert('刪除失敗: ' + (err instanceof Error ? err.message : 'Unknown error'));
    }
  };

  const filteredPatterns = getFilteredPatterns();

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-slate-400">載入中...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="glass-panel border border-rose-500/30 rounded-lg p-4">
        <p className="text-rose-200">錯誤: {error}</p>
        <button 
          onClick={loadPatterns}
          className="mt-2 px-4 py-2 bg-rose-500/20 text-rose-100 border border-rose-500/40 rounded hover:bg-rose-500/30"
        >
          重試
        </button>
      </div>
    );
  }

  if (filteredPatterns.length === 0) {
    return (
      <div className="text-center py-12">
        <p className="text-slate-400 mb-4">沒有符合條件的模式</p>
        <button 
          onClick={loadPatterns}
          className="px-4 py-2 bg-blue-500/20 text-blue-100 border border-blue-500/40 rounded hover:bg-blue-500/30"
        >
          重新整理
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* 標題與統計 */}
      <div className="flex justify-between items-center">
        <h2 className="text-xl font-semibold text-slate-100">模式列表</h2>
        <span className="text-sm text-slate-300 font-semibold">共 {filteredPatterns.length} 個模式</span>
      </div>

      {/* 模式卡片網格 */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filteredPatterns.map((pattern) => (
          <PatternCard
            key={pattern.pattern_id}
            pattern={pattern}
            onSelect={() => selectPattern(pattern.pattern_id)}
            onDelete={() => handleDelete(pattern.pattern_id)}
          />
        ))}
      </div>
    </div>
  );
}

// 模式卡片組件
function PatternCard({ 
  pattern, 
  onSelect, 
  onDelete 
}: { 
  pattern: Pattern; 
  onSelect: () => void; 
  onDelete: () => void;
