// frontend/src/components/pattern/XGBoostAnalysisPanel.tsx
/**
 * XGBoostAnalysisPanel.tsx
 * 
 * XGBoost 分析主面板
 * 
 * Features:
 * - 任務啟動與狀態追蹤
 * - WebSocket 即時進度更新
 * - 顯示特徵重要性、決策規則、模型效能
 * - 一鍵建立樣式功能
 */

'use client';

import React, { useState, useEffect } from 'react';
import { usePatternStore } from '@/store/patternStore';
import { startXGBoostAnalysis, getXGBoostTaskStatus } from '@/lib/api/patternApi';
import FeatureImportanceChart from './FeatureImportanceChart';
import DecisionRuleTable from './DecisionRuleTable';
import type { XGBoostAnalysisRequest } from '@/lib/patternTypes';

interface Props {
  caseId: string;
  onPatternCreated?: () => void;
}

export default function XGBoostAnalysisPanel({ caseId, onPatternCreated }: Props) {
  const { 
    currentAnalysis, 
    analysisLoading, 
    analysisTaskId, 
    setCurrentAnalysis 
  } = usePatternStore();

  const [progress, setProgress] = useState(0);
  const [status, setStatus] = useState<'idle' | 'running' | 'completed' | 'failed'>('idle');
  const [errorMessage, setErrorMessage] = useState<string>('');

  // 啟動分析
  const handleStartAnalysis = async () => {
    try {
      const request: XGBoostAnalysisRequest = {
        case_id: caseId,
        max_depth: 5,
        learning_rate: 0.05,
        n_estimators: 100,
        top_n_features: 10,
        min_rule_support: 5
      };

      const response = await startXGBoostAnalysis(request);
      usePatternStore.setState({ analysisTaskId: response.task_id, analysisLoading: true });
      setStatus('running');
      setProgress(0);

      // 開始輪詢任務狀態
      pollTaskStatus(response.task_id);
    } catch (error) {
      console.error('啟動分析失敗:', error);
      setStatus('failed');
      setErrorMessage(error instanceof Error ? error.message : '未知錯誤');
    }
  };

  // 輪詢任務狀態
  const pollTaskStatus = async (taskId: string) => {
    const interval = setInterval(async () => {
      try {
        const statusData = await getXGBoostTaskStatus(taskId);
        setProgress(statusData.progress);

        if (statusData.status === 'completed') {
          clearInterval(interval);
          setStatus('completed');
          setCurrentAnalysis(statusData.result);
          usePatternStore.setState({ analysisLoading: false });
        } else if (statusData.status === 'failed') {
          clearInterval(interval);
          setStatus('failed');
          setErrorMessage(statusData.error || '分析失敗');
          usePatternStore.setState({ analysisLoading: false });
        }
      } catch (error) {
        console.error('獲取任務狀態失敗:', error);
        clearInterval(interval);
        setStatus('failed');
        setErrorMessage('無法獲取任務狀態');
        usePatternStore.setState({ analysisLoading: false });
      }
    }, 2000);
  };

  return (
    <div className="space-y-6">
      {/* 標題與啟動按鈕 */}
      <div className="glass-panel rounded-xl border border-white/10 p-4">
        <div className="flex justify-between items-center">
          <div>
            <h2 className="text-xl font-semibold text-slate-100">XGBoost 樣式分析</h2>
            <p className="text-sm text-slate-400 mt-1">案例 ID: {caseId}</p>
          </div>
          <button
            onClick={handleStartAnalysis}
            disabled={status === 'running'}
            className={`px-4 py-2 rounded font-semibold ${
              status === 'running'
                ? 'bg-white/10 text-slate-400 border border-white/10 cursor-not-allowed'
                : 'bg-blue-500/20 text-blue-100 border border-blue-500/40 hover:bg-blue-500/30'
            }`}
          >
            {status === 'running' ? '分析中...' : '開始分析'}
          </button>
        </div>

        {/* 進度條 */}
        {status === 'running' && (
          <div className="mt-4">
            <div className="flex justify-between text-sm text-slate-300 mb-1">
              <span>進度</span>
              <span>{progress}%</span>
            </div>
            <div className="w-full bg-white/10 rounded-full h-2">
              <div
                className="bg-blue-400 h-2 rounded-full transition-all duration-300"
                style={{ width: `${progress}%` }}
              />
            </div>
          </div>
        )}

        {/* 錯誤訊息 */}
        {status === 'failed' && (
          <div className="mt-4 p-3 bg-rose-500/10 border border-rose-500/30 rounded text-rose-200 text-sm">
            ❌ {errorMessage}
          </div>
        )}
      </div>

      {/* 分析結果 */}
      {status === 'completed' && currentAnalysis && (
        <div className="space-y-6">
          {/* 模型效能 */}
          <div className="glass-panel rounded-xl border border-white/10 p-4">
            <h3 className="text-lg font-semibold text-slate-100 mb-3">模型效能</h3>
            <div className="grid grid-cols-4 gap-4">
              <div className="text-center">
                <p className="text-sm text-slate-400">準確度</p>
                <p className="text-2xl font-semibold text-blue-300">
                  {(currentAnalysis.model_performance.test_accuracy * 100).toFixed(1)}%
                </p>
              </div>
              <div className="text-center">
                <p className="text-sm text-slate-400">精確度</p>
                <p className="text-2xl font-semibold text-emerald-300">
                  {(currentAnalysis.model_performance.test_precision * 100).toFixed(1)}%
                </p>
              </div>
              <div className="text-center">
                <p className="text-sm text-slate-400">召回率</p>
                <p className="text-2xl font-semibold text-amber-300">
                  {(currentAnalysis.model_performance.test_recall * 100).toFixed(1)}%
                </p>
              </div>
              <div className="text-center">
                <p className="text-sm text-slate-400">F1 分數</p>
                <p className="text-2xl font-semibold text-purple-400">
                  {currentAnalysis.model_performance.test_f1.toFixed(3)}
                </p>
              </div>
            </div>

            {/* AUC */}
            {currentAnalysis.model_performance.test_auc && (
              <div className="mt-4 text-center">
                <p className="text-sm text-slate-400">AUC</p>
                <p className="text-3xl font-semibold text-blue-300">
                  {currentAnalysis.model_performance.test_auc.toFixed(3)}
                </p>
              </div>
            )}
          </div>

          {/* 特徵重要性 */}
          <FeatureImportanceChart 
            featureImportance={currentAnalysis.feature_importance}
            topN={10}
          />

          {/* 決策規則 */}
          <DecisionRuleTable 
            rules={currentAnalysis.decision_rules}
          />

          {/* 建立樣式按鈕 */}
          <div className="glass-panel rounded-xl border border-white/10 p-4 text-center">
            <p className="text-sm text-slate-300 mb-3">
              從此分析結果建立新樣式定義
            </p>
            <button
              onClick={() => {
                // TODO: 導航到樣式建立表單，預填充資料
                if (onPatternCreated) onPatternCreated();
              }}
              className="px-6 py-2 bg-emerald-500/20 text-emerald-100 border border-emerald-500/40 rounded font-semibold hover:bg-emerald-500/30"
            >
              建立樣式定義
            </button>
          </div>
        </div>
      )}

      {/* 空狀態 */}
      {status === 'idle' && (
        <div className="glass-panel rounded-xl border-2 border-dashed border-white/10 p-12 text-center">
          <p className="text-slate-400 text-lg">點擊「開始分析」來執行 XGBoost 樣式發現</p>
        </div>
      )}
    </div>
  );
}

// frontend/src/components/results/DensityComparisonChart.tsx
// 密度對比視覺化 - 箱型圖、直方圖、小提琴圖切換

'use client';

import React, { useState, useMemo } from 'react';
import {
  BarChart,
  Bar,
  ScatterChart,
  Scatter,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  Cell
} from 'recharts';
import { ExportButton } from './ExportButton';
import { DensityTooltip } from './CustomTooltip';

interface DensityComparisonChartProps {
  positiveDensities: number[];
  negativeDensities: number[];
  taskId?: string;
  className?: string;
}

type ChartType = 'histogram' | 'box_plot' | 'scatter';

/**
 * 計算箱型圖統計量
 */
function calculateBoxPlotStats(data: number[]) {
  if (data.length === 0) {
    return {
      min: 0,
      q1: 0,
      median: 0,
      q3: 0,
      max: 0,
      outliers: [],
      mean: 0
    };
  }

  const sorted = [...data].sort((a, b) => a - b);
  const n = sorted.length;

  const q1 = sorted[Math.floor(n * 0.25)];
  const median = sorted[Math.floor(n * 0.5)];
  const q3 = sorted[Math.floor(n * 0.75)];
  const iqr = q3 - q1;
  const lowerFence = q1 - 1.5 * iqr;
  const upperFence = q3 + 1.5 * iqr;

  const outliers = sorted.filter(v => v < lowerFence || v > upperFence);
  const min = Math.max(sorted[0], lowerFence);
  const max = Math.min(sorted[n - 1], upperFence);

  return {
    min,
    q1,
    median,
    q3,
    max,
    outliers,
    mean: data.reduce((a, b) => a + b, 0) / n
  };
}

/**
 * 創建直方圖 bins
 */
function createHistogramBins(
  positiveData: number[],
  negativeData: number[],
  binCount: number = 20
) {
  const allData = [...positiveData, ...negativeData];
  if (allData.length === 0) return [];

  const min = Math.min(...allData);
  const max = Math.max(...allData);

  // 處理所有數據相同的情況
  if (max === min) {
    return [{
      bin: `${min.toFixed(3)}`,
      binStart: min,
      positive: positiveData.length,
      negative: negativeData.length,
    }];
  }

  const binWidth = (max - min) / binCount;

  const bins = [];
  for (let i = 0; i < binCount; i++) {
    const binStart = min + i * binWidth;
    const binEnd = binStart + binWidth;
    const binLabel = `${binStart.toFixed(3)}-${binEnd.toFixed(3)}`;

    const posCount = positiveData.filter(
      v => v >= binStart && v < binEnd
    ).length;
    const negCount = negativeData.filter(
      v => v >= binStart && v < binEnd
    ).length;

    bins.push({
      bin: binLabel,
      binStart,
      positive: posCount,
      negative: negCount,
    });
  }

  return bins;
}

/**
 * 密度對比圖表組件
 */
export const DensityComparisonChart: React.FC<DensityComparisonChartProps> = ({
  positiveDensities,
  negativeDensities,
  taskId = 'unknown',
  className = '',
}) => {
  const [chartType, setChartType] = useState<ChartType>('histogram');

  // 計算統計量
  const stats = useMemo(() => {
    return {
      positive: calculateBoxPlotStats(positiveDensities),
      negative: calculateBoxPlotStats(negativeDensities)
    };
  }, [positiveDensities, negativeDensities]);

  // 直方圖數據
  const histogramData = useMemo(() => {
    return createHistogramBins(positiveDensities, negativeDensities, 20);
  }, [positiveDensities, negativeDensities]);

  // 箱型圖數據（簡化為條形圖表示）
  const boxPlotData = useMemo(() => {
    if (!stats.positive || !stats.negative) return [];

    return [
      {
        group: '正例',
        min: stats.positive.min,
        q1: stats.positive.q1,
        median: stats.positive.median,
        q3: stats.positive.q3,
        max: stats.positive.max,
        mean: stats.positive.mean
      },
      {
        group: '反例',
        min: stats.negative.min,
        q1: stats.negative.q1,
        median: stats.negative.median,
        q3: stats.negative.q3,
        max: stats.negative.max,
        mean: stats.negative.mean
      }
    ];
  }, [stats]);

  // 散點圖數據
  const scatterData = useMemo(() => {
    const positive = positiveDensities.map((density, idx) => ({
      x: 0,
      y: density,
      group: 'positive'
    }));
    const negative = negativeDensities.map((density, idx) => ({
      x: 1,
      y: density,
      group: 'negative'
    }));
    return { positive, negative };
  }, [positiveDensities, negativeDensities]);

  // 渲染直方圖
  const renderHistogram = () => (
    <ResponsiveContainer width="100%" height={400}>
      <BarChart data={histogramData}>
        <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.1)" />
        <defs>
          <linearGradient id="positiveGradient" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="#34d399" stopOpacity={0.9} />
            <stop offset="100%" stopColor="#34d399" stopOpacity={0.4} />
          </linearGradient>
          <linearGradient id="negativeGradient" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="#fb7185" stopOpacity={0.9} />
            <stop offset="100%" stopColor="#fb7185" stopOpacity={0.4} />
          </linearGradient>
        </defs>
        <XAxis
          dataKey="bin"
          angle={-45}
          textAnchor="end"
          height={100}
          tick={{ fontSize: 10 }}
          stroke="#64748b"
        />
        <YAxis label={{ value: '案例數量', angle: -90, position: 'insideLeft', fill: '#64748b' }} stroke="#64748b" />
        <Tooltip content={<DensityTooltip />} />
        <Legend />
        <Bar dataKey="positive" fill="url(#positiveGradient)" name="正例" fillOpacity={0.9} className="chart-glow-success" />
        <Bar dataKey="negative" fill="url(#negativeGradient)" name="反例" fillOpacity={0.9} className="chart-glow-danger" />
      </BarChart>
    </ResponsiveContainer>
  );

  // 渲染箱型圖（簡化版）
  const renderBoxPlot = () => (
    <div className="space-y-6">
      <ResponsiveContainer width="100%" height={300}>
        <BarChart
          data={boxPlotData}
          layout="vertical"
          margin={{ top: 20, right: 30, left: 100, bottom: 20 }}
        >
          <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.1)" />
          <XAxis type="number" domain={[0, 1]} label={{ value: '信號密度', position: 'insideBottom', offset: -10, fill: '#64748b' }} stroke="#64748b" />
          <YAxis type="category" dataKey="group" stroke="#64748b" />
          <Tooltip
            formatter={(value: number) => value.toFixed(4)}
            labelFormatter={(label) => `組別: ${label}`}
          />
          <Legend />
          {/* IQR (Q1-Q3) */}
          <Bar dataKey="q1" stackId="a" fill="transparent" />
          <Bar dataKey="q3" stackId="a" fill="#60a5fa" fillOpacity={0.5} name="四分位距 (IQR)" />
        </BarChart>
      </ResponsiveContainer>

      {/* 統計表格 */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {boxPlotData.map((data) => (
          <div key={data.group} className="bg-white/5 border border-white/10 p-4 rounded-lg">
            <h4 className="font-semibold text-slate-200 mb-3">{data.group} 統計量</h4>
            <div className="space-y-1 text-sm">
              <div className="flex justify-between">
                <span className="text-slate-400">最小值:</span>
                <span className="font-medium text-slate-100">{data.min.toFixed(4)}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-slate-400">第一四分位數 (Q1):</span>
                <span className="font-medium text-slate-100">{data.q1.toFixed(4)}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-slate-400">中位數 (Q2):</span>
                <span className="font-medium text-blue-300">{data.median.toFixed(4)}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-slate-400">第三四分位數 (Q3):</span>
                <span className="font-medium text-slate-100">{data.q3.toFixed(4)}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-slate-400">最大值:</span>
                <span className="font-medium text-slate-100">{data.max.toFixed(4)}</span>
              </div>
              <div className="flex justify-between border-t border-white/10 pt-1 mt-1">
                <span className="text-slate-400">平均值:</span>
                <span className="font-semibold text-emerald-400">{data.mean.toFixed(4)}</span>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );

  // 渲染散點圖（模擬小提琴圖）
  const renderScatter = () => (
    <ResponsiveContainer width="100%" height={400}>
      <ScatterChart margin={{ top: 20, right: 30, left: 20, bottom: 20 }}>
        <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.1)" />
        <XAxis
          type="number"
          dataKey="x"
          domain={[-0.5, 1.5]}
          ticks={[0, 1]}
          tickFormatter={(value) => value === 0 ? '正例' : '反例'}
          stroke="#64748b"
        />
        <YAxis
          type="number"
          dataKey="y"
          domain={[0, 1]}
          label={{ value: '信號密度', angle: -90, position: 'insideLeft', fill: '#64748b' }}
          stroke="#64748b"
        />
        <Tooltip
          cursor={{ strokeDasharray: '3 3' }}
          formatter={(value: number) => value.toFixed(4)}
          labelFormatter={(label) => `組別: ${label === 0 ? '正例' : '反例'}`}
        />
        <Legend />
        <Scatter name="正例" data={scatterData.positive} fill="#34d399" />
        <Scatter name="反例" data={scatterData.negative} fill="#fb7185" />
      </ScatterChart>
    </ResponsiveContainer>
  );

  return (
    <div 
      id="density-comparison-chart"
      className={`density-comparison-chart glass-panel rounded-xl p-6 ${className}`}
    >
      {/* 標題與切換按鈕 */}
      <div className="flex items-center justify-between mb-6">
        <h2 className="text-2xl font-semibold text-slate-100">密度分布對比</h2>

        <div className="flex gap-2 items-center">
          {/* 圖表類型切換 */}
          <button
            onClick={() => setChartType('histogram')}
            className={`
              px-4 py-2 rounded-lg font-medium transition-all
              ${chartType === 'histogram'
                ? 'bg-blue-500/20 text-blue-100 border border-blue-500/40'
                : 'bg-white/10 text-slate-300 border border-white/10 hover:bg-white/15'
              }
            `}
          >
            📊 直方圖
