/**
 * OptimizationHistoryChart.tsx
 * 
 * ULTRA THINK 3-STEP PROCESS DOCUMENTATION:
 * ==========================================
 * 
 * STEP 1 - THINK: Requirements Analysis & Technical Selection
 * ------------------------------------------------------------
 * Data Source: ImportanceAnalysisResponse.optimization_history (Trial[])
 * 
 * Core Visualization Requirements:
 * 1. Convergence curve: trial number vs separation value (Line)
 * 2. Trial state markers: COMPLETE (green circle), PRUNED (gray cross), FAIL (red triangle)
 * 3. Best trial highlight: green star ReferenceDot
 * 4. Hover info: trial number, value, state, duration, datetime
 * 
 * Data Structure Analysis:
 * interface Trial {
 *   number: number;
 *   value: number | null;  // separation score
 *   state: 'COMPLETE' | 'PRUNED' | 'FAIL';
 *   datetime_start: string;
 *   datetime_complete: string | null;
 *   duration: number | null;
 *   params: Record<string, number | string | boolean>;
 * }
 * 
 * Technical Selection:
 * - Recharts ComposedChart (Line + Scatter overlay)
 * - Line: Only connect COMPLETE trials to show convergence trend
 * - Scatter: All trials with state-based styling
 * - ReferenceDot: Mark best trial (highest separation)
 * 
 * STEP 2 - REVIEW: Edge Cases & Type Safety
 * ------------------------------------------
 * Edge Cases Identified:
 * 1. Empty trials array → Show friendly message
 * 2. All trials PRUNED/FAIL → No convergence line, only scatter
 * 3. Trial.value === null → Filter out from Line, show in Scatter with special marker
 * 4. Single trial → No trend line (need min 2 points)
 * 5. 1000+ trials → Performance concern, use useMemo for data processing
 * 
 * Type Safety:
 * - Filter null values before rendering Line
 * - Safe datetime parsing (fallback to "N/A")
 * - Handle missing duration (null → "N/A")
 * 
 * Error Handling:
 * - Return early if !data || data.length === 0
 * - Graceful degradation for incomplete trial data
 * 
 * STEP 3 - OPTIMIZE: Visual Consistency & Performance
 * ----------------------------------------------------
 * Performance:
 * - useMemo to process chart data (filter, sort, mark best trial)
 * - useMemo to find best trial
 * - Avoid inline functions in render (pre-calculate data)
 * 
 * Visual Consistency:
 * - Colors match global scheme:
 *   - COMPLETE: #10b981 (green, same as MetricsPanel good values)
 *   - PRUNED: #6b7280 (gray, neutral)
 *   - FAIL: #ef4444 (red, same as MetricsPanel bad values)
 *   - Best trial star: #10b981 (green)
 * - Consistent formatting: 4 decimals for separation, ISO datetime
 * 
 * Code Reuse:
 * - CustomTooltip pattern from StabilityChart
 * - formatValue utility for null/NaN handling
 * 
 * UX Improvements:
 * - Legend explains state markers
 * - Best trial tooltip shows "Best Trial: #X"
 * - Duration shown in seconds with 2 decimals
 * - Datetime shown in readable format (YYYY-MM-DD HH:mm)
 */

'use client';

import React, { useMemo } from 'react';
import {
  ComposedChart,
  Line,
  Scatter,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ReferenceDot,
} from 'recharts';
import type { Trial, TrialSummary } from '@/lib/types';
import { ExportButton } from './ExportButton';
import { OptimizationHistoryTooltip } from './CustomTooltip';

interface OptimizationHistoryChartProps {
  data: Trial[] | TrialSummary[];
  taskId?: string;
  className?: string;
}

/**
 * Format value with null/NaN/Infinity handling
 */
const formatValue = (value: number | null | undefined, decimals: number = 4): string => {
  if (value == null || isNaN(value) || !isFinite(value)) {
    return 'N/A';
  }
  return value.toFixed(decimals);
};


/**
 * OptimizationHistoryChart Component
 * 
 * Displays Optuna optimization progress:
 * - Line chart showing convergence of COMPLETE trials
 * - Scatter plot showing all trials colored by state
 * - Best trial marked with green star
 */
export const OptimizationHistoryChart: React.FC<OptimizationHistoryChartProps> = ({
  data,
  taskId = 'unknown',
  className = '',
}) => {
  const safeData = data ?? [];

  // PERFORMANCE: useMemo to process chart data
  const chartData = useMemo(() => {
    return safeData.map((trial) => ({
      ...trial,
      // For Line: only COMPLETE trials with non-null values
      lineValue: trial.state === 'COMPLETE' && trial.value != null ? trial.value : null,
      // For Scatter: all trials
      scatterValue: trial.value,
    }));
  }, [safeData]);

  // PERFORMANCE: useMemo to find best trial
  const bestTrial = useMemo(() => {
    const completedTrials = safeData.filter((t) => t.state === 'COMPLETE' && t.value != null);
    if (completedTrials.length === 0) return null;

    return completedTrials.reduce((best, current) => {
      return (current.value ?? -Infinity) > (best.value ?? -Infinity) ? current : best;
    });
  }, [safeData]);

  // Attach bestValue to chart data for tooltip highlighting
  const chartDataWithBest = useMemo(() => {
    return chartData.map((item) => ({
      ...item,
      bestValue: bestTrial?.value,
    }));
  }, [chartData, bestTrial]);

  // Calculate Y-axis domain (with 10% padding)
  const yDomain = useMemo(() => {
    const values = safeData.filter((t) => t.value != null).map((t) => t.value as number);
    if (values.length === 0) return [0, 1];

    const min = Math.min(...values);
    const max = Math.max(...values);
    const padding = (max - min) * 0.1;

    return [min - padding, max + padding];
  }, [safeData]);

  if (safeData.length === 0) {
    return (
      <div className={`glass-panel rounded-xl p-6 ${className}`}>
        <h3 className="text-lg font-semibold text-slate-100 mb-4">
          Optimization History
        </h3>
        <div className="flex items-center justify-center h-64 text-slate-400">
          No optimization history data available.
        </div>
      </div>
    );
  }

  return (
    <div 
      id="optimization-history-chart"
      className={`glass-panel rounded-xl p-6 ${className}`}
    >
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-semibold text-slate-100">
          Optimization History
        </h3>
        <ExportButton
          elementId="optimization-history-chart"
          chartName="OptimizationHistory"
          taskId={taskId}
        />
      </div>

      <ResponsiveContainer width="100%" height={400}>
        <ComposedChart
          data={chartDataWithBest}
          margin={{ top: 10, right: 30, left: 0, bottom: 0 }}
        >
          <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.1)" />
          <XAxis
            dataKey="trial_number"
            label={{ value: 'Trial Number', position: 'insideBottom', offset: -5 }}
            stroke="#64748b"
          />
          <YAxis
            domain={yDomain}
            label={{ value: 'Separation', angle: -90, position: 'insideLeft' }}
            stroke="#64748b"
            tickFormatter={(value) => value.toFixed(2)}
          />
          <Tooltip content={<OptimizationHistoryTooltip />} />
          <Legend
            wrapperStyle={{ paddingTop: '20px' }}
            iconType="circle"
            formatter={(value) => {
              const labels: Record<string, string> = {
                lineValue: 'Convergence Trend (COMPLETE)',
                COMPLETE: 'Complete Trials',
                PRUNED: 'Pruned Trials',
                FAIL: 'Failed Trials',
              };
              return labels[value] || value;
            }}
          />

          {/* Convergence Line: Only COMPLETE trials */}
          <Line
            type="monotone"
            dataKey="lineValue"
            name="lineValue"
            stroke="#60a5fa"
            strokeWidth={2}
            dot={false}
            connectNulls={false}
            isAnimationActive={false}
          />

          {/* Scatter: All trials colored by state */}
          <Scatter
            name="COMPLETE"
            dataKey="scatterValue"
            data={chartDataWithBest.filter((t) => t.state === 'COMPLETE')}
            fill="#34d399"
            shape="circle"
          />
          <Scatter
            name="PRUNED"
            dataKey="scatterValue"
            data={chartDataWithBest.filter((t) => t.state === 'PRUNED')}
            fill="#64748b"
            shape="cross"
          />
          <Scatter
            name="FAIL"
            dataKey="scatterValue"
            data={chartDataWithBest.filter((t) => t.state === 'FAIL')}
            fill="#fb7185"
            shape="triangle"
          />

          {/* Best Trial Marker */}
          {bestTrial && (
            <ReferenceDot
              x={bestTrial.trial_number}
              y={bestTrial.value}
              r={10}
              fill="#34d399"
              stroke="rgba(255,255,255,0.4)"
              strokeWidth={2}
              ifOverflow="extendDomain"
            />
          )}
        </ComposedChart>
      </ResponsiveContainer>

      {/* Summary Stats */}
      <div className="mt-4 grid grid-cols-4 gap-4 text-sm">
        <div className="text-center">
          <div className="text-slate-400">Total Trials</div>
          <div className="text-lg font-semibold text-slate-100">
            {safeData.length}
          </div>
        </div>
        <div className="text-center">
          <div className="text-slate-400">Complete</div>
          <div className="text-lg font-semibold text-emerald-400">
            {safeData.filter((t) => t.state === 'COMPLETE').length}
          </div>
        </div>
        <div className="text-center">
          <div className="text-slate-400">Pruned</div>
          <div className="text-lg font-semibold text-slate-400">
            {safeData.filter((t) => t.state === 'PRUNED').length}
          </div>
        </div>
        <div className="text-center">
          <div className="text-slate-400">Failed</div>
          <div className="text-lg font-semibold text-rose-400">
            {safeData.filter((t) => t.state === 'FAIL').length}
          </div>
        </div>
      </div>

      {bestTrial && (
        <div className="mt-4 bg-emerald-400/10 border border-emerald-400/30 rounded-lg p-3">
          <div className="flex items-center gap-2">
            <span className="text-2xl">⭐</span>
            <div>
              <div className="font-semibold text-emerald-200">
                Best Trial: #{bestTrial.trial_number}
              </div>
              <div className="text-sm text-emerald-300">
                Separation: {formatValue(bestTrial.value)}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

/**
