 * 
 * STEP 2 - REVIEW: Edge Cases & Type Safety
 * ------------------------------------------
 * Edge Cases Identified:
 * 1. Empty array → Show friendly message
 * 2. All importance === 0 → Show warning (optimization ineffective)
 * 3. Long parameter names (>20 chars) → Truncate with tooltip
 * 4. 20+ parameters → Chart too tall, set max height with scroll
 * 5. Single parameter → Still show bar (valid edge case)
 * 
 * Type Safety:
 * - importance guaranteed 0-1 by backend
 * - significance_level string validation (use getSignificanceLevel utility)
 * - Handle missing fields gracefully
 * 
 * Error Handling:
 * - Return early if !data || data.length === 0
 * - Validate significance_level mapping
 * 
 * STEP 3 - OPTIMIZE: Visual Consistency & Performance
 * ----------------------------------------------------
 * Performance:
 * - useMemo to sort data by importance (descending)
 * - useMemo to calculate dynamic chart height
 * - Avoid inline color mapping (pre-define color map)
 * 
 * Visual Consistency:
 * - Colors match getSignificanceLevel() utility:
 *   - "高度顯著": #10b981 (green, p < 0.01)
 *   - "顯著": #eab308 (yellow, 0.01 <= p < 0.05)
 *   - "不顯著": #9ca3af (gray, p >= 0.05)
 * - Consistent formatting: importance as percentage (XX.X%)
 * 
 * Code Reuse:
 * - CustomTooltip pattern from OptimizationHistoryChart
 * - formatValue utility for null/NaN handling
 * 
 * UX Improvements:
 * - Parameter names shown in full on Y-axis (no truncation, chart adjusts height)
 * - Hover tooltip shows exact p-value and effect size
 * - Legend explains significance levels
 * - Grid lines for easier reading
 */

'use client';

import React, { useMemo } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  Cell,
  LabelList,
} from 'recharts';
import type { ParamImportance } from '@/lib/types';
import { ExportButton } from './ExportButton';
import { ParameterImportanceTooltip } from './CustomTooltip';

interface ParameterImportanceChartProps {
  data: ParamImportance[];
  taskId?: string;
  className?: string;
}

/**
 * Importance level color mapping (by rank)
 */
const getImportanceColor = (rank: number, total: number): string => {
  const percentage = rank / total;
  if (percentage <= 0.3) return '#34d399'; // Top 30% - emerald
  if (percentage <= 0.7) return '#fbbf24'; // Middle 40% - amber
  return '#64748b'; // Bottom 30% - slate
};


/**
 * Custom label to show percentage on bars
 */
const CustomLabel = (props: unknown) => {
  const { x, y, width, value } = props;
  const percentage = (value * 100).toFixed(1);

  return (
    <text
      x={x + width + 5}
      y={y + 12}
      fill="#cbd5e1"
      fontSize={12}
      fontWeight={500}
      textAnchor="start"
    >
      {percentage}%
    </text>
  );
};

/**
 * ParameterImportanceChart Component
 * 
 * Displays parameter importance ranking from Optuna FIS analysis:
 * - Horizontal bar chart sorted by importance (descending)
 * - Colored by significance level (green/yellow/gray)
 * - Shows percentage labels on bars
 */
export const ParameterImportanceChart: React.FC<ParameterImportanceChartProps> = ({
  data,
  taskId = 'unknown',
  className = '',
}) => {
  const safeData = data ?? [];

  // PERFORMANCE: useMemo to sort data by importance (descending)
  const sortedData = useMemo(() => {
    return [...safeData].sort((a, b) => b.importance - a.importance);
  }, [safeData]);

  // PERFORMANCE: useMemo to calculate dynamic chart height
  const chartHeight = useMemo(() => {
    // Each parameter needs ~50px height, min 300px, max 800px
    return Math.max(300, Math.min(800, sortedData.length * 50));
  }, [sortedData.length]);

  // Check if all importance values are 0 (optimization ineffective)
  const allZero = sortedData.every((param) => param.importance === 0);

  if (safeData.length === 0) {
    return (
      <div className={`glass-panel rounded-xl p-6 ${className}`}>
        <h3 className="text-lg font-semibold text-slate-100 mb-4">
          Parameter Importance
        </h3>
        <div className="flex items-center justify-center h-64 text-slate-400">
          No parameter importance data available.
        </div>
      </div>
    );
  }

  return (
    <div 
      id="parameter-importance-chart"
      className={`glass-panel rounded-xl p-6 ${className}`}
    >
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-semibold text-slate-100">
          Parameter Importance (FIS Analysis)
        </h3>
        <ExportButton
          elementId="parameter-importance-chart"
          chartName="ParameterImportance"
          taskId={taskId}
        />
      </div>

      {allZero && (
        <div className="mb-4 bg-amber-400/10 border border-amber-400/30 rounded-lg p-3 text-sm text-amber-300">
          ⚠️ All parameters show 0% importance. This may indicate optimization issues or insufficient trials.
        </div>
      )}

      <ResponsiveContainer width="100%" height={chartHeight}>
        <BarChart
          data={sortedData}
          layout="horizontal"
          margin={{ top: 10, right: 60, left: 120, bottom: 10 }}
        >
          <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.1)" />
          <XAxis
            type="number"
            domain={[0, 1]}
            tickFormatter={(value) => `${(value * 100).toFixed(0)}%`}
            label={{ value: 'Importance (%)', position: 'insideBottom', offset: -5 }}
            stroke="#64748b"
          />
          <YAxis
            type="category"
            dataKey="parameter_name"
            width={110}
            stroke="#64748b"
            tick={{ fontSize: 12 }}
          />
          <Tooltip content={<ParameterImportanceTooltip />} />
          <Legend
            wrapperStyle={{ paddingTop: '20px' }}
            payload={[
              { value: 'Top 30% (High Importance)', type: 'square', color: '#34d399' },
              { value: 'Middle 40% (Medium)', type: 'square', color: '#fbbf24' },
              { value: 'Bottom 30% (Low)', type: 'square', color: '#64748b' },
            ]}
          />

          <Bar dataKey="importance" radius={[0, 4, 4, 0]}>
            {sortedData.map((entry, index) => (
              <Cell
                key={`cell-${index}`}
                fill={getImportanceColor(entry.rank, sortedData.length)}
              />
            ))}
            <LabelList content={<CustomLabel />} />
          </Bar>
        </BarChart>
      </ResponsiveContainer>

      {/* Summary Stats */}
      <div className="mt-4 grid grid-cols-3 gap-4 text-sm">
        <div className="text-center">
          <div className="text-slate-400">Total Parameters</div>
          <div className="text-lg font-semibold text-slate-100">
            {sortedData.length}
          </div>
        </div>
        <div className="text-center">
          <div className="text-slate-400">High Importance (Top 30%)</div>
          <div className="text-lg font-semibold text-emerald-400">
            {Math.ceil(sortedData.length * 0.3)}
          </div>
        </div>
        <div className="text-center">
          <div className="text-slate-400">Low Importance (Bottom 30%)</div>
          <div className="text-lg font-semibold text-slate-400">
            {Math.floor(sortedData.length * 0.3)}
          </div>
        </div>
      </div>

      {/* Top 3 Most Important Parameters */}
      {sortedData.length >= 3 && (
        <div className="mt-4 bg-blue-400/10 border border-blue-400/30 rounded-lg p-3">
          <div className="font-semibold text-blue-200 mb-2">
            🏆 Top 3 Most Important Parameters
          </div>
          <ol className="list-decimal list-inside text-sm text-blue-300 space-y-1">
            {sortedData.slice(0, 3).map((param, index) => (
              <li key={index}>
                <span className="font-medium">{param.parameter_name}</span>:{' '}
                {(param.importance * 100).toFixed(1)}% (Rank #{param.rank})
              </li>
            ))}
          </ol>
        </div>
      )}
    </div>
  );
};

