 * 默認配置
 */
const DEFAULT_CONFIG: OptunaConfig = {
  enabled: false,
  n_trials: 50,
  n_startup_trials: null,  // null 則自動計算為 n_trials 的 15%
  timeout: 1800,  // 30 minutes
  random_seed: 42,
  enable_pruning: true,
  n_jobs: 4,  // 默認使用 4 核並行
  ema_short_range: [5, 15],
  ema_mid_range: [20, 40],
  ema_long_range: [50, 100]
}

export function OptunaConfigPanel({
  config,
  onChange,
  disabled = false
}: OptunaConfigPanelProps) {
  // 驗證警告
  const validationWarnings = useMemo(() => {
    const warnings: string[] = []

    // 參數範圍檢查 (short < mid < long)
    if (config.ema_short_range[1] >= config.ema_mid_range[0]) {
      warnings.push(`EMA Short Max (${config.ema_short_range[1]}) >= Mid Min (${config.ema_mid_range[0]})，範圍重疊`)
    }
    if (config.ema_mid_range[1] >= config.ema_long_range[0]) {
      warnings.push(`EMA Mid Max (${config.ema_mid_range[1]}) >= Long Min (${config.ema_long_range[0]})，範圍重疊`)
    }

    // Trial 數量檢查
    if (config.n_trials < 20) {
      warnings.push(`Trial 數量較少 (${config.n_trials})，建議至少 20 次以獲得穩定結果`)
    }

    return warnings
  }, [config])

  // 預估時間計算
  const estimatedTime = useMemo(() => {
    // 假設每個 trial 平均 30-60 秒
    const avgTrialTime = 45  // seconds
    const totalSeconds = config.n_trials * avgTrialTime

    if (totalSeconds < 60) return `約 ${totalSeconds} 秒`
    if (totalSeconds < 3600) return `約 ${Math.ceil(totalSeconds / 60)} 分鐘`
    return `約 ${(totalSeconds / 3600).toFixed(1)} 小時`
  }, [config.n_trials])

  // 更新配置
  const updateConfig = (partial: Partial<OptunaConfig>) => {
    onChange({ ...config, ...partial })
  }

  // 更新範圍
  const updateRange = (
    key: 'ema_short_range' | 'ema_mid_range' | 'ema_long_range',
    index: 0 | 1,
    value: number
  ) => {
    const newRange: [number, number] = [...config[key]]
    newRange[index] = value
    updateConfig({ [key]: newRange })
  }

  return (
    <div className="space-y-6">
      {/* 啟用開關 */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Sparkles className="h-5 w-5 text-violet-300" />
          <div>
            <Label className="text-base font-semibold text-slate-100">
              Optuna 參數優化
            </Label>
            <p className="text-sm text-slate-400">
              自動搜索最佳參數組合
            </p>
          </div>
        </div>
        <Switch
          checked={config.enabled}
          onCheckedChange={(checked) => updateConfig({ enabled: checked })}
          disabled={disabled}
        />
      </div>

      {/* 配置區域（僅在啟用時顯示） */}
      {config.enabled && (
        <>
          {/* 基礎設定 */}
          <div className="space-y-4 rounded-lg border border-white/10 bg-white/5 p-4">
            <h3 className="text-sm font-semibold flex items-center gap-2 text-slate-100">
              基礎設定
              <Badge variant="outline" className="text-xs border-white/10 text-slate-300">
                <Clock className="h-3 w-3 mr-1" />
                {estimatedTime}
              </Badge>
            </h3>

            <div className="grid grid-cols-2 gap-4">
              {/* Trial 次數 */}
              <div className="space-y-2">
                <Label htmlFor="n_trials" className="text-slate-200">Trial 次數</Label>
                <Input
                  id="n_trials"
                  type="number"
                  min={10}
                  max={1000}
                  value={config.n_trials}
                  onChange={(e) => updateConfig({ n_trials: parseInt(e.target.value) || 50 })}
                  disabled={disabled}
                  className="bg-white/5 border-white/10 text-slate-100 placeholder:text-slate-500"
                />
                <p className="text-xs text-slate-400">
                  建議 20-100 次
                </p>
              </div>

              {/* 超時時間 */}
              <div className="space-y-2">
                <Label htmlFor="timeout" className="text-slate-200">超時時間（秒）</Label>
                <Input
                  id="timeout"
                  type="number"
                  min={300}
                  max={36000}
                  step={300}
                  value={config.timeout}
                  onChange={(e) => updateConfig({ timeout: parseInt(e.target.value) || 1800 })}
                  disabled={disabled}
                  className="bg-white/5 border-white/10 text-slate-100 placeholder:text-slate-500"
                />
                <p className="text-xs text-slate-400">
                  {Math.floor(config.timeout / 60)} 分鐘
                </p>
              </div>

              {/* 隨機種子 */}
              <div className="space-y-2">
                <Label htmlFor="random_seed" className="text-slate-200">隨機種子</Label>
                <Input
                  id="random_seed"
                  type="number"
                  min={0}
                  max={9999}
                  value={config.random_seed}
                  onChange={(e) => updateConfig({ random_seed: parseInt(e.target.value) || 42 })}
                  disabled={disabled}
                  className="bg-white/5 border-white/10 text-slate-100 placeholder:text-slate-500"
                />
                <p className="text-xs text-slate-400">
                  固定種子可重現結果
                </p>
              </div>

              {/* 初始隨機試驗數 */}
              <div className="space-y-2">
                <Label htmlFor="n_startup_trials" className="flex items-center gap-2 text-slate-200">
                  初始隨機數
                  <Badge variant="outline" className="text-xs border-white/10 text-slate-300">
                    TPE
                  </Badge>
                </Label>
                <Input
                  id="n_startup_trials"
                  type="number"
                  min={1}
                  max={100}
                  value={config.n_startup_trials ?? ''}
                  placeholder={`自動 (${Math.max(10, Math.floor(config.n_trials * 0.15))})`}
                  onChange={(e) => {
                    const val = e.target.value
                    updateConfig({ n_startup_trials: val === '' ? null : parseInt(val) || null })
