    mode: "relative",
  },
  symbols: ["ALL_SYMBOLS"],
  timeframe: "12h",
  dateRange: {
    start: formatDate(defaultStart),
    end: formatDate(now),
  },
  clusteringWeight: 0.5,
  syncToUrl: true,
  templateId: null,
};

const encodePayload = (payload: StrategyUrlPayload): string | null => {
  try {
    const json = JSON.stringify(payload);
    if (typeof window === "undefined") {
      return Buffer.from(json, "utf-8").toString("base64");
    }
    return window.btoa(encodeURIComponent(json));
  } catch (error) {
    console.error("策略配置序列化失敗", error);
    return null;
  }
};

const decodePayload = (encoded: string): StrategyUrlPayload | null => {
  try {
    const json =
      typeof window === "undefined"
        ? Buffer.from(encoded, "base64").toString("utf-8")
        : decodeURIComponent(window.atob(encoded));
    return JSON.parse(json) as StrategyUrlPayload;
  } catch (error) {
    console.error("策略配置反序列化失敗", error);
    return null;
  }
};

const buildUrlPayload = (state: StrategyFormState): StrategyUrlPayload => ({
  dataSources: state.dataSources,
  indicatorType: state.indicatorType,
  strategyLogic: state.strategyLogic,
  indicatorParams: state.indicatorParams,
  windowConfig: state.windowConfig,
  symbols: state.symbols,
  timeframe: state.timeframe,
  dateRange: state.dateRange,
  clusteringWeight: state.clusteringWeight,
});

// 清理舊版參數名稱 (ema_short -> short_period 等)
const cleanIndicatorParams = (
  params: Record<string, number>
): Record<string, number> => {
  const legacyToNew: Record<string, string> = {
    ema_short: "short_period",
    ema_mid: "mid_period",
    ema_long: "long_period",
  };

  const cleaned: Record<string, number> = {};

  for (const [key, value] of Object.entries(params)) {
    // 如果是舊版 key 且新版 key 不存在，則轉換
    if (key in legacyToNew) {
      const newKey = legacyToNew[key];
      if (!(newKey in params) && !(newKey in cleaned)) {
        cleaned[newKey] = value;
      }
      // 舊版 key 不保留
    } else {
      cleaned[key] = value;
    }
  }

  return cleaned;
};

const mergeFromPayload = (
  original: StrategyFormState,
  payload: StrategyUrlPayload
): StrategyFormState => ({
  ...original,
  dataSources: payload.dataSources ?? original.dataSources,
  indicatorType: payload.indicatorType ?? original.indicatorType,
  strategyLogic: payload.strategyLogic ?? original.strategyLogic,
  indicatorParams: cleanIndicatorParams({
    ...original.indicatorParams,
    ...payload.indicatorParams,
  }),
  windowConfig: {
    ...original.windowConfig,
    ...payload.windowConfig,
  },
  symbols: payload.symbols ?? original.symbols,
  timeframe: payload.timeframe ?? original.timeframe,
  dateRange: payload.dateRange ?? original.dateRange,
  clusteringWeight: payload.clusteringWeight ?? original.clusteringWeight,
  templateId: null,
});

const hasPlainParams = (params?: URLSearchParams | null): boolean => {
  if (!params) return false;
  const candidateKeys = [
    "symbol",
    "timeframe",
    "start",
    "end",
    "dataSources",
    "indicatorType",
    "strategyLogic",
    "emaShort",
    "emaMid",
    "emaLong",
    "lookback",
    "farLookback",
    "forward",
    "clusterWeight",
  ];
  return candidateKeys.some((key) => params.has(key));
};

const parsePlainQueryPayload = (
  params: URLSearchParams
): StrategyUrlPayload | null => {
  if (!hasPlainParams(params)) {
    return null;
  }

  const getNumber = (key: string): number | undefined => {
    const value = params.get(key);
    if (value === null || value === "") return undefined;
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : undefined;
  };

  const getDate = (key: "start" | "end", fallback: string): string => {
    const value = params.get(key);
    if (!value) return fallback;
    return value.slice(0, 10);
  };

  const dataSourcesParam = params.get("dataSources");
  const parsedDataSource = dataSourcesParam?.trim() || null;

  const indicatorParams = {
    ...DEFAULT_STATE.indicatorParams,
    short_period: getNumber("emaShort") ?? DEFAULT_STATE.indicatorParams.short_period,
    mid_period: getNumber("emaMid") ?? DEFAULT_STATE.indicatorParams.mid_period,
    long_period: getNumber("emaLong") ?? DEFAULT_STATE.indicatorParams.long_period,
  };

  const windowConfig: StrategyWindowConfig = {
    ...DEFAULT_STATE.windowConfig,
    lookback_bars:
      getNumber("lookback") ?? DEFAULT_STATE.windowConfig.lookback_bars,
    lookforward_bars:
      getNumber("forward") ?? DEFAULT_STATE.windowConfig.lookforward_bars,
    far_lookback_bars:
      getNumber("farLookback") ?? DEFAULT_STATE.windowConfig.far_lookback_bars,
  };

  const clusteringWeight = getNumber("clusterWeight");

  return {
    dataSources: parsedDataSource ?? DEFAULT_STATE.dataSources,
    indicatorType:
      params.get("indicatorType") ?? DEFAULT_STATE.indicatorType,
    strategyLogic:
      params.get("strategyLogic") ?? DEFAULT_STATE.strategyLogic,
    indicatorParams,
    windowConfig,
    symbols: params.get("symbols")?.split(",").filter(s => s.trim()) ?? DEFAULT_STATE.symbols,
    timeframe: params.get("timeframe") ?? DEFAULT_STATE.timeframe,
    dateRange: {
      start: getDate("start", DEFAULT_STATE.dateRange.start),
      end: getDate("end", DEFAULT_STATE.dateRange.end),
    },
    clusteringWeight:
      typeof clusteringWeight === "number"
        ? Math.min(Math.max(clusteringWeight, 0), 1)
        : DEFAULT_STATE.clusteringWeight,
  };
};

const appendPlainQueryParams = (
  params: URLSearchParams,
  state: StrategyFormState
) => {
  const assignIfValue = (key: string, value?: string | number | null) => {
    if (value === undefined || value === null) return;
    const stringValue = typeof value === "number" ? String(value) : value;
    if (!stringValue) return;
    params.set(key, stringValue);
  };

  assignIfValue("symbols", state.symbols.join(","));
  assignIfValue("timeframe", state.timeframe);
  assignIfValue("start", state.dateRange.start);
  assignIfValue("end", state.dateRange.end);
  assignIfValue("dataSources", state.dataSources);
  assignIfValue("indicatorType", state.indicatorType);
  assignIfValue("strategyLogic", state.strategyLogic);
  assignIfValue("emaShort", state.indicatorParams.short_period);
  assignIfValue("emaMid", state.indicatorParams.mid_period);
  assignIfValue("emaLong", state.indicatorParams.long_period);
  assignIfValue("lookback", state.windowConfig.lookback_bars);
  assignIfValue("farLookback", state.windowConfig.far_lookback_bars);
  assignIfValue("forward", state.windowConfig.lookforward_bars);
  assignIfValue("clusterWeight", state.clusteringWeight);
};

const normalizeSearchParams = (
  input?: string | URLSearchParams
): { params: URLSearchParams | null; directState: string | null } => {
  if (input instanceof URLSearchParams) {
    return { params: input, directState: null };
  }

  if (typeof input === "string" && input.length > 0) {
    if (input.includes("=")) {
      const params = new URLSearchParams(
        input.startsWith("?") ? input : `?${input}`
      );
      return { params, directState: null };
    }
    return { params: null, directState: input };
  }

  if (typeof window !== "undefined") {
    return {
      params: new URLSearchParams(window.location.search),
      directState: null,
    };
  }

  return { params: null, directState: null };
};

const readTemplatesFromStorage = (): StrategyTemplatePayload[] => {
  if (typeof window === "undefined") return [];
  try {
    const raw = window.localStorage.getItem(TEMPLATE_STORAGE_KEY);
    return raw ? (JSON.parse(raw) as StrategyTemplatePayload[]) : [];
  } catch (error) {
    console.error("讀取策略範本失敗", error);
    return [];
  }
};

const writeTemplatesToStorage = (templates: StrategyTemplatePayload[]) => {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(
      TEMPLATE_STORAGE_KEY,
      JSON.stringify(templates)
    );
  } catch (error) {
    console.error("寫入策略範本失敗", error);
  }
};

const cacheEncodedPayload = (encoded: string) => {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(STATE_CACHE_KEY, encoded);
  } catch (error) {
    console.error("寫入策略快照失敗", error);
  }
};

const readCachedEncodedPayload = (): string | null => {
  if (typeof window === "undefined") return null;
  try {
    return window.localStorage.getItem(STATE_CACHE_KEY);
  } catch (error) {
    console.error("讀取策略快照失敗", error);
    return null;
  }
};

const clearCachedEncodedPayload = () => {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.removeItem(STATE_CACHE_KEY);
  } catch (error) {
    console.error("清除策略快照失敗", error);
  }
};

export const useStrategyConfig = create<StrategyConfigStore>()(
  persist(
    (set, get) => ({
      state: DEFAULT_STATE,
      lastSyncedQuery: null,
      lastHydrationSource: "default",
      isHydrated: false,
      setField: (key, value) =>
        set((current) => ({
          state: {
            ...current.state,
            [key]: value,
          },
        })),
      setFields: (values) =>
        set((current) => ({
          state: {
            ...current.state,
            ...values,
          },
        })),
      reset: () =>
        set(() => {
          clearCachedEncodedPayload();
          return {
            state: DEFAULT_STATE,
            lastHydrationSource: "default",
            lastSyncedQuery: null,
          };
        }),
      saveTemplate: ({ name, description }) => {
        if (!name.trim()) {
          console.warn("範本名稱不得為空");
          return null;
        }
        const snapshot = get().state;
        const template: StrategyTemplatePayload = {
          id: `tpl_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
          name: name.trim(),
          description: description?.trim(),
          createdAt: Date.now(),
          updatedAt: Date.now(),
          state: snapshot,
        };
        const existing = readTemplatesFromStorage();
        writeTemplatesToStorage([...existing, template]);
        set((current) => ({
          state: {
            ...current.state,
            templateId: template.id,
          },
        }));
        return template;
      },
      loadTemplate: (template) =>
        set({
          state: {
            ...template.state,
            templateId: template.id,
          },
          lastHydrationSource: "storage",
          isHydrated: true,
        }),
      listTemplates: () => readTemplatesFromStorage(),
      deleteTemplate: (templateId) => {
        const currentTemplates = readTemplatesFromStorage();
        const filtered = currentTemplates.filter((tpl) => tpl.id !== templateId);
        writeTemplatesToStorage(filtered);
        set((current) => ({
          state: {
            ...current.state,
            templateId:
              current.state.templateId === templateId
                ? null
                : current.state.templateId,
          },
        }));
      },
      syncToUrl: (extraParams = {}) => {
        if (!get().state.syncToUrl) return null;
        const snapshot = get().state;
        const payload = buildUrlPayload(snapshot);
        const encoded = encodePayload(payload);
        if (!encoded) return null;
        cacheEncodedPayload(encoded);
        const params = new URLSearchParams(extraParams);
        appendPlainQueryParams(params, snapshot);
        params.set("state", encoded);
        const query = params.toString();
        set({
          lastSyncedQuery: query,
        });
        return `?${query}`;
      },
      hydrateFromUrl: (input) => {
        const { params, directState } = normalizeSearchParams(input);
        const encoded = directState ?? params?.get("state") ?? null;

        if (encoded) {
          const payload = decodePayload(encoded);
          if (!payload) return false;
          cacheEncodedPayload(encoded);
          set((current) => ({
            state: mergeFromPayload(current.state, payload),
            lastHydrationSource: "url",
            isHydrated: true,
          }));
          return true;
        }

        if (params) {
          const plainPayload = parsePlainQueryPayload(params);
          if (plainPayload) {
            set((current) => ({
              state: mergeFromPayload(current.state, plainPayload),
              lastHydrationSource: "url",
              isHydrated: true,
            }));
            return true;
          }
        }

        return false;
      },
      hydrateFromCache: () => {
        const encoded = readCachedEncodedPayload();
        if (!encoded) return false;
        const payload = decodePayload(encoded);
        if (!payload) return false;
        set((current) => ({
          state: mergeFromPayload(current.state, payload),
          lastHydrationSource: "storage",
          isHydrated: true,
        }));
        return true;
      },
      cacheStateSnapshot: () => {
        const payload = buildUrlPayload(get().state);
        const encoded = encodePayload(payload);
        if (!encoded) return null;
        cacheEncodedPayload(encoded);
        return encoded;
      },
    }),
    {
      name: STORE_KEY,
      storage: createJSONStorage(() => localStorage),
      version: 2, // 版本升級到 2 以觸發遷移
      migrate: (persistedState: unknown, version: number) => {
        // 遷移舊版 symbol (string) 到新版 symbols (string[])
        if (persistedState?.state) {
          const oldState = persistedState.state;

          // 如果有舊的 symbol 欄位且沒有 symbols 欄位
          if (oldState.symbol && !oldState.symbols) {
            oldState.symbols = [oldState.symbol];
            delete oldState.symbol; // 移除舊欄位
          }

          // 確保 symbols 至少有預設值
          if (!oldState.symbols || !Array.isArray(oldState.symbols) || oldState.symbols.length === 0) {
            oldState.symbols = ["ALL_SYMBOLS"];
          }
        }

        return persistedState;
      },
      partialize: (store) => ({
        state: store.state,
        lastSyncedQuery: store.lastSyncedQuery,
        lastHydrationSource: store.lastHydrationSource,
        isHydrated: store.isHydrated,
      }),
      onRehydrateStorage: () => (state, error) => {
        if (error) {
          console.error("策略狀態恢復失敗", error);
          return;
        }
        if (state) {
          // 清理 localStorage 中的舊版參數名稱
          if (state.state?.indicatorParams) {
            state.state.indicatorParams = cleanIndicatorParams(state.state.indicatorParams);
          }

          // 再次確保 symbols 欄位存在（雙重保險）
          if (!state.state?.symbols || !Array.isArray(state.state.symbols) || state.state.symbols.length === 0) {
            state.state.symbols = ["ALL_SYMBOLS"];
          }

          state.lastHydrationSource = "storage";
          state.isHydrated = true;
        }
      },
    }
  )
);

// frontend/src/lib/api.ts 
// API client for connecting to FastAPI backend - 兩階段搜索版本

import { ApiResponse, SearchResultData, SearchTemplate, SearchRequest, TaskInfo } from './types';

const API_BASE_URL = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000';
const API_PREFIX = '/api/v1';

// 後端搜索配置請求格式
interface SearchConfigRequest {
  name: string;
  timeframe: string;
  initial_conditions: FilterConditionRequest[];
  symbols?: string[];
  save_results?: boolean;
  // ✅ 修復：添加時間範圍字段
  startDate?: string | null;
  endDate?: string | null;
  // ✅ 新增：價格計算方式
  price_change_method?: string;
}

interface FilterConditionRequest {
  condition_type: string;
  parameter: string;
  operator: string;
  value: number | string;
  description?: string;
}

// 反例搜索請求格式
interface NegativeCaseRequest {
  negative_conditions: unknown[];
  negative_ratio: number;
  enable_time_separation: boolean;
  time_separation_days: number;
  sampling_strategy: string;
}

class ApiClient {
  private baseUrl: string;

  constructor() {
    this.baseUrl = `${API_BASE_URL}${API_PREFIX}`;
  }

  // Generic fetch wrapper with error handling
  private async fetchApi<T>(
    endpoint: string, 
    options: RequestInit = {},
    timeout: number = 30000  // 30秒超時
  ): Promise<ApiResponse<T>> {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeout);

    try {
      const response = await fetch(`${this.baseUrl}${endpoint}`, {
        ...options,
        signal: controller.signal,
        headers: {
          'Content-Type': 'application/json',
          ...options.headers,
        },
      });

      clearTimeout(timeoutId);
      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error?.message || `HTTP ${response.status}: Request failed`);
      }

      return data;
    } catch (error: unknown) {
      clearTimeout(timeoutId);

      if (error.name === 'AbortError') {
        throw new Error('請求超時，請檢查網路連接');
      }

      console.error('API Error:', error);
      throw error;
    }
  }

  // 轉換前端搜索請求為後端格式
  private convertToSearchConfig(
    request: SearchRequest,
    operators: {
      priceChange: string;
      volumeMultiplier: string;
      closingStrength: string;
      takerBuyRatio: string;
      pricePosition: string;
    },
    rangeValues: {
      priceChange: { min: number | null, max: number | null };
      volumeMultiplier: { min: number | null, max: number | null };
      closingStrength: { min: number | null, max: number | null };
      takerBuyRatio: { min: number | null, max: number | null };
      pricePosition: { min: number | null, max: number | null };
    }
  ): SearchConfigRequest {
    const conditions: FilterConditionRequest[] = [];

    // 1. 價格變化條件 (已修復)
    if (operators.priceChange === 'BETWEEN' && 
        rangeValues.priceChange.min !== null && 
        rangeValues.priceChange.max !== null) {
      conditions.push({
        condition_type: "price",
        parameter: "price_change",
        operator: "between",
        value: [rangeValues.priceChange.min / 100, rangeValues.priceChange.max / 100],
        description: `價格變化介於 ${rangeValues.priceChange.min}% 到 ${rangeValues.priceChange.max}%`
      });
    } else if (request.priceChange !== null && request.priceChange !== undefined) {
      conditions.push({
        condition_type: "price",
        parameter: "price_change",
        operator: operators.priceChange,  // 動態運算符
        value: request.priceChange / 100,
        description: `價格變化 ${operators.priceChange} ${request.priceChange}%`
      });
    }

    // 2. 成交量倍數條件 (新修復)
    if (operators.volumeMultiplier === 'BETWEEN' && 
        rangeValues.volumeMultiplier.min !== null && 
        rangeValues.volumeMultiplier.max !== null) {
      conditions.push({
        condition_type: "volume",
        parameter: "volume_multiplier",
        operator: "between",
        value: [rangeValues.volumeMultiplier.min, rangeValues.volumeMultiplier.max],
        description: `成交量倍數介於 ${rangeValues.volumeMultiplier.min} 到 ${rangeValues.volumeMultiplier.max}`
      });
    } else if (request.volumeMultiplier !== null && request.volumeMultiplier !== undefined) {
      conditions.push({
        condition_type: "volume",
        parameter: "volume_multiplier",
        operator: operators.volumeMultiplier,  // 修復：使用動態運算符
        value: request.volumeMultiplier,
        description: `成交量倍數 ${operators.volumeMultiplier} ${request.volumeMultiplier}`
      });
    }

    // 3. 收盤強度條件 (新修復)
    if (operators.closingStrength === 'BETWEEN' && 
        rangeValues.closingStrength.min !== null && 
        rangeValues.closingStrength.max !== null) {
      conditions.push({
        condition_type: "price",
        parameter: "closing_strength",
        operator: "between",
        value: [rangeValues.closingStrength.min, rangeValues.closingStrength.max],
        description: `收盤強度介於 ${rangeValues.closingStrength.min} 到 ${rangeValues.closingStrength.max}`
      });
    } else if (request.closingStrength !== null && request.closingStrength !== undefined) {
      conditions.push({
        condition_type: "price",
        parameter: "closing_strength",
        operator: operators.closingStrength,  // 修復：使用動態運算符
        value: request.closingStrength,
        description: `收盤強度 ${operators.closingStrength} ${request.closingStrength}`
      });
    }

    // 4. 主動買入比例條件 (新修復)
    if (operators.takerBuyRatio === 'BETWEEN' && 
        rangeValues.takerBuyRatio.min !== null && 
        rangeValues.takerBuyRatio.max !== null) {
      conditions.push({
        condition_type: "volume",
        parameter: "taker_buy_ratio",
        operator: "between",
        value: [rangeValues.takerBuyRatio.min, rangeValues.takerBuyRatio.max],
        description: `主動買入比例介於 ${rangeValues.takerBuyRatio.min} 到 ${rangeValues.takerBuyRatio.max}`
      });
    } else if (request.takerBuyRatio !== null && request.takerBuyRatio !== undefined) {
      conditions.push({
        condition_type: "volume",
        parameter: "taker_buy_ratio",
        operator: operators.takerBuyRatio,  // 修復：使用動態運算符
        value: request.takerBuyRatio,
        description: `主動買入比例 ${operators.takerBuyRatio} ${request.takerBuyRatio}`
      });
    }

    // 5. 價格位置條件 (新修復)
    if (operators.pricePosition === 'BETWEEN' && 
        rangeValues.pricePosition.min !== null && 
        rangeValues.pricePosition.max !== null) {
      conditions.push({
        condition_type: "price",
        parameter: "price_position",
        operator: "between",
        value: [rangeValues.pricePosition.min, rangeValues.pricePosition.max],
        description: `價格位置介於 ${rangeValues.pricePosition.min} 到 ${rangeValues.pricePosition.max}`
      });
    } else if (request.pricePosition !== null && request.pricePosition !== undefined) {
      conditions.push({
        condition_type: "price",
        parameter: "price_position",
        operator: operators.pricePosition,  // 修復：使用動態運算符
        value: request.pricePosition,
        description: `價格位置 ${operators.pricePosition} ${request.pricePosition}`
      });
    }

    // 添加debug log來確認時間數據
    console.log('convertToSearchConfig 接收到的request:', request);
    console.log('  - startDate:', request.startDate);
    console.log('  - endDate:', request.endDate);
    console.log('  - priceChangeMethod:', request.priceChangeMethod);

    return {
      name: request.name || `搜索_${new Date().toISOString().slice(0, 19)}`,
      timeframe: request.timeframe || "12h",
      initial_conditions: conditions,
      symbols: request.symbols,
      save_results: request.saveResults || false,
      // ✅ 修復：添加時間範圍字段
      startDate: request.startDate || null,
      endDate: request.endDate || null,
      // ✅ 新增：傳遞價格計算方式
      price_change_method: request.priceChangeMethod || "CLOSE_TO_CLOSE"
    };
  }

